char *
string_sprintf(const char *fmt, ...)
{
	va_list ap;
	char *buf = NULL;

	va_start(ap, fmt);
	if (vasprintf(&buf, fmt, ap) < 0)
		buf = NULL;
	va_end(ap);
	return buf;
}

void
string_ncopy_do(char *dst, size_t dstlen, const char *src, size_t srclen)
{
	if (srclen > dstlen - 1)
		srclen = dstlen - 1;
	memmove(dst, src, srclen);
	dst[srclen] = 0;
}

bool
string_nformat(char *buf, size_t bufsize, size_t *bufpos, const char *fmt, ...)
{
	size_t pos = bufpos ? *bufpos : 0;
	int retval;
	va_list args;

	if (pos >= bufsize)
		return false;
	va_start(args, fmt);
	retval = vsnprintf(buf + pos, bufsize - pos, fmt, args);
	va_end(args);

	if (bufpos && retval > 0)
		*bufpos = pos + retval;

	return pos + retval < bufsize && retval >= 0;
}

char *
string_trim_end(char *name)
{
	int namelen = strlen(name) - 1;

	while (namelen > 0 && isspace((unsigned char) name[namelen]))
		name[namelen--] = 0;

	return name;
}

char *
string_trim(char *name)
{
	while (isspace((unsigned char) *name))
		name++;

	return string_trim_end(name);
}

bool
string_isnumber(const char *str)
{
	int pos;

	for (pos = 0; str[pos]; pos++) {
		if (!isdigit((unsigned char) str[pos]))
			return false;
	}

	return pos > 0;
}

bool
iscommit(const char *str)
{
	int pos;

	for (pos = 0; str[pos]; pos++) {
		if (!isxdigit((unsigned char) str[pos]))
			return false;
	}

	return 7 <= pos && pos < SIZEOF_REV;
}

int
suffixcmp(const char *str, int slen, const char *suffix)
{
	size_t len = slen >= 0 ? slen : strlen(str);
	size_t suffixlen = strlen(suffix);

	return suffixlen < len ? strcmp(str + len - suffixlen, suffix) : -1;
}

int
count_digits(unsigned long i)
{
	int digits;

	for (digits = 0; i; digits++)
		i /= 10;
	return digits;
}

unsigned long
string_hash(const char *str)
{
	unsigned long hash = 0;

	while (*str)
		hash = (hash * 31) + (unsigned char) *str++;
	return hash;
}

size_t
string_expand(char *dst, size_t dstlen, const char *src, int srclen, int tabsize)
{
	size_t size, pos;

	for (size = pos = 0; size < dstlen - 1 && (srclen == -1 || pos < (size_t) srclen) && src[pos]; pos++) {
		const char c = src[pos];

		if (c == '\t') {
			size_t expanded = tabsize - (size % tabsize);

			if (expanded + size >= dstlen - 1)
				expanded = dstlen - size - 1;
			memcpy(dst + size, "                                                                                ", expanded);
			size += expanded;
		} else if (c == '\r') {
			/* skip */
		} else {
			dst[size++] = c;
		}
	}

	dst[size] = 0;
	return pos;
}

int
string_enum_compare(const char *str1, const char *str2, int len)
{
	size_t i;

#define string_enum_sep(x) ((x) == '-' || (x) == '_' || (x) == '.')

	/* Diff-Header == DIFF_HEADER */
	for (i = 0; i < (size_t) len; i++) {
		if (string_enum_sep(str1[i]) && string_enum_sep(str2[i]))
			continue;

		if (toupper((unsigned char) str1[i]) == toupper((unsigned char) str2[i]))
			continue;

		return str1[i] - str2[i];
	}

	return 0;
}

char *
enum_name(const char *name)
{
	static char buf[SIZEOF_STR];
	size_t i;

	for (i = 0; name[i] && i < sizeof(buf) - 1; i++) {
		buf[i] = name[i] == '_' ? '-' : tolower((unsigned char) name[i]);
	}
	buf[i] = 0;
	return buf;
