unsigned char
utf8_char_length(const char *string)
{
	int c = *(unsigned char *) string;

	return utf8_bytes[c];
}

unsigned long
utf8_to_unicode(const char *string, size_t length)
{
	unsigned long unicode;

	switch (length) {
	case 1:
		unicode  =   string[0];
		break;
	case 2:
		unicode  =  (string[0] & 0x1f) << 6;
		unicode +=  (string[1] & 0x3f);
		break;
	case 3:
		unicode  =  (string[0] & 0x0f) << 12;
		unicode += ((string[1] & 0x3f) << 6);
		unicode +=  (string[2] & 0x3f);
		break;
	case 4:
		unicode  =  (string[0] & 0x0f) << 18;
		unicode += ((string[1] & 0x3f) << 12);
		unicode += ((string[2] & 0x3f) << 6);
		unicode +=  (string[3] & 0x3f);
		break;
	case 5:
		unicode  =  (string[0] & 0x0f) << 24;
		unicode += ((string[1] & 0x3f) << 18);
		unicode += ((string[2] & 0x3f) << 12);
		unicode += ((string[3] & 0x3f) << 6);
		unicode +=  (string[4] & 0x3f);
		break;
	case 6:
		unicode  =  (string[0] & 0x01) << 30;
		unicode += ((string[1] & 0x3f) << 24);
		unicode += ((string[2] & 0x3f) << 18);
		unicode += ((string[3] & 0x3f) << 12);
		unicode += ((string[4] & 0x3f) << 6);
		unicode +=  (string[5] & 0x3f);
		break;
	default:
		return 0;
	}

	/* Invalid characters could return the special 0xfffd value but NUL
	 * should be just as good. */
	return unicode > 0xffff ? 0 : unicode;
}

int
unicode_width(unsigned long c, int tab_size)
{
	if (c >= 0x1100 &&
	   (c <= 0x115f				/* Hangul Jamo */
	    || c == 0x2329
	    || c == 0x232a
	    || (c >= 0x2e80  && c <= 0xa4cf && c != 0x303f)
						/* CJK ... Yi */
	    || (c >= 0xac00  && c <= 0xd7a3)	/* Hangul Syllables */
	    || (c >= 0xf900  && c <= 0xfaff)	/* CJK Compatibility Ideographs */
	    || (c >= 0xfe30  && c <= 0xfe6f)	/* CJK Compatibility Forms */
	    || (c >= 0xff00  && c <= 0xff60)	/* Fullwidth Forms */
	    || (c >= 0xffe0  && c <= 0xffe6)
	    || (c >= 0x20000 && c <= 0x2fffd)
	    || (c >= 0x30000 && c <= 0x3fffd)))
		return 2;

	if (c == '\t')
		return tab_size;

	return 1;
}

/* Calculate how much of string can be shown within the given maximum width
 * and sets trimmed parameter to non-zero value if all of string could not be
 * shown. If the reserve flag is true, it will reserve at least one
 * trailing character, which can be useful when drawing a delimiter.
 *
 * Returns the number of bytes to output from string to satisfy max_width. */
size_t
utf8_length(const char **start, int max_chars, size_t skip, int *width, int max_width, int *trimmed, bool reserve, int tab_size)
{
	const char *string = *start;
	const char *end = max_chars < 0 ? strchr(string, '\0') : string + max_chars;
	unsigned char last_bytes = 0;
	size_t last_ucwidth = 0;

	*width = 0;
	*trimmed = 0;

	while (string < end) {
		unsigned char bytes = utf8_char_length(string);
		size_t ucwidth;
		unsigned long unicode;

		if (string + bytes > end)
			break;

		/* Change representation to figure out whether
		 * it is a single- or double-width character. */

		unicode = utf8_to_unicode(string, bytes);
		/* FIXME: Graceful handling of invalid Unicode character. */
		if (!unicode)
			break;

		ucwidth = unicode_width(unicode, tab_size);
		if (skip > 0) {
			skip -= ucwidth <= skip ? ucwidth : skip;
			*start += bytes;
		}
		*width  += ucwidth;
		if (max_width > 0 && *width > max_width) {
			*trimmed = 1;
			*width -= ucwidth;
			if (reserve && *width == max_width) {
				string -= last_bytes;
				*width -= last_ucwidth;
			}
			break;
		}

		string  += bytes;
		if (ucwidth) {
			last_bytes = bytes;
			last_ucwidth = ucwidth;
		} else {
			last_bytes += bytes;
		}
	}

	return string - *start;
}

int
utf8_width_of(const char *text, int max_bytes, int max_width)
{
	int text_width = 0;
	const char *tmp = text;
	int trimmed = false;

	utf8_length(&tmp, max_bytes, 0, &text_width, max_width, &trimmed, false, 1);
	return text_width;
}

/* ------------------------------------------------------------------ */
/* Encoding */

iconv_t opt_iconv_out = (iconv_t) -1;

const char *
encoding_convert_out(const char *str, size_t len, size_t *outlen)
{
	static char *outbuf;
	static size_t outbufsize;
	char *inbuf = (char *) str;
	size_t inlen = len;
	char *out;
	size_t outleft;

	if (opt_iconv_out == (iconv_t) -1) {
		*outlen = len;
		return str;
	}

	if (outbufsize < len * 8 + 16) {
		outbufsize = len * 8 + 16;
		outbuf = xrealloc(outbuf, outbufsize);
	}
	out = outbuf;
	outleft = outbufsize;
	iconv(opt_iconv_out, NULL, NULL, NULL, NULL);
	while (inlen > 0) {
		size_t ret = iconv(opt_iconv_out, &inbuf, &inlen, &out, &outleft);
		if (ret == (size_t) -1) {
			if (errno == E2BIG)
				break;
			/* skip invalid byte */
			if (outleft > 0) {
				*out++ = '?';
				outleft--;
			}
			inbuf++;
			inlen--;
		}
	}
	*outlen = out - outbuf;
	return outbuf;
}

/* ------------------------------------------------------------------ */
/* argv helpers */

size_t
argv_size(const char **argv)
{
	int argc = 0;

	while (argv && argv[argc])
		argc++;

	return argc;
}

bool
argv_contains(const char **argv, const char *arg)
{
	size_t i;

	for (i = 0; argv && argv[i]; i++)
		if (!strcmp(argv[i], arg))
			return true;
	return false;
}

bool
argv_append(const char ***argv, const char *arg)
{
	size_t argc = argv_size(*argv);

	*argv = xrealloc((void *) *argv, sizeof(char *) * (argc + 2));
	(*argv)[argc++] = xstrdup(arg);
	(*argv)[argc] = NULL;
	return true;
}

bool
argv_append_array(const char ***dst_argv, const char *src_argv[])
{
	int i;

	for (i = 0; src_argv && src_argv[i]; i++)
		if (!argv_append(dst_argv, src_argv[i]))
			return false;
	return true;
}

void
argv_free(const char *argv[])
{
	int argc;

	if (!argv)
		return;
	for (argc = 0; argv[argc]; argc++)
		free((void *) argv[argc]);
	argv[0] = NULL;
}

bool
argv_copy(const char ***dst, const char *src[])
{
	int argc;

	argv_free(*dst);
	for (argc = 0; src[argc]; argc++)
		if (!argv_append(dst, src[argc]))
			return false;
	return true;
}

static bool
concat_argv(const char *argv[], char *buf, size_t buflen, const char *sep, bool quoted)
{
	size_t bufpos, argc;

	for (bufpos = 0, argc = 0; argv[argc]; argc++) {
		const char *arg_sep = argc ? sep : "";
		const char *arg = argv[argc];

		if (quoted && arg[strcspn(arg, " \t\"")]) {
			if (!string_nformat(buf, buflen, &bufpos, "%s\"%s\"", arg_sep, arg))
				return false;
		} else if (!string_nformat(buf, buflen, &bufpos, "%s%s", arg_sep, arg))
			return false;
	}

	return true;
}

char *
argv_to_string_alloc(const char *argv[], const char *sep)
{
	static char buf[SIZEOF_MED_STR];

	buf[0] = 0;
	if (argv)
		concat_argv(argv, buf, sizeof(buf), sep, false);
	return buf;
}

static char *
parse_arg(char **cmd, bool remove_quotes)
{
	int quote = 0;
	char *arg = *cmd;
	char *next, *pos;

	for (pos = next = arg; *pos; pos++) {
		int c = *pos;

		if (c == '"' || c == '\'') {
			if (quote == c) {
				quote = 0;
				if (remove_quotes) {
					if (pos == arg) {
						arg++;
						next++;
					}
					continue;
				}

			} else if (!quote) {
				quote = c;
				if (remove_quotes) {
					if (pos == arg) {
						arg++;
						next++;
					}
					continue;
				}
			}

		} else if (quote == '"' && c == '\\' && pos[1]) {
			if (remove_quotes) {
				pos++;
				c = *pos;
			} else {
				*next++ = *pos++;
				c = *pos;
			}

		} else if (!quote && isspace((unsigned char) c)) {
			break;
		}

		*next++ = c;
	}

	if (*pos)
		*cmd = pos + 1;
	else
		*cmd = pos;
	*next = 0;
	while (isspace((unsigned char) **cmd))
		(*cmd)++;
	return arg;
}

static bool
argv_from_string_do(const char *argv[SIZEOF_ARG], int *argc, char *cmd, bool remove_quotes)
{
	while (isspace((unsigned char) *cmd))
		cmd++;

	while (*cmd && *argc < SIZEOF_ARG) {
		char *arg = parse_arg(&cmd, remove_quotes);

		argv[(*argc)++] = arg;
	}

	if (*argc < SIZEOF_ARG)
		argv[*argc] = NULL;
	return *argc < SIZEOF_ARG;
}

bool
argv_from_string_no_quotes(const char *argv[SIZEOF_ARG], int *argc, char *cmd)
{
	return argv_from_string_do(argv, argc, cmd, false);
}

bool
argv_from_string(const char *argv[SIZEOF_ARG], int *argc, char *cmd)
{
	return argv_from_string_do(argv, argc, cmd, true);
}

bool
argv_parse_rev_flag(const char *arg)
{
	static const char *with_arg[] = {
		"--after=", "--before=", "--since=", "--until=", "--max-age=", "--min-age=",
		"--max-count=", "--skip=", "--author=", "--committer=", "--grep=",
		"--grep-reflog=", "--branches=", "--tags=", "--remotes=", "--glob=",
		"--exclude=", "--min-parents=", "--max-parents=", "--decorate-refs=",
		"--decorate-refs-exclude=",
	};
	static const char *no_arg[] = {
		"--all", "--alternate-refs", "--ancestry-path", "--author-date-order",
		"--basic-regexp", "--bisect", "--boundary", "--branches", "--cherry",
		"--cherry-mark", "--cherry-pick", "--date-order", "--dense",
		"--exclude-first-parent-only", "--extended-regexp", "--first-parent",
		"--fixed-strings", "--full-history", "--ignore-missing", "--invert-grep",
		"--left-only", "--merge", "--merges", "--no-max-parents",
		"--no-merges", "--no-min-parents", "--no-walk", "--not", "--perl-regexp",
		"--reflog", "--regexp-ignore-case", "--remove-empty", "--remotes",
		"--reverse", "--right-only", "--simplify-by-decoration",
		"--simplify-merges", "--single-worktree", "--sparse", "--stdin",
		"--tags", "--topo-order", "--use-mailmap", "--walk-reflogs",
		"-E", "-F", "-P", "-g", "-i",
	};
	size_t i;

	for (i = 0; i < ARRAY_SIZE(with_arg); i++)
		if (!prefixcmp(arg, with_arg[i]))
			return true;
	for (i = 0; i < ARRAY_SIZE(no_arg); i++)
		if (!strcmp(arg, no_arg[i]))
			return true;
	if (!prefixcmp(arg, "-n") && arg[2] && string_isnumber(arg + 2))
		return true;
	if (arg[0] == '-' && arg[1] && string_isnumber(arg + 1))
		return true;
	if (!prefixcmp(arg, "--no-walk="))
		return true;
	return false;
}

/* ------------------------------------------------------------------ */
/* Dates and identities */

const struct ident unknown_ident = { "Unknown", "unknown@localhost" };

struct ident_entry {
	struct ident ident;
	struct ident_entry *next;
};

static struct ident_entry *idents[256];

const struct ident *
get_author(const char *name, const char *email)
{
	unsigned long hash = (string_hash(name) * 7 + string_hash(email)) % ARRAY_SIZE(idents);
	struct ident_entry *e;

	for (e = idents[hash]; e; e = e->next)
		if (!strcmp(e->ident.name, name) && !strcmp(e->ident.email, email))
			return &e->ident;
	e = xcalloc(1, sizeof(*e));
	e->ident.name = xstrdup(name);
	e->ident.email = xstrdup(email);
	e->next = idents[hash];
	idents[hash] = e;
	return &e->ident;
}

void
parse_timesec(struct time *time, const char *sec)
{
	time->sec = (time_t) atol(sec);
}

void
parse_timezone(struct time *time, const char *zone)
{
	long tz;

	tz  = ('0' - zone[1]) * 60 * 60 * 10;
	tz += ('0' - zone[2]) * 60 * 60;
	tz += ('0' - zone[3]) * 60 * 10;
	tz += ('0' - zone[4]) * 60;

	if (zone[0] == '-')
		tz = -tz;

	time->tz = tz;
	time->sec -= tz;
}

/* Parse author lines where the name may be empty:
 *	author  <email@address.tld> 1138474660 +0100
 */
void
parse_author_line(char *ident, const struct ident **author, struct time *time)
{
	char *nameend = strchr(ident, '<');
	char *emailend = strchr(ident, '>');
	const char *name, *email = "";

	if (nameend && emailend)
		*nameend = *emailend = 0;
	name = string_trim(ident);
	if (nameend)
		email = string_trim(nameend + 1);
	if (!*name)
		name = *email ? email : unknown_ident.name;
	if (!*email)
		email = *name ? name : unknown_ident.email;

	*author = get_author(name, email);

	/* Parse epoch and timezone */
	if (time && emailend && emailend[1] == ' ') {
		char *secs = emailend + 2;
		char *zone = strchr(secs, ' ');

		parse_timesec(time, secs);

		if (zone && strlen(zone) == STRING_SIZE(" +0700"))
			parse_timezone(time, zone + 1);
	}
}

static const struct {
	const char *name;
	const char *compact_symbol;
	time_t in_seconds;
} reldate[] = {
	{ "second", "s", 1 },
	{ "minute", "m", 60 },
	{ "hour",   "h", 60 * 60 },
	{ "day",    "D", 24 * 60 * 60 },
	{ "week",   "W", 7 * 24 * 60 * 60 },
	{ "month",  "M", 30 * 24 * 60 * 60 },
	{ "year",   "Y", 365 * 24 * 60 * 60 },
};

static const char *
get_relative_date(const struct time *time, char *buf, size_t buflen, bool compact)
{
	struct timeval now;
	time_t timestamp = time->sec + time->tz;
	time_t seconds;
	size_t i;

	if (gettimeofday(&now, NULL))
		return "";

	{
		struct tm tm;
		time_t t = now.tv_sec;
		localtime_r(&t, &tm);
		now.tv_sec += tm.tm_gmtoff;
	}

	seconds = now.tv_sec < timestamp ? timestamp - now.tv_sec : now.tv_sec - timestamp;

	for (i = 0; i < ARRAY_SIZE(reldate); i++) {
		if (i + 1 < ARRAY_SIZE(reldate) && seconds >= reldate[i + 1].in_seconds)
			continue;

		seconds /= reldate[i].in_seconds;
		if (compact) {
			if (!string_nformat(buf, buflen, NULL, "%s%ld%s",
					    now.tv_sec >= timestamp ? "" : "-",
					    (long) seconds, reldate[i].compact_symbol))
				return "";

		} else if (!string_nformat(buf, buflen, NULL, "%ld %s%s %s",
					   (long) seconds, reldate[i].name,
					   seconds > 1 ? "s" : "",
					   now.tv_sec >= timestamp ? "ago" : "ahead"))
			return "";

		return buf;
	}

	return "";
}

const char *
mkdate(const struct time *time, int date, bool local, const char *custom_format)
{
	static char buf[SIZEOF_STR];
	struct tm tm;
	const char *format;
	bool is_local = local;

	if (!date || !time || !time->sec)
		return "";

	if (date == DATE_RELATIVE || date == DATE_RELATIVE_COMPACT)
		return get_relative_date(time, buf, sizeof(buf),
					 date == DATE_RELATIVE_COMPACT);

	format = (date == DATE_CUSTOM && custom_format && *custom_format)
	       ? custom_format : "%Y-%m-%d %H:%M %z";

	if (is_local) {
		time_t t = time->sec;
		localtime_r(&t, &tm);
	} else {
		time_t t = time->sec + time->tz;
		gmtime_r(&t, &tm);
		tm.tm_gmtoff = time->tz;
	}

	if (!is_local && strstr(format, "%z")) {
		/* Format %z manually since gmtime does not know the zone */
		char fmt[SIZEOF_STR];
		char zone[16];
		size_t pos = 0;
		const char *p;
		int tz = time->tz;
		char sign = tz >= 0 ? '+' : '-';

		if (tz < 0)
			tz = -tz;
		snprintf(zone, sizeof(zone), "%c%02d%02d", sign, tz / 3600, (tz % 3600) / 60);
		for (p = format; *p && pos < sizeof(fmt) - 8; p++) {
			if (p[0] == '%' && p[1] == 'z') {
				size_t zl = strlen(zone);
				memcpy(fmt + pos, zone, zl);
				pos += zl;
				p++;
			} else if (p[0] == '%' && p[1]) {
				fmt[pos++] = *p++;
				fmt[pos++] = *p;
			} else {
				fmt[pos++] = *p;
			}
		}
		fmt[pos] = 0;
		return strftime(buf, sizeof(buf), fmt, &tm) ? buf : "";
	}

	return strftime(buf, sizeof(buf), format, &tm) ? buf : "";
}

const char *
mkfilesize(unsigned long size, int format)
{
	static char buf[64 + 1];
	static const char relsize[] = {
		'B', 'K', 'M', 'G', 'T', 'P'
	};

	if (!format)
		return "";

	if (format == FILE_SIZE_UNITS) {
		const char *fmt = "%.0f%c";
		double rsize = size;
		size_t i;

		for (i = 1; i < ARRAY_SIZE(relsize); i++) {
			if (rsize < 1024)
				break;
			rsize /= 1024;
		}

		size = rsize * 10;
		if (size % 10 > 0)
			fmt = "%.1f%c";

		return string_format(buf, fmt, rsize, relsize[i - 1])
			? buf : NULL;
	}

	return string_format(buf, "%ld", size) ? buf : NULL;
}

const char *
mkmode(mode_t mode)
{
	if (S_ISDIR(mode))
		return "drwxr-xr-x";
	else if (S_ISLNK(mode))
		return "lrwxrwxrwx";
	else if (S_ISGITLINK(mode))
		return "m---------";
	else if (S_ISREG(mode) && mode & S_IXUSR)
		return "-rwxr-xr-x";
	else if (S_ISREG(mode))
		return "-rw-r--r--";
	else
		return "----------";
}

static const char *
get_author_initials(const char *author)
{
	static char initials[256];
	size_t pos = 0;
	const char *end = strchr(author, '\0');

#define is_initial_sep(c) (isspace((unsigned char)(c)) || ispunct((unsigned char)(c)) || (c) == '@' || (c) == '-')

	memset(initials, 0, sizeof(initials));
	while (author < end) {
		unsigned char bytes;
		size_t i;

		while (author < end && is_initial_sep(*author))
			author++;

		bytes = utf8_char_length(author);
		if (bytes >= sizeof(initials) - 1 - pos)
			break;
		while (bytes--) {
			initials[pos++] = *author++;
		}

		i = pos;
		while (author < end && !is_initial_sep(*author)) {
			bytes = utf8_char_length(author);
			if (bytes >= sizeof(initials) - 1 - i) {
				while (author < end && !is_initial_sep(*author))
					author++;
				break;
			}
			while (bytes--) {
				initials[i++] = *author++;
			}
		}

		initials[i++] = 0;
	}

	return initials;
}

static const char *
get_email_user(const char *email)
{
	static char user[SIZEOF_STR + 1];
	const char *end = strchr(email, '@');
	int length = end ? end - email : (int) strlen(email);

	string_format(user, "%.*s%c", length, email, 0);
	return user;
}

const char *
mkauthor(const struct ident *ident, int cols, int author)
{
	bool trim = cols > 0 && cols <= 10? true : false;

	if (author == AUTHOR_NO || !ident)
		return "";
	if (author == AUTHOR_EMAIL && ident->email)
		return ident->email;
	if (author == AUTHOR_EMAIL_USER && ident->email)
		return get_email_user(ident->email);
	if (author == AUTHOR_ABBREVIATED || trim)
		return get_author_initials(ident->name);
	return ident->name;
}
