	time_t in_seconds;
	time_t limit;
} reldate[] = {
	{ "second", "s", 1,			120 },
	{ "minute", "m", 60,			7200 },
	{ "hour",   "h", 60 * 60,		172800 },
	{ "day",    "D", 24 * 60 * 60,		1209600 },
	{ "week",   "W", 7 * 24 * 60 * 60,	3024000 },
	{ "month",  "M", 30 * 24 * 60 * 60,	31536000 },
	{ "year",   "Y", 365 * 24 * 60 * 60,	0 },
};

bool
time_now(struct timeval *tv)
{
	static bool checked;
	static long fixed;

	if (!checked) {
		const char *env = getenv("TEST_TIME_NOW");

		checked = true;
		if (env && *env)
			fixed = atol(env);
	}

	if (fixed) {
		tv->tv_sec = fixed;
		tv->tv_usec = 0;
		return true;
	}
	return gettimeofday(tv, NULL) == 0;
}

static const char *
get_relative_date(const struct time *time, char *buf, size_t buflen, bool compact)
{
	struct timeval now;
	time_t timestamp = time->sec;
	time_t seconds;
	size_t i;

	if (!time_now(&now))
		return "";

	seconds = now.tv_sec < timestamp ? timestamp - now.tv_sec : now.tv_sec - timestamp;

	for (i = 0; i < ARRAY_SIZE(reldate); i++) {
		if (reldate[i].limit && seconds >= reldate[i].limit)
			continue;

		seconds /= reldate[i].in_seconds;
		if (compact) {
			if (!string_nformat(buf, buflen, NULL, "%s%ld%s",
					    now.tv_sec >= timestamp ? "" : "-",
					    (long) seconds, reldate[i].compact_symbol))
				return "";

		} else if (!string_nformat(buf, buflen, NULL, "%ld %s%s %s",
					   (long) seconds, reldate[i].name,
					   seconds > 1 ? "s" : "",
					   now.tv_sec >= timestamp ? "ago" : "ahead"))
			return "";

		return buf;
	}

	return "";
}

const char *
mkdate(const struct time *time, int date, bool local, const char *custom_format)
{
	static char buf[SIZEOF_STR];
	static char zone[16];
	struct tm tm;
	const char *format;

	if (!date || !time || !time->sec)
		return "";

	if (date == DATE_RELATIVE || date == DATE_RELATIVE_COMPACT)
		return get_relative_date(time, buf, sizeof(buf),
					 date == DATE_RELATIVE_COMPACT);

	if (date == DATE_CUSTOM && custom_format && *custom_format)
		format = custom_format;
	else
		format = local ? "%Y-%m-%d %H:%M" : "%Y-%m-%d %H:%M %z";

	if (local) {
		time_t t = time->sec;
		localtime_r(&t, &tm);
	} else {
		time_t t = time->sec + time->tz;
		int tz = time->tz < 0 ? -time->tz : time->tz;

		gmtime_r(&t, &tm);
		tm.tm_gmtoff = time->tz;
		snprintf(zone, sizeof(zone), "%c%02d%02d", time->tz < 0 ? '-' : '+', tz / 3600, (tz % 3600) / 60);
		tm.tm_zone = zone;
	}

	return strftime(buf, sizeof(buf), format, &tm) ? buf : "";
}

