static int
get_key_value_by_name(const char *name, int namelen)
{
	size_t i;

	for (i = 0; i < ARRAY_SIZE(key_mappings); i++)
		if ((int) strlen(key_mappings[i].name) == namelen &&
		    !strncasecmp(key_mappings[i].name, name, namelen))
			return key_mappings[i].value;

	return ERR;
}

static void
key_set_value(struct key *key, int value)
{
	if (value > 0 && value < 0x80 && isprint(value)) {
		key->bytes[0] = value;
		key->bytes[1] = 0;
		key->value = 0;
	} else {
		key->value = value;
		key->bytes[0] = 0;
	}
}

enum status_code
get_key_value(const char **name_ptr, struct key *key)
{
	const char *name = *name_ptr;
	const char *end = NULL;

	memset(key, 0, sizeof(*key));

	if (*name == '<') {
		end = strchr(name + 1, '>');
		if (!end)
			return error("Missing '>' from key mapping: %s", name);

		if (!prefixcmp(name, "<Ctrl-")) {
			const char *start = name + STRING_SIZE("<Ctrl-");

			if (end - start == 1) {
				key->control = true;
				key->value = tolower((unsigned char) *start);
				*name_ptr = end + 1;
				return SUCCESS;
			}

			return error("Invalid key mapping: %.*s", (int) (end - name + 1), name);

		} else if (!prefixcmp(name, "<Esc>") && name[5]) {
			const char *rest = name + 5;
			enum status_code code;

			code = get_key_value(&rest, key);
			if (code != SUCCESS)
				return code;
			key->escape = true;
			*name_ptr = rest;
			return SUCCESS;

		} else {
			int value = get_key_value_by_name(name + 1, end - name - 1);

			if (value != ERR) {
				key_set_value(key, value);
				*name_ptr = end + 1;
				return SUCCESS;
			}

			return error("Unknown key mapping: %.*s", (int) (end - name + 1), name);
		}
	}

	{
		int len = utf8_char_length(name);

		if (len > (int) sizeof(key->bytes) - 1)
			len = sizeof(key->bytes) - 1;
		string_ncopy_do(key->bytes, sizeof(key->bytes), name, len);
		*name_ptr = name + len;
		if (!*key->bytes)
			return error("Empty key");
	}

	return SUCCESS;
}

static const char *
get_key_mapping_name(int value)
{
	size_t i;

	for (i = 0; i < ARRAY_SIZE(key_mappings); i++)
		if (key_mappings[i].value == value)
			return key_mappings[i].name;
	return NULL;
}

const char *
get_key_name(const struct key key[], size_t keys, bool quote_comma)
{
	static char buf[SIZEOF_STR];
	size_t pos = 0;
	size_t i;

	buf[0] = 0;
	for (i = 0; i < keys; i++) {
		const char *name = key[i].bytes;
		const char *start = "";
		const char *end = "";
		char tmp[16];

		if (key[i].escape) {
			if (!string_format_from(buf, &pos, "<Esc>"))
				return "(no key)";
		}

		if (key[i].control) {
			snprintf(tmp, sizeof(tmp), "%c", toupper(key[i].value));
			name = tmp;
			start = "<Ctrl-";
			end = ">";
		} else if (*name) {
			bool use_symbolic = *name == ' ';

			if (*name == ',' && quote_comma) {
				start = "'";
				end = "'";
			}
			if (!quote_comma && (*name == '<' || *name == '#'))
				use_symbolic = true;
			if (use_symbolic) {
				const char *sym = get_key_mapping_name(*name);

				if (sym) {
					name = sym;
					start = "<";
					end = ">";
				}
			}
		} else {
			const char *sym = get_key_mapping_name(key[i].value);

			if (sym) {
				name = sym;
				start = "<";
				end = ">";
			} else {
				snprintf(tmp, sizeof(tmp), "%d", key[i].value);
				name = tmp;
			}
		}

		if (!string_format_from(buf, &pos, "%s%s%s", start, name, end))
			return "(no key)";
	}

	return buf;
}

bool
key_equal(const struct key *a, const struct key *b)
{
	return a->value == b->value && a->control == b->control &&
	       a->escape == b->escape && !strcmp(a->bytes, b->bytes);
}

/* ------------------------------------------------------------------ */
/* Keymaps */

static struct keymap keymaps[32];
static int keymaps_count;
struct keymap *generic_keymap;
struct keymap *search_keymap;
struct keymap *toggle_keymap;

struct keymap *
get_keymap_by_index(int i)
{
	return i < keymaps_count ? &keymaps[i] : NULL;
}

int
get_keymaps_count(void)
{
	return keymaps_count;
}

struct keymap *
add_keymap(const char *name)
{
	struct keymap *km = &keymaps[keymaps_count++];

	memset(km, 0, sizeof(*km));
	km->name = name;
	if (!strcmp(name, "generic"))
		generic_keymap = km;
	else if (!strcmp(name, "search"))
		search_keymap = km;
	else if (!strcmp(name, "toggle"))
		toggle_keymap = km;
	return km;
}

struct keymap *
get_keymap(const char *name, size_t namelen)
{
	int i;

	for (i = 0; i < keymaps_count; i++)
		if (strlen(keymaps[i].name) == namelen &&
		    !strncasecmp(keymaps[i].name, name, namelen))
			return &keymaps[i];

	return NULL;
}

static bool
keybinding_equals(const struct keybinding *kb, const struct key key[], size_t keys)
{
	int i;

	if (kb->keys != (int) keys)
		return false;
	for (i = 0; i < kb->keys; i++)
		if (!key_equal(&kb->key[i], &key[i]))
			return false;
	return true;
}

static bool
keybinding_matches_prefix(const struct keybinding *kb, const struct key key[], size_t keys)
{
	size_t i;

	if (kb->keys < (int) keys)
		return false;
	for (i = 0; i < keys; i++)
		if (!key_equal(&kb->key[i], &key[i]))
			return false;
	return true;
}

static void
remove_binding(struct keymap *table, int i)
{
	memmove(&table->data[i], &table->data[i + 1], sizeof(*table->data) * (table->size - i - 1));
	table->size--;
}

enum status_code
add_keybinding(struct keymap *table, enum request request, const struct key key[], size_t keys)
{
	int i;

	for (i = 0; i < table->size; i++) {
		if (keybinding_equals(&table->data[i], key, keys)) {
			table->data[i].request = request;
			return SUCCESS;
		}
	}

	table->data = xrealloc(table->data, (table->size + 1) * sizeof(*table->data));
	memset(&table->data[table->size], 0, sizeof(table->data[0]));
	memcpy(table->data[table->size].key, key, sizeof(*key) * keys);
	table->data[table->size].keys = keys;
	table->data[table->size].request = request;
	table->size++;

	/* bind generic <key> none: unbind the key from all keymaps */
	if (request == REQ_NONE && table == generic_keymap) {
		int k;

		for (k = 0; k < keymaps_count; k++) {
			struct keymap *km = &keymaps[k];
			int j;

			if (km == generic_keymap)
				continue;
			for (j = 0; j < km->size; j++)
				if (keybinding_equals(&km->data[j], key, keys)) {
					km->data[j].request = REQ_NONE;
				}
		}
	}

	return SUCCESS;
}

enum request
get_keybinding(const struct keymap *keymap, const struct key key[], size_t keys, int *matches)
{
	int i;
	enum request request = REQ_UNKNOWN;
	int found = 0;

	for (i = 0; i < keymap->size; i++)
		if (keybinding_matches_prefix(&keymap->data[i], key, keys)) {
			found++;
			if (keymap->data[i].keys == (int) keys && request == REQ_UNKNOWN)
				request = keymap->data[i].request;
		}

	if (keymap != generic_keymap && generic_keymap) {
		for (i = 0; i < generic_keymap->size; i++)
			if (keybinding_matches_prefix(&generic_keymap->data[i], key, keys)) {
				found++;
				if (generic_keymap->data[i].keys == (int) keys && request == REQ_UNKNOWN)
					request = generic_keymap->data[i].request;
			}
	}

	if (matches)
		*matches = found;
	return request;
}

/* Returns a comma separated list of key names bound to request. */
const char *
get_keys(const struct keymap *keymap, enum request request, bool all)
{
	static char buf[SIZEOF_STR];
	size_t pos = 0;
	const char *sep = "";
	int i;

	buf[0] = 0;
	for (i = 0; i < keymap->size; i++) {
		if (keymap->data[i].request == request) {
			const char *key = get_key_name(keymap->data[i].key, keymap->data[i].keys, all);

			if (!*key)
				continue;
			if (!string_format_from(buf, &pos, "%s%s", sep, key))
				return "Too many keybindings!";
			sep = ", ";
			if (!all)
				break;
		}
	}

	return buf;
}

/* ------------------------------------------------------------------ */
/* Run requests */

static struct run_request *run_requests;
static int run_requests_count;

struct run_request *
get_run_request(enum request request)
{
	if (request < REQ_RUN_REQUESTS || request > REQ_RUN_REQUESTS + run_requests_count)
		return NULL;
	return &run_requests[request - REQ_RUN_REQUESTS - 1];
}

enum status_code
parse_run_request_flags(struct run_request_flags *flags, const char **argv)
{
	if (!argv[0] || !argv[0][0])
		return SUCCESS;

	while (strchr("!?@<>+:", argv[0][0]) && argv[0][0]) {
		switch (argv[0][0]) {
		case '!':
			flags->echo? (void)0 : (void)0;
			break;
		case '@':
			flags->silent = true;
			break;
		case '?':
			flags->confirm = true;
			break;
		case '<':
			flags->exit = true;
			break;
		case '>':
			flags->quick = true;
			break;
		case '+':
			flags->echo = true;
			break;
		case ':':
			flags->internal = true;
			argv[0]++;
			return SUCCESS;
		}
		argv[0]++;
		if (!argv[0][0])
			break;
	}

	return SUCCESS;
}

enum status_code
add_run_request(struct keymap *keymap, const struct key key[], size_t keys, const char **argv)
{
	struct run_request *req;
	struct run_request_flags flags = {0};
	const char *first = argv[0];
	enum status_code code;
	const char **copy = NULL;

	code = parse_run_request_flags(&flags, argv);
	if (code != SUCCESS)
		return code;

	if (!argv_copy(&copy, argv)) {
		argv[0] = first;
		return ERROR_OUT_OF_MEMORY;
	}
	argv[0] = first;

	run_requests = xrealloc(run_requests, sizeof(*run_requests) * (run_requests_count + 1));
	req = &run_requests[run_requests_count++];
	memset(req, 0, sizeof(*req));
	req->flags = flags;
	req->keymap = keymap;
	req->argv = copy;

	return add_keybinding(keymap, REQ_RUN_REQUESTS + run_requests_count, key, keys);
}

const char *
format_run_request_flags(const struct run_request *req)
{
	static char flags[8];
	int flagspos = 0;

	memset(flags, 0, sizeof(flags));

	if (req->flags.internal)
		flags[flagspos++] = ':';
	else
		flags[flagspos] = '!'; /* Optional, if other flags are defined */

	if (req->flags.silent)
		flags[flagspos++] = '@';
	if (req->flags.confirm)
		flags[flagspos++] = '?';
	if (req->flags.exit)
		flags[flagspos++] = '<';
	if (req->flags.echo)
		flags[flagspos++] = '+';
	if (req->flags.quick)
		flags[flagspos++] = '>';
	if (flagspos > 1)
		flags[flagspos++] = 0;

	return flags;
}

int
get_run_requests_count(void)
{
	return run_requests_count;
}
