/* Process execution */
#include "tig.h"

static void
child_setup(const char *dir, int in_fd, int out_fd, int err_fd)
{
	if (in_fd >= 0 && in_fd != STDIN_FILENO) {
		dup2(in_fd, STDIN_FILENO);
		close(in_fd);
	}
	if (out_fd >= 0 && out_fd != STDOUT_FILENO) {
		dup2(out_fd, STDOUT_FILENO);
	}
	if (err_fd >= 0 && err_fd != STDERR_FILENO) {
		dup2(err_fd, STDERR_FILENO);
	}
	if (out_fd > STDERR_FILENO)
		close(out_fd);
	if (err_fd > STDERR_FILENO && err_fd != out_fd)
		close(err_fd);
	if (dir && *dir && chdir(dir) == -1)
		_exit(errno);
}

static int
devnull(int flags)
{
	return open("/dev/null", flags);
}

static int
wait_pid(pid_t pid)
{
	int status = 0;

	while (waitpid(pid, &status, 0) == -1) {
		if (errno != EINTR)
			return -1;
	}
	if (WIFEXITED(status))
		return WEXITSTATUS(status);
	return -1;
}

char *
io_capture_input(const char **argv, const char *dir, const char *input, size_t inlen,
		 size_t *len, int *status, bool with_stderr)
{
	int out[2];
	int in[2] = { -1, -1 };
	pid_t pid;
	char *buf = NULL;
	size_t size = 0, alloc = 0;

	if (!argv || !argv[0])
		return NULL;
	if (pipe(out) < 0)
		return NULL;
	if (input && pipe(in) < 0) {
		close(out[0]);
		close(out[1]);
		return NULL;
	}

	fflush(NULL);
	pid = fork();
	if (pid < 0) {
		close(out[0]);
		close(out[1]);
		if (input) {
			close(in[0]);
			close(in[1]);
		}
		return NULL;
	}

	if (pid == 0) {
		int in_fd = input ? in[0] : devnull(O_RDONLY);
		int err_fd = with_stderr ? out[1] : devnull(O_WRONLY);

		close(out[0]);
		if (input)
			close(in[1]);
		child_setup(dir, in_fd, out[1], err_fd);
		execvp(argv[0], (char *const *) argv);
		_exit(127);
	}

	close(out[1]);
	if (input) {
		size_t written = 0;

		close(in[0]);
		signal(SIGPIPE, SIG_IGN);
		/* Write input; assume the child consumes before producing too much */
		while (written < inlen) {
			ssize_t n = write(in[1], input + written, inlen - written);
			if (n <= 0) {
				if (n < 0 && errno == EINTR)
					continue;
				break;
			}
			written += n;
		}
		close(in[1]);
	}

	while (true) {
		ssize_t n;

		if (alloc - size < 4096) {
			alloc = alloc ? alloc * 2 : 8192;
			buf = xrealloc(buf, alloc + 1);
		}
		n = read(out[0], buf + size, alloc - size);
		if (n < 0) {
			if (errno == EINTR)
				continue;
			break;
		}
		if (n == 0)
			break;
		size += n;
	}
	close(out[0]);
	if (!buf)
		buf = xcalloc(1, 1);
	buf[size] = 0;

	{
		int st = wait_pid(pid);
		if (status)
			*status = st;
	}
	if (len)
		*len = size;
	return buf;
}

char *
io_capture(const char **argv, const char *dir, size_t *len, int *status, bool with_stderr)
{
	return io_capture_input(argv, dir, NULL, 0, len, status, with_stderr);
}

bool
io_run_buf(const char **argv, char buf[], size_t bufsize, const char *dir, bool allow_empty)
{
	size_t len;
	int status;
	char *out = io_capture(argv, dir, &len, &status, false);

	if (!out)
		return false;
	while (len > 0 && (out[len - 1] == '\n' || out[len - 1] == '\r'))
		out[--len] = 0;
	string_ncopy_do(buf, bufsize, out, len);
	free(out);
	if (status != 0)
		return false;
	return allow_empty || *buf;
}

bool
io_run_ok(const char **argv, const char *dir)
{
	int status;
	char *out = io_capture(argv, dir, NULL, &status, false);

	if (!out)
		return false;
	free(out);
	return status == 0;
}

bool
io_run_with_input(const char **argv, const char *dir, const char *input, size_t inlen)
{
	int status;
	char *out = io_capture_input(argv, dir, input, inlen, NULL, &status, false);

	if (!out)
		return false;
	free(out);
	return status == 0;
}

bool
io_run_bg(const char **argv, const char *dir)
{
	return io_run_ok(argv, dir);
}

bool
io_run_fg(const char **argv, const char *dir)
{
	pid_t pid;

	fflush(NULL);
	pid = fork();
	if (pid < 0)
		return false;
	if (pid == 0) {
		if (dir && *dir && chdir(dir) == -1)
			_exit(errno);
		execvp(argv[0], (char *const *) argv);
		_exit(127);
	}
	return wait_pid(pid) == 0;
}

int
io_load_string(char *data, size_t len, const char *separators, io_read_fn read_property, void *cbdata)
{
	char *pos = data;
	char *end = data + len;
	int state = 0;

	while (pos < end && state == 0) {
		char *eol = memchr(pos, '\n', end - pos);
		char *name, *value;
		size_t namelen, valuelen;

		if (!eol)
			eol = end;
		*eol = 0;

		name = pos;
		namelen = strcspn(name, separators);

		if (name[namelen]) {
			name[namelen] = 0;
			value = string_trim(name + namelen + 1);
			valuelen = strlen(value);
		} else {
			value = (char *) "";
			valuelen = 0;
		}

		name = string_trim(name);
		namelen = strlen(name);
		state = read_property(name, namelen, value, valuelen, cbdata);
		pos = eol + 1;
	}

	return state;
}

int
io_run_load(const char **argv, const char *separators, io_read_fn read_property, void *data)
{
	size_t len;
	int status;
	char *out = io_capture(argv, NULL, &len, &status, false);
	int state;

	if (!out)
		return ERR;
	state = io_load_string(out, len, separators, read_property, data);
	free(out);
	if (state == ERR)
		return ERR;
	return status == 0 ? OK : ERR;
}

char *
read_file(const char *path, size_t *len)
{
	FILE *file = fopen(path, "r");
	char *buf = NULL;
	size_t size = 0, alloc = 0;

	if (!file)
		return NULL;
	while (true) {
		size_t n;

		if (alloc - size < 4096) {
			alloc = alloc ? alloc * 2 : 8192;
			buf = xrealloc(buf, alloc + 1);
		}
		n = fread(buf + size, 1, alloc - size, file);
		if (n == 0)
			break;
		size += n;
	}
	fclose(file);
	if (!buf)
		buf = xcalloc(1, 1);
	buf[size] = 0;
	if (len)
		*len = size;
	return buf;
}
