read_repo_info_line(char *name, size_t namelen, char *value, size_t valuelen, void *data)
{
	return OK;
}

void
load_repo_head(void)
{
	const char *head_argv[] = { "git", "rev-parse", "--verify", "-q", "HEAD", NULL };
	const char *sym_argv[] = { "git", "symbolic-ref", "-q", "HEAD", NULL };
	char buf[SIZEOF_STR];

	repo.head[0] = 0;
	repo.head_id[0] = 0;
	if (io_run_buf(head_argv, buf, sizeof(buf), NULL, false))
		string_ncopy(repo.head_id, buf, strlen(buf));
	if (io_run_buf(sym_argv, buf, sizeof(buf), NULL, false)) {
		const char *name = buf;

		if (!prefixcmp(name, "refs/heads/"))
			name += STRING_SIZE("refs/heads/");
		string_ncopy(repo.head, name, strlen(name));
	}
}

void
load_repo_info(void)
{
	const char *argv[] = { "git", "rev-parse", "--git-dir", "--is-inside-work-tree", "--show-cdup", "--show-prefix", NULL };
	size_t len;
	int status;
	char *out = io_capture(argv, NULL, &len, &status, false);
	char *lines[8] = {0};
	int n = 0;
	char *pos;

	(void) read_repo_info_line;
	memset(&repo, 0, sizeof(repo));
	if (!out)
		return;
	if (status != 0) {
		/* Might be inside .git dir; try just --git-dir */
		const char *gd_argv[] = { "git", "rev-parse", "--git-dir", NULL };
		char buf[SIZEOF_STR];

		free(out);
		if (io_run_buf(gd_argv, buf, sizeof(buf), NULL, false)) {
			string_copy(repo.git_dir, buf);
			repo.exists = true;
		}
		return;
	}

	for (pos = out; n < 8 && pos < out + len; ) {
		char *eol = strchr(pos, '\n');

		if (!eol)
			eol = out + len;
		*eol = 0;
		lines[n++] = pos;
		pos = eol + 1;
	}

	if (n >= 1) {
		string_copy(repo.git_dir, lines[0]);
		repo.exists = true;
	}
	if (n >= 2)
		repo.is_inside_work_tree = !strcmp(lines[1], "true");
	if (n >= 3)
		string_copy(repo.cdup, lines[2]);
	if (n >= 4)
		string_copy(repo.prefix, lines[3]);
	free(out);

	load_repo_head();

	if (*repo.head) {
		const char *up_argv[] = { "git", "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{upstream}", NULL };
		char buf[SIZEOF_STR];

		if (io_run_buf(up_argv, buf, sizeof(buf), NULL, false)) {
			string_copy(repo.upstream, buf);
		}
	}
}

/* ------------------------------------------------------------------ */
/* References */

struct ref_entry {
	struct ref *ref;
};

static struct ref **refs;
static size_t refs_size;
static struct ref *refs_head;
static bool refs_tags_annotated;

struct ref_list_entry {
	char id[SIZEOF_REV];
	struct ref *refs;
};

static struct ref_list_entry *ref_lists;
static size_t ref_lists_size;

static struct ref_format **ref_formats;

static int
strcmp_numeric(const char *s1, const char *s2)
{
	while (*s1 && *s2) {
		if (isdigit((unsigned char) *s1) && isdigit((unsigned char) *s2)) {
			char *e1, *e2;
			unsigned long n1 = strtoul(s1, &e1, 10);
			unsigned long n2 = strtoul(s2, &e2, 10);

			if (n1 != n2)
				return n1 < n2 ? -1 : 1;
			s1 = e1;
			s2 = e2;
			continue;
		}
		if (*s1 != *s2)
			return (unsigned char) *s1 - (unsigned char) *s2;
		s1++;
		s2++;
	}
	return (unsigned char) *s1 - (unsigned char) *s2;
}

int
ref_compare(const struct ref *ref1, const struct ref *ref2)
{
	if (ref1->type != ref2->type)
		return ref1->type - ref2->type;
	return strcmp_numeric(ref1->name, ref2->name);
}

static struct ref *
find_ref(const char *name)
{
	size_t i;

	for (i = 0; i < refs_size; i++)
		if (!strcmp(refs[i]->name, name))
			return refs[i];
	return NULL;
}

struct read_ref_opt {
	const char *head;
	const char *remote;
};

static int
read_ref(char *id, size_t idlen, char *name, size_t namelen, void *data)
{
	struct read_ref_opt *opt = data;
	enum reference_type type = REFERENCE_BRANCH;
	struct ref *ref;
	char namebuf[SIZEOF_STR];

	if (idlen != SIZEOF_REV - 1 || !namelen)
		return OK;

	if (!prefixcmp(name, "refs/tags/")) {
		type = REFERENCE_TAG;
		if (!suffixcmp(name, namelen, "^{}")) {
			namelen -= 3;
			name[namelen] = 0;
		} else {
			type = REFERENCE_LOCAL_TAG;
		}

		namelen -= STRING_SIZE("refs/tags/");
		name	+= STRING_SIZE("refs/tags/");

	} else if (!prefixcmp(name, "refs/remotes/")) {
		type = REFERENCE_REMOTE;
		namelen -= STRING_SIZE("refs/remotes/");
		name	+= STRING_SIZE("refs/remotes/");
		if (opt->remote && !strcmp(opt->remote, name))
			type = REFERENCE_TRACKED_REMOTE;

	} else if (!prefixcmp(name, "refs/replace/")) {
		type = REFERENCE_REPLACE;
		id	= name + strlen("refs/replace/");
		idlen	= namelen - strlen("refs/replace/");
		name	= (char *) "replaced";
		namelen	= strlen(name);

	} else if (!prefixcmp(name, "refs/heads/")) {
		namelen -= STRING_SIZE("refs/heads/");
		name	+= STRING_SIZE("refs/heads/");
		if (strlen(opt->head) == namelen &&
		    !strncmp(opt->head, name, namelen))
			type = REFERENCE_HEAD;

	} else if (!strcmp(name, "HEAD")) {
		/* Handle the case of HEAD not being a symbolic ref,
		 * i.e. during a rebase. */
		if (*opt->head)
			return OK;
		type = REFERENCE_HEAD;

	} else if (!strcmp(name, "refs/stash")) {
		type = REFERENCE_STASH;

	} else if (!prefixcmp(name, "refs/notes/")) {
		type = REFERENCE_NOTE;

	} else if (!prefixcmp(name, "refs/prefetch/")) {
		type = REFERENCE_PREFETCH;

	} else {
		type = REFERENCE_OTHER;
	}

	string_ncopy(namebuf, name, namelen);

	ref = find_ref(namebuf);
	if (!ref) {
		ref = xcalloc(1, sizeof(*ref) + namelen);
		memcpy(ref->name, namebuf, namelen);
		ref->name[namelen] = 0;
		refs = xrealloc(refs, sizeof(*refs) * (refs_size + 1));
		refs[refs_size++] = ref;
	}

	ref->type = type;
	ref->valid = 1;
	string_ncopy_do(ref->id, SIZEOF_REV, id, idlen);
	if (type == REFERENCE_TAG)
		refs_tags_annotated = true;
	if (type == REFERENCE_HEAD)
		refs_head = ref;

	return OK;
}

static int
compare_refs_ptr(const void *a, const void *b)
{
	return ref_compare(*(const struct ref **) a, *(const struct ref **) b);
}

static struct ref_list_entry *
get_ref_list_entry(const char *id, bool create)
{
	size_t i;

	for (i = 0; i < ref_lists_size; i++)
		if (!strcmp(ref_lists[i].id, id))
			return &ref_lists[i];
	if (!create)
		return NULL;
	ref_lists = xrealloc(ref_lists, sizeof(*ref_lists) * (ref_lists_size + 1));
	memset(&ref_lists[ref_lists_size], 0, sizeof(*ref_lists));
	string_copy_rev(ref_lists[ref_lists_size].id, id);
	return &ref_lists[ref_lists_size++];
}

void
load_refs(bool force)
{
	const char *ls_remote_argv[SIZEOF_ARG] = {
		"git", "show-ref", "--head", "--dereference", NULL
	};
	char ls_remote_cmd[SIZEOF_STR];
	const char *env = getenv("TIG_LS_REMOTE");
	struct read_ref_opt opt;
	size_t i;
	static bool loaded;

	if (loaded && !force)
		return;
	loaded = true;

	if (env && *env) {
		int argc = 0;

		string_copy(ls_remote_cmd, env);
		argv_from_string(ls_remote_argv, &argc, ls_remote_cmd);
	}

	for (i = 0; i < refs_size; i++)
		refs[i]->valid = 0;
	refs_head = NULL;
	refs_tags_annotated = false;

	load_repo_head();
	opt.head = repo.head;
	opt.remote = repo.upstream;

	io_run_load(ls_remote_argv, "\t ", read_ref, &opt);

	/* Remove invalid refs */
	{
		size_t j = 0;

		for (i = 0; i < refs_size; i++) {
			if (refs[i]->valid)
				refs[j++] = refs[i];
		}
		refs_size = j;
	}

	qsort(refs, refs_size, sizeof(*refs), compare_refs_ptr);

	/* Rebuild per-commit lists */
	ref_lists_size = 0;
	for (i = 0; i < refs_size; i++) {
		struct ref_list_entry *entry = get_ref_list_entry(refs[i]->id, true);
		struct ref **pos = &entry->refs;

		refs[i]->next = NULL;
		while (*pos)
			pos = &(*pos)->next;
		*pos = refs[i];
	}
}

const struct ref *
get_ref_list(const char *id)
{
	struct ref_list_entry *entry = get_ref_list_entry(id, false);

	return entry ? entry->refs : NULL;
}

const struct ref *
get_ref_head(void)
{
	return refs_head;
}

bool
refdb_has_annotated_tags(void)
{
	return refs_tags_annotated;
}

bool
ref_list_contains_tag(const struct ref *list)
{
	for (; list; list = list->next)
		if (list->type == REFERENCE_TAG)
			return true;
	return false;
}

void
foreach_ref(bool (*visitor)(void *data, const struct ref *ref), void *data)
{
	size_t i;

	for (i = 0; i < refs_size; i++)
		if (!visitor(data, refs[i]))
			break;
}

line_type_t
get_line_type_from_ref(const struct ref *ref)
{
	switch (ref->type) {
	case REFERENCE_HEAD:		return LINE_MAIN_HEAD;
	case REFERENCE_BRANCH:		return LINE_MAIN_REF;
	case REFERENCE_TRACKED_REMOTE:	return LINE_MAIN_TRACKED;
	case REFERENCE_REMOTE:		return LINE_MAIN_REMOTE;
	case REFERENCE_TAG:		return LINE_MAIN_TAG;
	case REFERENCE_LOCAL_TAG:	return LINE_MAIN_LOCAL_TAG;
	case REFERENCE_REPLACE:		return LINE_MAIN_REPLACE;
	case REFERENCE_STASH:		return LINE_MAIN_STASH;
	case REFERENCE_NOTE:		return LINE_MAIN_NOTE;
	case REFERENCE_PREFETCH:	return LINE_MAIN_PREFETCH;
	case REFERENCE_OTHER:		return LINE_MAIN_OTHER;
	}
	return LINE_MAIN_REF;
}

/* ------------------------------------------------------------------ */
/* Reference formats */

static const char *ref_type_names[] = {
	"head", "branch", "tracked-remote", "remote", "tag", "local-tag",
	"replace", "stash", "note", "prefetch", "other",
};

#define REFERENCE_TYPES (REFERENCE_OTHER + 1)

static struct ref_format *ref_format_table[REFERENCE_TYPES];
static char *ref_format_strings[REFERENCE_TYPES];

const struct ref_format *
get_ref_format(const struct ref *ref)
{
	static const struct ref_format default_format = { "", "" };
	struct ref_format *format = ref_format_table[ref->type];

	(void) ref_formats;
	if (!format && ref->type == REFERENCE_LOCAL_TAG)
		format = ref_format_table[REFERENCE_TAG];
	if (!format && ref->type == REFERENCE_TRACKED_REMOTE)
		format = ref_format_table[REFERENCE_REMOTE];
	if (!format)
		format = ref_format_table[REFERENCE_BRANCH];
	if (!format)
		format = (struct ref_format *) &default_format;
	return format;
}

static bool
parse_ref_format(const char *arg, int idx)
{
	const char *start = arg;
	size_t i;

	for (i = 0; i < REFERENCE_TYPES; i++) {
		const char *name = ref_type_names[i];
		size_t namelen = strlen(name);
		const char *pos;
		bool hide = false;

		if (!prefixcmp(arg, "hide:")) {
			hide = true;
			start = arg + STRING_SIZE("hide:");
		} else {
			start = arg;
		}

		if (hide) {
			if (strcmp(start, name))
				continue;
			pos = start;
		} else {
			pos = strstr(start, name);
			if (!pos)
				continue;
			/* make sure we match whole word, e.g. "tag" vs "local-tag" */
			if (pos > start && (isalnum((unsigned char) pos[-1]) || pos[-1] == '-'))
				continue;
			if (isalnum((unsigned char) pos[namelen]) || pos[namelen] == '-')
				continue;
		}

		{
			struct ref_format *format = xcalloc(1, sizeof(*format));

			if (hide) {
				format->start = xstrdup("hide:");
				format->end = xstrdup("");
			} else {
				format->start = xstrndup(start, pos - start);
				format->end = xstrdup(pos + namelen);
			}
			ref_format_table[i] = format;
			free(ref_format_strings[i]);
			ref_format_strings[i] = xstrdup(arg);
			(void) idx;
			return true;
		}
	}

	return false;
}

bool
parse_ref_formats(const char *argv[])
{
	int i;

	for (i = 0; i < REFERENCE_TYPES; i++) {
		ref_format_table[i] = NULL;
		free(ref_format_strings[i]);
		ref_format_strings[i] = NULL;
	}

	for (i = 0; argv[i]; i++) {
		if (!parse_ref_format(argv[i], i))
			return false;
	}
	return true;
}

void
format_ref_formats(char *buf, size_t bufsize)
{
	size_t pos = 0;
	int order[] = { REFERENCE_BRANCH, REFERENCE_REMOTE, REFERENCE_TAG, REFERENCE_REPLACE,
			REFERENCE_HEAD, REFERENCE_TRACKED_REMOTE, REFERENCE_LOCAL_TAG,
			REFERENCE_STASH, REFERENCE_NOTE, REFERENCE_PREFETCH, REFERENCE_OTHER };
	size_t i;

	buf[0] = 0;
	for (i = 0; i < ARRAY_SIZE(order); i++) {
		int type = order[i];
		struct ref_format *format = ref_format_table[type];

		if (!format)
			continue;
		string_nformat(buf, bufsize, &pos, "%s%s%s%s", pos ? " " : "",
			       format->start, ref_type_names[type], format->end);
	}
}

/* ------------------------------------------------------------------ */
/* Git configuration */

extern enum status_code set_option_from_git_config(const char *name, const char *value);

static char git_config_remote_branch[SIZEOF_REF];

static int
read_git_config_option(char *name, size_t namelen, char *value, size_t valuelen, void *data)
{
	if (!strcmp(name, "core.abbrev")) {
		int abbrev;

		if (parse_int(&abbrev, value, 0, SIZEOF_REV - 1) == SUCCESS)
			git_config_abbrev = abbrev;
	} else if (!strcmp(name, "core.editor")) {
		string_copy(git_core_editor, value);
	} else if (!strcmp(name, "core.worktree")) {
		string_copy(repo.worktree, value);
	} else if (!strcmp(name, "i18n.commitencoding") || !strcmp(name, "gui.encoding")) {
		/* Ignored */
	} else if (!prefixcmp(name, "tig.") || !prefixcmp(name, "color.")) {
		set_option_from_git_config(name, value);
	} else if (*repo.head && !prefixcmp(name, "branch.")) {
		size_t headlen = strlen(repo.head);

		if (!strncmp(name + 7, repo.head, headlen) && name[7 + headlen] == '.') {
			const char *key = name + 7 + headlen + 1;

			if (!strcmp(key, "remote"))
				string_copy(repo.remote, value);
			else if (!strcmp(key, "merge"))
				string_copy(git_config_remote_branch, value);
		}
	}

	return OK;
}

bool
load_git_config(void)
{
	const char *config_list_argv[] = { "git", "config", "--list", NULL };

	return io_run_load(config_list_argv, "=", read_git_config_option, NULL) == OK;
}
