	{ "wrap-lines", OPT_BOOL, &opt_wrap_lines, {0}, 0, true },
	{ "wrap-search", OPT_BOOL, &opt_wrap_search, {0}, 0, true },
	/* hidden */
	{ "file-args", OPT_ARGS, &opt_file_args, {0}, 0, false, true },
	{ "rev-args", OPT_ARGS, &opt_rev_args, {0}, 0, false, true },
	{ "cmdline-args", OPT_ARGS, &opt_cmdline_args, {0}, 0, false, true },
};

static struct option_info *
find_option_info(const char *name)
{
	size_t namelen = strlen(name);
	size_t i;

	for (i = 0; i < ARRAY_SIZE(option_info); i++) {
		struct option_info *option = &option_info[i];

		if (strlen(option->name) == namelen &&
		    !string_enum_compare(option->name, name, namelen))
			return option;
	}
	return NULL;
}

bool
option_is_known(const char *name)
{
	return find_option_info(name) != NULL;
}

void
mark_option_seen_name(const char *name)
{
	struct option_info *option = find_option_info(name);

	if (option)
		option->seen = true;
}

/* ------------------------------------------------------------------ */
/* Error messages */

static char status_custom_message[SIZEOF_STR];

enum status_code
error(const char *fmt, ...)
{
	va_list args;

	va_start(args, fmt);
	vsnprintf(status_custom_message, sizeof(status_custom_message), fmt, args);
	va_end(args);
	return ERROR_CUSTOM_MESSAGE;
}

const char *
get_status_message(enum status_code code)
{
	switch (code) {
	case SUCCESS:			return "";
	case ERROR_OUT_OF_MEMORY:	return "Out of memory";
	case ERROR_CUSTOM_MESSAGE:	return status_custom_message;
	case ERROR_UNKNOWN_OPTION:	return "Unknown option";
	case ERROR_UNKNOWN_KEYMAP:	return "Unknown key map";
	case ERROR_UNKNOWN_KEY:		return "Unknown key";
	case ERROR_UNKNOWN_REQUEST:	return "Unknown request";
	case ERROR_UNKNOWN_COLOR:	return "Unknown color";
	case ERROR_UNKNOWN_ATTR:	return "Unknown color attribute";
	case ERROR_WRONG_ARGS:		return "Wrong number of arguments";
	case ERROR_NO_OPTION_VALUE:	return "No option value";
	case ERROR_INVALID_STEP_VALUE:	return "Invalid step value";
	case ERROR_FILE_DOES_NOT_EXIST:	return "File does not exist";
	case ERROR_HISTORY_NOT_SUPPORTED: return "History not supported";
	case ERROR_NO_VALUE_ASSIGNED:	return "No value assigned";
	}
	return "Unknown error";
}

/* ------------------------------------------------------------------ */
/* Value parsing */

enum status_code
parse_int(int *opt, const char *arg, int min, int max)
{
	char *end;
	long value;

	if (!arg || !*arg)
		return error("Integer value expected");
	value = strtol(arg, &end, 10);
	if (*end)
		return error("Integer value expected");
	if (min <= value && value <= max) {
		*opt = value;
		return SUCCESS;
	}

	return error("Value must be between %d and %d", min, max);
}

static bool
parse_bool_value(const char *arg)
{
	return !strcmp(arg, "1") || !strcasecmp(arg, "true") || !strcasecmp(arg, "yes");
}

static enum status_code
parse_step(double *opt, const char *arg)
{
	int value = atoi(arg);

	if (!value && !isdigit((unsigned char) *arg))
		return error("Invalid double or percentage");

	*opt = value;
	if (!strchr(arg, '%'))
		return SUCCESS;

	/* "Shift down" so 100% and 1 does not conflict. */
	*opt = (*opt - 1) / 100;
	if (*opt >= 1.0) {
		*opt = 0.99;
		return error("Percentage is larger than 100%%");
	}
	if (*opt < 0.0) {
		*opt = 1;
		return error("Percentage is less than 0%%");
	}
	return SUCCESS;
}

int
apply_step(double step, int value)
{
	if (step >= 1)
		return (int) step;
	value *= step + 0.01;
	return value ? value : 1;
}

static enum status_code
parse_enum(int *opt, const char *arg, const struct enum_map *map)
{
	if (map_enum_do(map->entries, map->size, opt, arg))
		return SUCCESS;

	*opt = parse_bool_value(arg) ? map->entries[1].value : map->entries[0].value;
	return SUCCESS;
}

static enum status_code
parse_string(char *opt, const char *arg, size_t optsize)
{
	int arglen = strlen(arg);

	switch (arg[0]) {
	case '\"':
	case '\'':
		if (arglen == 1 || arg[arglen - 1] != arg[0])
			return error("Unmatched quotation");
		arg += 1; arglen -= 2;
		/* fallthrough */
	default:
		string_ncopy_do(opt, optsize, arg, arglen);
		return SUCCESS;
	}
}

