		return width > 160 || width * 0.5 > (height - 1) * 2;
	return vsplit == VERTICAL_SPLIT_VERTICAL;
}

/* ------------------------------------------------------------------ */
/* Toggling */

static const char *
format_option_value(struct option_info *option, char *buf, size_t bufsize)
{
	buf[0] = 0;
	switch (option->type) {
	case OPT_BOOL:
		return *(bool *) option->value ? "yes" : "no";
	case OPT_INT:
		snprintf(buf, bufsize, "%d", *(int *) option->value);
		return buf;
	case OPT_DOUBLE: {
		double value = *(double *) option->value;

		if (value >= 1)
			snprintf(buf, bufsize, "%d", (int) value);
		else
			snprintf(buf, bufsize, "%.0f%%", value * 100 + 1);
		return buf;
	}
	case OPT_ENUM: {
		int value = *(int *) option->value;
		int i;

		for (i = 0; i < option->map.size; i++)
			if (option->map.entries[i].value == value)
				return option->map.entries[i].name;
		return "";
	}
	case OPT_STRING:
	case OPT_DELIM:
		snprintf(buf, bufsize, "\"%s\"", (char *) option->value);
		return buf;
	case OPT_ARGS: {
		const char **argv = *(const char ***) option->value;
		char *str = argv_to_string_alloc(argv, " ");

		snprintf(buf, bufsize, "%s", str);
		return buf;
	}
	case OPT_VIEW: {
		struct view_config *cfg = find_view_config(option->value);

		format_view_config(cfg, buf, bufsize);
		return buf;
	}
	case OPT_REFFORMAT:
		format_ref_formats(buf, bufsize);
		return buf;
	}
	return buf;
}

const char *
get_option_value_string(const char *name, char *buf, size_t bufsize)
{
	struct option_info *option = find_option_info(name);

	if (!option)
		return NULL;
	return format_option_value(option, buf, bufsize);
}

static enum status_code
toggle_option_info(struct option_info *option, const char *name, const char *arg, char *msg, size_t msgsize)
{
	switch (option->type) {
	case OPT_BOOL: {
		bool *opt = option->value;

		*opt = !*opt;
		if (opt == &opt_mouse)
			enable_mouse(*opt);
		snprintf(msg, msgsize, ":set %s = %s", name, *opt ? "yes" : "no");
		return SUCCESS;
	}
	case OPT_ENUM: {
		int *opt = option->value;
		int idx = 0, i;

		for (i = 0; i < option->map.size; i++)
			if (option->map.entries[i].value == *opt)
				idx = i;
		idx = (idx + 1) % option->map.size;
		*opt = option->map.entries[idx].value;
		snprintf(msg, msgsize, ":set %s = %s", name, option->map.entries[idx].name);
		return SUCCESS;
	}
	case OPT_INT: {
		int *opt = option->value;
		int diff;

		if (!arg)
			arg = "1";
		diff = atoi(arg);
		if (!diff)
			diff = *arg == '-' ? -1 : 1;

		if (opt == &opt_diff_context && *opt < 0)
			*opt = -*opt;
		if (opt == &opt_diff_context && diff < 0) {
			if (!*opt)
				return error("Diff context cannot be less than zero");
			if (*opt < -diff)
				diff = -*opt;
		}

		*opt += diff;
		snprintf(msg, msgsize, ":set %s = %d", name, *opt);
		return SUCCESS;
	}
	case OPT_DOUBLE: {
		double *opt = option->value;
		int sign = 1;
		double diff;

		if (!arg)
			arg = "1.0";
		if (*arg == '-') {
			sign = -1;
			arg++;
		}

		if (parse_step(&diff, arg) != SUCCESS)
			diff = strtod(arg, NULL);

		*opt += sign * diff;
		snprintf(msg, msgsize, ":set %s = %.2f", name, *opt);
		return SUCCESS;
	}
	default:
		return error("Unsupported `:toggle %s`", name);
	}
}

static enum status_code
toggle_column_option(struct view *view, struct view_config *cfg, int c,
		     const struct column_option_desc *desc, const char *arg, char *msg, size_t msgsize)
{
	struct view_column_options *opt = &cfg->opts[c];
	char *field = (char *) opt + desc->offset;
	char name[SIZEOF_STR];
	const char *colname = view_column_names[cfg->types[c]];

	snprintf(name, sizeof(name), "%s-view-%s-%s", view->name, colname, desc->name);

	switch (desc->type) {
	case COLOPT_BOOL: {
		bool is_display = desc->offset == offsetof(struct view_column_options, display);
		bool value;

		if (is_display) {
			*(int *) field = !*(int *) field;
			value = *(int *) field;
		} else {
			*(bool *) field = !*(bool *) field;
			value = *(bool *) field;
		}
		snprintf(msg, msgsize, ":set %s = %s", name, value ? "yes" : "no");
		break;
	}
	case COLOPT_ENUM: {
		int *value = (int *) field;
		size_t idx = 0, i;

		for (i = 0; i < desc->mapsize; i++)
			if (desc->map[i].value == *value)
				idx = i;
		idx = (idx + 1) % desc->mapsize;
		*value = desc->map[idx].value;
		snprintf(msg, msgsize, ":set %s = %s", name, desc->map[idx].name);
		break;
	}
	case COLOPT_OVERFLOW: {
		int *value = (int *) field;

		*value = *value ? -*value : 50;
		if (*value < 0) {
			snprintf(msg, msgsize, ":set %s = no", name);
		} else {
			snprintf(msg, msgsize, ":set %s = %d", name, *value);
		}
		if (*value < 0)
			*value = 0;
		break;
	}
	case COLOPT_INT:
	case COLOPT_WIDTH: {
		int *value = (int *) field;
		int diff = arg ? atoi(arg) : 1;

		if (!diff)
			diff = arg && *arg == '-' ? -1 : 1;
		*value += diff;
		if (*value < 0)
			*value = 0;
		snprintf(msg, msgsize, ":set %s = %d", name, *value);
		break;
	}
	default:
		return error("Unsupported `:toggle %s`", name);
	}

	cfg->version++;
	options_version++;
	return SUCCESS;
}

/* Returns SUCCESS with message filled, or error. *flags receives the view
 * flags of views that need to be reloaded. */
enum status_code
toggle_option_full(struct view *view, const char *option, const char *arg,
		   char *msg, size_t msgsize, enum view_flag *flags)
{
	struct option_info *info;
	struct view_config *cfg;
	size_t optionlen;

	*flags = 0;
	msg[0] = 0;
	if (!option)
		return error("%s", "No option name given to :toggle");
	optionlen = strlen(option);

	if ((optionlen == 10 && !string_enum_compare(option, "sort-field", 10)) ||
	    (optionlen == 10 && !string_enum_compare(option, "sort-order", 10))) {
		if (!view_has_flags(view, VIEW_SORTABLE))
			return error("Sorting is not yet supported for the %s view", view->name);
		return error("SORT:%s", option);
	}

	info = find_option_info(option);
	if (info && info->toggle && !info->hidden) {
		*flags = info->flags;
		return toggle_option_info(info, info->name, arg, msg, msgsize);
	}

	cfg = find_view_config(view->name);
	if (cfg) {
		int c;

		for (c = 0; c < cfg->count; c++) {
			const char *colname = view_column_names[cfg->types[c]];
			size_t collen = strlen(colname);
			const struct column_option_desc *desc = NULL;

			if (optionlen == collen && !string_enum_compare(option, colname, collen)) {
				desc = find_column_option(cfg->types[c], "display", 7);
			} else if (optionlen > collen && !string_enum_compare(option, colname, collen) &&
				   option[collen] == '-') {
				desc = find_column_option(cfg->types[c], option + collen + 1, optionlen - collen - 1);
			} else {
				/* "<option>-<column>" e.g. author-display? */
				continue;
			}
			if (desc)
				return toggle_column_option(view, cfg, c, desc, arg, msg, msgsize);
		}
	}

	return error("`:toggle %s` not supported", option);
}

/* ------------------------------------------------------------------ */
/* Saving options */

extern const char *get_key_name(const struct key key[], size_t keys, bool quote_comma);

static void
save_option_settings(FILE *file)
{
	size_t i;

	fprintf(file, "%s", "\n## Settings\n\n");
	for (i = 0; i < ARRAY_SIZE(option_info); i++) {
		struct option_info *option = &option_info[i];
		char buf[SIZEOF_MED_STR];
		const char *value;

		if (option->hidden)
			continue;
		value = format_option_value(option, buf, sizeof(buf));
		if (option->value == &opt_diff_context) {
			snprintf(buf, sizeof(buf), "%d", opt_diff_context < 0 ? -opt_diff_context : opt_diff_context);
			value = buf;
		}
		fprintf(file, "set %-25s = %s\n", option->name, value);
	}
}

static void
save_option_keybindings(FILE *file)
{
	int k, r;

	fprintf(file, "%s", "\n## Keybindings\n");
	for (k = 0; k < get_keymaps_count(); k++) {
		struct keymap *keymap = get_keymap_by_index(k);
		const char *group = NULL;
		const char *last_group = NULL;
		int i;

		if (keymap == toggle_keymap)
			continue;

		for (r = 0; r < req_info_count; r++) {
			const struct request_info *info = &req_info[r];

			if (info->group)
				group = info->group;
			for (i = 0; i < keymap->size; i++) {
				struct keybinding *kb = &keymap->data[i];

				if (kb->request != info->request)
					continue;
				if (group != last_group) {
					fprintf(file, "\n# %s\n", group);
					last_group = group;
				}
				fprintf(file, "bind %-10s %-15s %s\n", keymap->name,
					get_key_name(kb->key, kb->keys, false), enum_name(info->name));
			}
		}

		{
			static const char *groups[] = { "Option toggling:", "Internal commands:", "External commands:" };
			int g;

			for (g = 0; g < 3; g++) {
				bool printed = false;

				for (i = 0; i < keymap->size; i++) {
					struct keybinding *kb = &keymap->data[i];
					struct run_request *req = get_run_request(kb->request);
					int kind;

					if (!req)
						continue;
					kind = !req->flags.internal ? 2 :
					       (req->argv[0] && !strcmp(req->argv[0], "toggle")) ? 0 : 1;
					if (kind != g)
						continue;
					if (!printed) {
						fprintf(file, "\n# %s\n", groups[g]);
						printed = true;
					}
					{
						const char *flags = format_run_request_flags(req);
						char *cmd = argv_to_string_alloc(req->argv, " ");

						fprintf(file, "bind %-10s %-15s %s%s\n", keymap->name,
							get_key_name(kb->key, kb->keys, false), flags, cmd);
					}
				}
			}
		}
	}
}

static const char *
color_name(int color)
{
	static char buf[16];
	static const char *names[] = { "black", "red", "green", "yellow", "blue", "magenta", "cyan", "white" };

	if (color == COLOR_DEFAULT)
		return "default";
	if (color >= 0 && color < 8)
		return names[color];
	snprintf(buf, sizeof(buf), "color%d", color);
	return buf;
}

static const char *
attr_names(int attr)
{
	static char buf[SIZEOF_STR];
	size_t pos = 0;

	buf[0] = 0;
	if (attr & A_BLINK) string_format_from(buf, &pos, " blink");
	if (attr & A_BOLD) string_format_from(buf, &pos, " bold");
	if (attr & A_DIM) string_format_from(buf, &pos, " dim");
	if (attr & A_REVERSE) string_format_from(buf, &pos, " reverse");
	if ((attr & A_STANDOUT) == A_STANDOUT) string_format_from(buf, &pos, " standout");
	if (attr & A_UNDERLINE) string_format_from(buf, &pos, " underline");
	return buf;
}

static void
save_color(FILE *file, const char *name, struct line_info *info)
{
	fprintf(file, "color %-25s %-8s %-8s%s\n", name, color_name(info->fg), color_name(info->bg),
		*attr_names(info->attr) ? attr_names(info->attr) : " ");
}

static void
save_option_colors(FILE *file)
{
	int type;

	fprintf(file, "%s", "\n## Colors\n\n");
	for (type = 0; type < line_rules_count; type++) {
		struct line_rule *rule = &line_rules[type];
		struct line_info *info;
		char name[SIZEOF_STR];

		for (info = &rule->info; info; info = info->next) {
			if (info->prefix)
				snprintf(name, sizeof(name), "%s.%s", info->prefix, rule->name);
			else if (rule->line && *rule->line)
				snprintf(name, sizeof(name), "\"%s\"", rule->line);
			else
				snprintf(name, sizeof(name), "%s", rule->name);
			fprintf(file, "color %-28s %-8s %-8s%s\n", name, color_name(info->fg), color_name(info->bg),
				*attr_names(info->attr) ? attr_names(info->attr) : " ");
		}
	}
	(void) save_color;
}

bool
save_options(const char *path)
{
	FILE *file = fopen(path, "w");

	if (!file)
		return false;
	fprintf(file, "%s", "# Saved by Tig\n");
	save_option_settings(file);
	save_option_keybindings(file);
	save_option_colors(file);
	fclose(file);
	return true;
}
