/* Column option descriptors */
enum colopt_type { COLOPT_BOOL, COLOPT_INT, COLOPT_ENUM, COLOPT_STRING, COLOPT_OVERFLOW, COLOPT_WIDTH };

struct column_option_desc {
	const char *name;
	enum colopt_type type;
	size_t offset;
	const struct enum_map_entry *map;
	size_t mapsize;
};

#define COLOPT(name, type, field) { name, type, offsetof(struct view_column_options, field), NULL, 0 }
#define COLOPT_MAP(name, field, m) { name, COLOPT_ENUM, offsetof(struct view_column_options, field), m, ARRAY_SIZE(m) }

static int
get_column_options(enum view_column_type type, const struct column_option_desc **descs)
{
	static const struct column_option_desc author[] = {
		COLOPT_MAP("display", display, author_map),
		COLOPT("width", COLOPT_WIDTH, width),
		COLOPT("maxwidth", COLOPT_WIDTH, maxwidth),
	};
	static const struct column_option_desc commit_title[] = {
		COLOPT("display", COLOPT_BOOL, display),
		COLOPT_MAP("graph", graph, graph_display_map),
		COLOPT("refs", COLOPT_BOOL, refs),
		COLOPT("overflow", COLOPT_OVERFLOW, overflow),
	};
	static const struct column_option_desc date[] = {
		COLOPT_MAP("display", display, date_map),
		COLOPT("use-author", COLOPT_BOOL, use_author),
		COLOPT("local", COLOPT_BOOL, local),
		COLOPT("format", COLOPT_STRING, format),
		COLOPT("width", COLOPT_WIDTH, width),
	};
	static const struct column_option_desc file_name[] = {
		COLOPT_MAP("display", display, filename_map),
		COLOPT("width", COLOPT_WIDTH, width),
		COLOPT("maxwidth", COLOPT_WIDTH, maxwidth),
	};
	static const struct column_option_desc file_size[] = {
		COLOPT_MAP("display", display, file_size_map),
		COLOPT("width", COLOPT_WIDTH, width),
	};
	static const struct column_option_desc id[] = {
		COLOPT("display", COLOPT_BOOL, display),
		COLOPT("color", COLOPT_BOOL, color),
		COLOPT("width", COLOPT_WIDTH, width),
	};
	static const struct column_option_desc line_number[] = {
		COLOPT("display", COLOPT_BOOL, display),
		COLOPT("interval", COLOPT_INT, interval),
		COLOPT("width", COLOPT_WIDTH, width),
	};
	static const struct column_option_desc mode[] = {
		COLOPT("display", COLOPT_BOOL, display),
		COLOPT("width", COLOPT_WIDTH, width),
	};
	static const struct column_option_desc ref[] = {
		COLOPT("display", COLOPT_BOOL, display),
		COLOPT("width", COLOPT_WIDTH, width),
		COLOPT("maxwidth", COLOPT_WIDTH, maxwidth),
	};
	static const struct column_option_desc status[] = {
		COLOPT_MAP("display", display, status_label_map),
	};
	static const struct column_option_desc text[] = {
		COLOPT("display", COLOPT_BOOL, display),
		COLOPT("commit-title-overflow", COLOPT_OVERFLOW, overflow),
	};

	switch (type) {
	case VIEW_COLUMN_AUTHOR:
	case VIEW_COLUMN_COMMITTER:	*descs = author; return ARRAY_SIZE(author);
	case VIEW_COLUMN_COMMIT_TITLE:	*descs = commit_title; return ARRAY_SIZE(commit_title);
	case VIEW_COLUMN_DATE:		*descs = date; return ARRAY_SIZE(date);
	case VIEW_COLUMN_FILE_NAME:	*descs = file_name; return ARRAY_SIZE(file_name);
	case VIEW_COLUMN_FILE_SIZE:	*descs = file_size; return ARRAY_SIZE(file_size);
	case VIEW_COLUMN_ID:		*descs = id; return ARRAY_SIZE(id);
	case VIEW_COLUMN_LINE_NUMBER:	*descs = line_number; return ARRAY_SIZE(line_number);
	case VIEW_COLUMN_MODE:		*descs = mode; return ARRAY_SIZE(mode);
	case VIEW_COLUMN_REF:		*descs = ref; return ARRAY_SIZE(ref);
	case VIEW_COLUMN_STATUS:	*descs = status; return ARRAY_SIZE(status);
	case VIEW_COLUMN_TEXT:		*descs = text; return ARRAY_SIZE(text);
