static const struct column_option_desc *
find_column_option(enum view_column_type type, const char *name, size_t namelen)
{
	const struct column_option_desc *descs;
	int n = get_column_options(type, &descs);
	int i;

	for (i = 0; i < n; i++)
		if (strlen(descs[i].name) == namelen &&
		    !string_enum_compare(descs[i].name, name, namelen))
			return &descs[i];
	return NULL;
}

static enum status_code
parse_column_option(enum view_column_type type, struct view_column_options *opt,
		    const struct column_option_desc *desc, const char *value)
{
	char *field = (char *) opt + desc->offset;

	switch (desc->type) {
	case COLOPT_BOOL:
		*(bool *) field = !value ? true : parse_bool_value(value);
		if (desc->offset == offsetof(struct view_column_options, display))
			*(int *) field = !value ? true : parse_bool_value(value);
		return SUCCESS;
	case COLOPT_INT: {
		int v;
		enum status_code code;

		if (!value)
			return error("Integer value expected");
		code = parse_int(&v, value, 0, 1024);
		if (code == SUCCESS)
			*(int *) field = v;
		return code;
	}
	case COLOPT_WIDTH: {
		int v;
		enum status_code code;

		if (!value)
			return error("Integer value expected");
		if (strchr(value, '%')) {
			double step;
			code = parse_step(&step, value);
			if (code != SUCCESS)
				return code;
			*(int *) field = -(int) (step * 100 + 1);
			return SUCCESS;
		}
		code = parse_int(&v, value, 0, 1024);
		if (code == SUCCESS)
			*(int *) field = v;
		return code;
	}
	case COLOPT_OVERFLOW: {
		int v;

		if (!value) {
			*(int *) field = 50;
		} else if (parse_int(&v, value, 0, 1024) == SUCCESS) {
			*(int *) field = v;
		} else {
			*(int *) field = parse_bool_value(value) ? 50 : 0;
		}
		return SUCCESS;
	}
	case COLOPT_ENUM: {
		struct enum_map map = { desc->map, desc->mapsize };
		int v;

		if (!value) {
			struct view_column_options def;

			column_default_options(type, &def);
			v = *(int *) ((char *) &def + desc->offset);
			if (desc->offset != offsetof(struct view_column_options, display))
				v = map.entries[1].value;
			*(int *) field = v;
			return SUCCESS;
		}
		parse_enum(&v, value, &map);
		*(int *) field = v;
		return SUCCESS;
	}
	case COLOPT_STRING: {
		char *dst = field;

		if (!value)
			return error("String value expected");
		return parse_string(dst, value, sizeof(opt->format));
	}
	}
	return SUCCESS;
}

static enum status_code
parse_view_column_spec(const char *spec, enum view_column_type *type, struct view_column_options *opt)
{
	const char *colon = strchr(spec, ':');
	size_t namelen = colon ? (size_t) (colon - spec) : strlen(spec);
	char buf[SIZEOF_STR];
	char *pos, *next;
	bool first = true;

	if (!get_view_column_type(spec, namelen, type))
		return error("Unknown column type: %.*s", (int) namelen, spec);

	column_default_options(*type, opt);
	if (!colon)
		return SUCCESS;

	string_copy(buf, colon + 1);
	for (pos = buf; pos && *pos; pos = next) {
		char *eq;
		const struct column_option_desc *desc;
		enum status_code code;

		next = strchr(pos, ',');
		if (next)
			*next++ = 0;

		eq = strchr(pos, '=');
		if (first && !eq) {
			desc = find_column_option(*type, "display", 7);
			code = parse_column_option(*type, opt, desc, pos);
			if (code != SUCCESS)
				return code;
			first = false;
			continue;
		}
		first = false;

		if (eq)
			*eq++ = 0;
		desc = find_column_option(*type, pos, strlen(pos));
		if (!desc)
			return error("Unknown column option: %s", pos);
		code = parse_column_option(*type, opt, desc, eq);
		if (code != SUCCESS)
			return code;
	}

	return SUCCESS;
}

static enum status_code
parse_view_config(struct view_config *config, const char *argv[])
{
	struct view_config tmp = *config;
	int i;

	tmp.count = 0;
	for (i = 0; argv[i]; i++) {
		enum status_code code;

		if (tmp.count >= (int) ARRAY_SIZE(tmp.types))
			break;
		code = parse_view_column_spec(argv[i], &tmp.types[tmp.count], &tmp.opts[tmp.count]);
		if (code != SUCCESS)
			return code;
		tmp.count++;
	}

	tmp.version = config->version + 1;
	*config = tmp;
	options_version++;
	return SUCCESS;
}

static void
format_column_options(enum view_column_type type, const struct view_column_options *opt,
		      char *buf, size_t bufsize, size_t *pos)
{
	const struct column_option_desc *descs;
	int n = get_column_options(type, &descs);
	char options[SIZEOF_STR] = "";
	size_t optpos = 0;
	char display[64] = "";
	int i;

	for (i = 0; i < n; i++) {
		const struct column_option_desc *desc = &descs[i];
		const char *field = (const char *) opt + desc->offset;
		bool is_display = desc->offset == offsetof(struct view_column_options, display) && i == 0;

		switch (desc->type) {
		case COLOPT_BOOL: {
			bool value = is_display ? *(int *) field : *(bool *) field;

			if (is_display)
				string_format(display, "%s", value ? "yes" : "no");
			else
				string_nformat(options, sizeof(options), &optpos, ",%s=%s", desc->name, value ? "yes" : "no");
			break;
		}
		case COLOPT_ENUM: {
			int value = *(int *) field;
			const char *name = "";
			size_t j;

			for (j = 0; j < desc->mapsize; j++)
				if (desc->map[j].value == value)
					name = desc->map[j].name;
			if (is_display)
				string_format(display, "%s", name);
			else
				string_nformat(options, sizeof(options), &optpos, ",%s=%s", desc->name, name);
			break;
		}
		case COLOPT_INT:
		case COLOPT_WIDTH:
		case COLOPT_OVERFLOW: {
			int value = *(int *) field;

			if (value > 0)
				string_nformat(options, sizeof(options), &optpos, ",%s=%d", desc->name, value);
			else if (value < 0)
				string_nformat(options, sizeof(options), &optpos, ",%s=%d%%", desc->name, -value - 1);
			break;
		}
		case COLOPT_STRING:
			string_nformat(options, sizeof(options), &optpos, ",%s=\"%s\"", desc->name, field);
			break;
		}
	}

	{
		bool display_is_bool = descs && descs[0].type == COLOPT_BOOL;

		if (display_is_bool && !*options && !strcmp(display, "yes"))
			string_nformat(buf, bufsize, pos, "%s", view_column_names[type]);
		else
			string_nformat(buf, bufsize, pos, "%s:%s%s", view_column_names[type], display, options);
	}
}

void
format_view_config(struct view_config *cfg, char *buf, size_t bufsize)
{
	size_t pos = 0;
	int i;

	buf[0] = 0;
	for (i = 0; i < cfg->count; i++) {
		if (i)
			string_nformat(buf, bufsize, &pos, " ");
		format_column_options(cfg->types[i], &cfg->opts[i], buf, bufsize, &pos);
	}
}

/* Handle "main-view-date", "main-view-date-format", etc. */
static enum status_code
set_view_column_option(const char *name, const char *value, bool *found)
{
	int i;

	*found = false;
	for (i = 0; i < view_configs_count; i++) {
		struct view_config *cfg = &view_configs[i];
		size_t len = strlen(cfg->option_name);
		const char *rest;
		int c;

		if (strncmp(name, cfg->option_name, len) || name[len] != '-')
			continue;
		rest = name + len + 1;

		for (c = 0; c < cfg->count; c++) {
			const char *colname = view_column_names[cfg->types[c]];
			size_t collen = strlen(colname);
			const struct column_option_desc *desc;

			if (strncmp(rest, colname, collen))
				continue;
			if (rest[collen] == 0) {
				desc = find_column_option(cfg->types[c], "display", 7);
			} else if (rest[collen] == '-') {
				desc = find_column_option(cfg->types[c], rest + collen + 1, strlen(rest + collen + 1));
			} else {
				continue;
			}
			if (!desc)
				continue;
			*found = true;
			{
				enum status_code code = parse_column_option(cfg->types[c], &cfg->opts[c], desc, value);

				cfg->version++;
				options_version++;
				return code;
			}
		}
	}
	return SUCCESS;
}

/* ------------------------------------------------------------------ */
/* set command */

static enum status_code
parse_option(struct option_info *option, const char *argv[], int argc)
{
	const char *arg = argv[0];

	switch (option->type) {
	case OPT_BOOL:
		*(bool *) option->value = parse_bool_value(arg);
		return SUCCESS;

	case OPT_INT: {
		int value;
		enum status_code code;

		if (!strcmp(option->name, "diff-context") || !strcmp(option->name, "id-width")) {
			code = parse_int(&value, arg, 0, 999999);
		} else if (!strcmp(option->name, "tab-size")) {
			code = parse_int(&value, arg, 1, 1024);
		} else {
			code = parse_int(&value, arg, 0, 1024 * 1024);
		}
		if (code == SUCCESS)
			*(int *) option->value = value;
		return code;
	}

	case OPT_DOUBLE:
		return parse_step(option->value, arg);

	case OPT_ENUM:
		if (option->value == &opt_line_graphics && !strcmp(arg, "auto")) {
			const char *codeset = nl_langinfo(CODESET);

			opt_line_graphics = codeset && !strcmp(codeset, "UTF-8") ? GRAPHIC_UTF_8 : GRAPHIC_DEFAULT;
			return SUCCESS;
		}
		return parse_enum(option->value, arg, &option->map);

	case OPT_STRING:
		return parse_string(option->value, arg, SIZEOF_STR);

	case OPT_DELIM: {
		char buf[16];
		enum status_code code = parse_string(buf, arg, sizeof(buf));

		if (code != SUCCESS)
			return code;
		if (!strcmp(buf, "utf-8") || !strcmp(buf, "utf8"))
			string_copy(opt_truncation_delimiter, "\xe2\x8b\xaf");
		else
			string_copy(opt_truncation_delimiter, buf);
		return SUCCESS;
	}

	case OPT_ARGS: {
		const char ***opt = option->value;

		argv_free(*opt);
		if (!*opt) {
			*opt = xcalloc(1, sizeof(char *));
		}
		if (!argv_append_array(opt, argv))
			return ERROR_OUT_OF_MEMORY;
		(void) argc;
		return SUCCESS;
	}

	case OPT_VIEW: {
		struct view_config *cfg = find_view_config(option->value);

		return parse_view_config(cfg, argv);
	}

	case OPT_REFFORMAT:
		if (!parse_ref_formats(argv))
			return error("Invalid reference format");
		return SUCCESS;
	}

	return SUCCESS;
}

static enum status_code
option_set_command(int argc, const char *argv[])
{
	struct option_info *option;

	if (argc < 2)
		return error("Invalid set command: set option = value");

	if (strcmp(argv[1], "="))
		return error("No value assigned to %s", argv[0]);

	option = find_option_info(argv[0]);
	if (option) {
		static const char *empty[] = { NULL };

		if (option->seen)
			return SUCCESS;

		if (argc < 3) {
			if (option->type == OPT_ARGS || option->type == OPT_VIEW || option->type == OPT_REFFORMAT)
				return parse_option(option, empty, 0);
			if (option->type == OPT_STRING) {
				*(char *) option->value = 0;
				return SUCCESS;
			}
			return error("Invalid set command: set option = value");
		}

		if (option->type == OPT_ARGS || option->type == OPT_VIEW || option->type == OPT_REFFORMAT)
			return parse_option(option, argv + 2, argc - 2);

		if (argc > 3 && option->type == OPT_STRING) {
			char buf[SIZEOF_STR];
			char *joined = argv_to_string_alloc(argv + 2, " ");

			string_copy(buf, joined);
			return parse_string(option->value, buf, SIZEOF_STR);
		}

		return parse_option(option, argv + 2, argc - 2);
	}

	{
		static const char *obsolete[][2] = {
			{ "author-width",		"author" },
			{ "filename-width",		"file-name" },
			{ "line-number-interval",	"line-number" },
			{ "show-author",		"author" },
			{ "show-date",			"date" },
			{ "show-file-size",		"file-size" },
			{ "show-filename",		"file-name" },
			{ "show-id",			"id" },
			{ "show-line-numbers",		"line-number" },
			{ "show-refs",			"commit-title" },
			{ "show-rev-graph",		"commit-title" },
			{ "title-overflow",		"commit-title and text" },
		};
		size_t i;

		for (i = 0; i < ARRAY_SIZE(obsolete); i++)
			if (!strcmp(obsolete[i][0], argv[0]))
				return error("%s has been replaced by the %s column option", obsolete[i][0], obsolete[i][1]);
	}

	if (argc >= 3) {
		bool found;
		enum status_code code = set_view_column_option(argv[0], argv[2], &found);

		if (found)
			return code;
	}

	return error("Unknown option name: %s", argv[0]);
}

enum status_code
set_option_command(int argc, const char *argv[])
{
	return option_set_command(argc, argv);
}

/* ------------------------------------------------------------------ */
/* bind command */

static enum status_code
option_bind_command(int argc, const char *argv[])
{
	struct key key[16];
	size_t keys = 0;
	enum request request;
	struct keymap *keymap;
	const char *key_arg;

	if (argc < 3)
		return error("Invalid key binding: bind keymap key action");

	if (!(keymap = get_keymap(argv[0], strlen(argv[0])))) {
		if (!strcmp(argv[0], "branch"))
			keymap = get_keymap("refs", strlen("refs"));
		if (!keymap)
			return error("Unknown key map: %s", argv[0]);
	}

	for (keys = 0, key_arg = argv[1]; *key_arg && keys < ARRAY_SIZE(key); keys++) {
		enum status_code code = get_key_value(&key_arg, &key[keys]);

		if (code != SUCCESS)
			return code;
	}

	if (*key_arg)
		return error("Except for <Esc> combos only one key is allowed in key combos: %s", argv[1]);

	request = get_request(argv[2]);
	if (request == REQ_UNKNOWN) {
		static const char *obsolete[][2] = {
			{ "view-branch",		"view-refs" },
		};
		static const char *toggles[][2] = {
			{ "diff-context-down",		"diff-context" },
			{ "diff-context-up",		"diff-context" },
			{ "stage-next",			":/^@@" },
			{ "toggle-author",		"author" },
			{ "toggle-changes",		"show-changes" },
			{ "toggle-commit-order",	"show-commit-order" },
			{ "toggle-date",		"date" },
			{ "toggle-files",		"file-filter" },
			{ "toggle-file-filter",		"file-filter" },
			{ "toggle-file-size",		"file-size" },
			{ "toggle-filename",		"filename" },
			{ "toggle-graphic",		"show-graphic" },
			{ "toggle-id",			"id" },
			{ "toggle-ignore-space",	"show-ignore-space" },
			{ "toggle-lineno",		"line-number" },
			{ "toggle-refs",		"commit-title-refs" },
			{ "toggle-rev-graph",		"commit-title-graph" },
			{ "toggle-sort-field",		"sort-field" },
			{ "toggle-sort-order",		"sort-order" },
			{ "toggle-title-overflow",	"commit-title-overflow" },
			{ "toggle-untracked-dirs",	"status-untracked-dirs" },
			{ "toggle-vertical-split",	"show-vertical-split" },
		};
		size_t i;

		for (i = 0; i < ARRAY_SIZE(obsolete); i++) {
			if (!strcmp(obsolete[i][0], argv[2])) {
				request = get_request(obsolete[i][1]);
				break;
			}
		}

		if (request == REQ_UNKNOWN) {
			for (i = 0; i < ARRAY_SIZE(toggles); i++) {
				if (!strcmp(toggles[i][0], argv[2])) {
					if (toggles[i][1][0] == ':')
						return error("%s has been replaced by `%s'", toggles[i][0], toggles[i][1]);
					return error("%s has been replaced by `:toggle %s'", toggles[i][0], toggles[i][1]);
				}
			}
		}
	}

	if (request == REQ_UNKNOWN)
		return add_run_request(keymap, key, keys, argv + 2);

	return add_keybinding(keymap, request, key, keys);
}

/* ------------------------------------------------------------------ */
/* color command */

static bool
set_color(int *color, const char *name)
{
	static const struct enum_map_entry color_map[] = {
		ENUM_MAP_ENTRY("default", COLOR_DEFAULT),
		ENUM_MAP_ENTRY("black", COLOR_BLACK),
		ENUM_MAP_ENTRY("blue", COLOR_BLUE),
		ENUM_MAP_ENTRY("cyan", COLOR_CYAN),
		ENUM_MAP_ENTRY("green", COLOR_GREEN),
		ENUM_MAP_ENTRY("magenta", COLOR_MAGENTA),
		ENUM_MAP_ENTRY("red", COLOR_RED),
		ENUM_MAP_ENTRY("white", COLOR_WHITE),
		ENUM_MAP_ENTRY("yellow", COLOR_YELLOW),
	};
	int value;

	if (map_enum(color, color_map, name))
		return true;
	if (!prefixcmp(name, "color"))
		name += 5;
	if (string_isnumber(name)) {
		value = atoi(name);
		if (value < 256) {
			*color = value;
			return true;
		}
	}
	return false;
}

static bool
set_attribute(int *attribute, const char *name)
{
	static const struct enum_map_entry attr_map[] = {
		ENUM_MAP_ENTRY("normal", A_NORMAL),
		ENUM_MAP_ENTRY("blink", A_BLINK),
		ENUM_MAP_ENTRY("bold", A_BOLD),
		ENUM_MAP_ENTRY("dim", A_DIM),
		ENUM_MAP_ENTRY("reverse", A_REVERSE),
		ENUM_MAP_ENTRY("standout", A_STANDOUT),
		ENUM_MAP_ENTRY("underline", A_UNDERLINE),
		ENUM_MAP_ENTRY("italic", A_ITALIC),
	};

	return map_enum(attribute, attr_map, name);
}

static enum status_code
option_color_command(int argc, const char *argv[])
{
	int fg, bg, attr = 0;
	const char *errmsg = NULL;
	int i;

	if (argc < 3)
		return error("Invalid color mapping: color area fgcolor bgcolor [attrs]");

	if (!set_color(&fg, argv[1]))
		return error("Unknown color: %s", argv[1]);
	if (!set_color(&bg, argv[2]))
		return error("Unknown color: %s", argv[2]);
	for (i = 3; i < argc; i++) {
		int a;

		if (!set_attribute(&a, argv[i]))
			return error("Unknown color attribute: %s", argv[i]);
		attr |= a;
	}

	if (!line_rule_set_color(argv[0], fg, bg, attr, &errmsg))
		return error("Unknown color name: %s", argv[0]);
	return SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Config files */

static const char *config_file_path;

static char *
expand_path(const char *path, char *buf, size_t bufsize)
{
	if (path[0] == '~' && (path[1] == '/' || !path[1])) {
		const char *home = getenv("HOME");

		snprintf(buf, bufsize, "%s%s", home ? home : "", path + 1);
	} else if (path[0] != '/' && config_file_path && strchr(config_file_path, '/')) {
		const char *slash = strrchr(config_file_path, '/');

		snprintf(buf, bufsize, "%.*s/%s", (int) (slash - config_file_path), config_file_path, path);
	} else {
		snprintf(buf, bufsize, "%s", path);
	}
	return buf;
}

static enum status_code
option_source_command(int argc, const char *argv[])
{
	bool quiet = false;
	const char *path;
	char buf[SIZEOF_STR];

	if (argc >= 1 && !strcmp(argv[0], "-q")) {
		quiet = true;
		argv++;
		argc--;
	}

	if (argc != 1)
		return error("Invalid source command: source [-q] path");

	path = expand_path(argv[0], buf, sizeof(buf));
	return load_option_file(path, quiet);
}

static enum status_code
set_option(const char *opt, int argc, const char *argv[])
{
	if (!strcmp(opt, "color"))
		return option_color_command(argc, argv);
	if (!strcmp(opt, "set"))
		return option_set_command(argc, argv);
	if (!strcmp(opt, "bind"))
		return option_bind_command(argc, argv);
	if (!strcmp(opt, "source"))
		return option_source_command(argc, argv);

	return error("Unknown option command: %s", opt);
}

enum status_code
execute_option_line(char *line)
{
	const char *argv[SIZEOF_ARG];
	int argc = 0;

	if (!argv_from_string(argv, &argc, line))
		return error("Too many option arguments");
	if (argc < 1)
		return SUCCESS;
	return set_option(argv[0], argc - 1, argv + 1);
}

enum status_code
execute_option_argv(int argc, const char *argv[])
{
	if (argc < 1)
		return SUCCESS;
	return set_option(argv[0], argc - 1, argv + 1);
}

static char *config_errors;
static size_t config_errors_len;

static void
config_error(const char *path, int lineno, const char *msg)
{
	char buf[SIZEOF_STR * 2];
	int n = snprintf(buf, sizeof(buf), "Error in %s line %d: %s\n", path, lineno, msg);

	config_errors = xrealloc(config_errors, config_errors_len + n + 1);
	memcpy(config_errors + config_errors_len, buf, n + 1);
	config_errors_len += n;
}

const char *
get_config_errors(void)
{
	return config_errors;
}

static enum status_code
load_option_data(const char *path, char *data, size_t len)
{
	char *pos = data;
	char *end = data + len;
	int lineno = 0;
	char line[SIZEOF_MED_STR];

	while (pos < end) {
		size_t linelen = 0;
		int startline = lineno + 1;

		/* Collect continued lines */
		while (pos < end) {
			char *eol = memchr(pos, '\n', end - pos);
			size_t n;

			if (!eol)
				eol = end;
			lineno++;
			n = eol - pos;
			if (linelen + n >= sizeof(line) - 1)
				n = sizeof(line) - 1 - linelen;
			memcpy(line + linelen, pos, n);
			linelen += n;
			line[linelen] = 0;
			pos = eol + 1;
			if (linelen > 0 && line[linelen - 1] == '\\') {
				line[--linelen] = ' ';
				linelen++;
				continue;
			}
			break;
		}
		line[linelen] = 0;

		/* Strip comments (outside quotes) */
		{
			char *p;
			int quote = 0;

			for (p = line; *p; p++) {
				if ((*p == '"' || *p == '\'') && (!quote || quote == *p))
					quote = quote ? 0 : *p;
				else if (*p == '#' && !quote) {
					*p = 0;
					break;
				}
			}
		}

		{
			char *trimmed = string_trim(line);
			enum status_code code;

			if (!*trimmed)
				continue;
			code = execute_option_line(trimmed);
			if (code != SUCCESS)
				config_error(path, startline, get_status_message(code));
		}
	}

	return SUCCESS;
}

enum status_code
load_option_file(const char *path, bool quiet)
{
	size_t len;
	char *data;
	const char *old_path = config_file_path;
	enum status_code code;

	if (!path || !*path)
		return SUCCESS;
	data = read_file(path, &len);
	if (!data) {
		if (quiet)
			return SUCCESS;
		return error("File does not exist: %s", path);
	}

	config_file_path = path;
	code = load_option_data(path, data, len);
	config_file_path = old_path;
	free(data);
	return code;
}

extern const char builtin_config[];

static void
init_keymaps(void)
{
	static const char *names[] = {
		"generic", "search", "main", "diff", "log", "reflog", "tree", "blob",
		"blame", "refs", "status", "stage", "stash", "grep", "pager", "help",
		"toggle",
	};
	size_t i;

	if (get_keymaps_count())
		return;
	for (i = 0; i < ARRAY_SIZE(names); i++)
		add_keymap(names[i]);
}

enum status_code
load_options(void)
{
	const char *tigrc_user = getenv("TIGRC_USER");
	const char *tigrc_system = getenv("TIGRC_SYSTEM");
	const char *tig_diff_opts = getenv("TIG_DIFF_OPTS");
	bool diff_opts_from_args = opt_diff_options != NULL;
	char buf[SIZEOF_STR];

	init_line_rules();
	init_keymaps();

	if (!tigrc_system)
		tigrc_system = "/etc/tigrc";

	if (!*tigrc_system || access(tigrc_system, R_OK)) {
		char *data = xstrdup(builtin_config);

		load_option_data("builtin", data, strlen(data));
		free(data);
	} else {
		load_option_file(tigrc_system, true);
	}

	if (!tigrc_user) {
		const char *xdg = getenv("XDG_CONFIG_HOME");
		const char *home = getenv("HOME");

		if (xdg && *xdg) {
			snprintf(buf, sizeof(buf), "%s/tig/config", xdg);
			if (access(buf, R_OK))
				snprintf(buf, sizeof(buf), "%s/.tigrc", home ? home : "");
		} else {
			snprintf(buf, sizeof(buf), "%s/.config/tig/config", home ? home : "");
			if (access(buf, R_OK))
				snprintf(buf, sizeof(buf), "%s/.tigrc", home ? home : "");
		}
		tigrc_user = buf;
	}
	load_option_file(tigrc_user, true);

	if (!diff_opts_from_args && tig_diff_opts && *tig_diff_opts) {
		static char diff_opts_buf[SIZEOF_STR];
		const char *argv[SIZEOF_ARG];
		int argc = 0;

		string_copy(diff_opts_buf, tig_diff_opts);
		if (argv_from_string(argv, &argc, diff_opts_buf)) {
			argv_free(opt_diff_options);
			argv_append_array(&opt_diff_options, argv);
		}
	}

	return SUCCESS;
}

/* tig.* options from git config */
enum status_code
set_option_from_git_config(const char *name, const char *value)
{
	char buf[SIZEOF_MED_STR];
	const char *argv[SIZEOF_ARG];
	int argc = 0;

	if (!prefixcmp(name, "color.")) {
		return SUCCESS;
	}

	name += STRING_SIZE("tig.");
	if (!prefixcmp(name, "color.")) {
		const char *area = name + STRING_SIZE("color.");

		snprintf(buf, sizeof(buf), "color %s %s", area, value);
	} else if (!prefixcmp(name, "bind.")) {
		snprintf(buf, sizeof(buf), "bind %s %s", name + STRING_SIZE("bind."), value);
	} else {
		snprintf(buf, sizeof(buf), "set %s = %s", name, value);
	}

	if (!argv_from_string(argv, &argc, buf))
		return SUCCESS;
	return execute_option_argv(argc, argv);
}

/* ------------------------------------------------------------------ */
/* Command line options */

void
update_options_from_argv(const char *argv[])
{
	int next, flags_pos;

	for (next = flags_pos = 0; argv && argv[next]; next++) {
		const char *flag = argv[next];
		int value = -1;

		if (!strcmp(flag, "--date-order") || !strcmp(flag, "--topo-order") ||
		    !strcmp(flag, "--author-date-order") || !strcmp(flag, "--reverse")) {
			if (!strcmp(flag, "--date-order"))
				opt_commit_order = COMMIT_ORDER_DATE;
			else if (!strcmp(flag, "--topo-order"))
				opt_commit_order = COMMIT_ORDER_TOPO;
			else if (!strcmp(flag, "--author-date-order"))
				opt_commit_order = COMMIT_ORDER_AUTHOR_DATE;
			else
				opt_commit_order = COMMIT_ORDER_REVERSE;
			mark_option_seen_name("commit-order");
			continue;
		}

		if (!strcmp(flag, "--ignore-all-space") || !strcmp(flag, "-w")) {
			opt_ignore_space = IGNORE_SPACE_ALL;
			mark_option_seen_name("ignore-space");
			continue;
		}
		if (!strcmp(flag, "--ignore-space-change") || !strcmp(flag, "-b")) {
			opt_ignore_space = IGNORE_SPACE_SOME;
			mark_option_seen_name("ignore-space");
			continue;
		}
		if (!strcmp(flag, "--ignore-space-at-eol")) {
			opt_ignore_space = IGNORE_SPACE_AT_EOL;
			mark_option_seen_name("ignore-space");
			continue;
		}

		if (!strcmp(flag, "--no-notes")) {
			opt_show_notes = false;
			mark_option_seen_name("show-notes");
			continue;
		}

		if (!prefixcmp(flag, "--show-notes") ||
		    !prefixcmp(flag, "--notes")) {
			opt_show_notes = true;
			string_copy(opt_notes_arg, flag);
			mark_option_seen_name("show-notes");
			continue;
		}

		if (!prefixcmp(flag, "-U")
		    && parse_int(&value, flag + 2, 0, 999999) == SUCCESS) {
			opt_diff_context = value;
			mark_option_seen_name("diff-context");
			continue;
		}

		if (!strcmp(flag, "--word-diff") ||
		    !strcmp(flag, "--word-diff=plain")) {
			opt_word_diff = true;
			mark_option_seen_name("word-diff");
			continue;
		}

		argv[flags_pos++] = flag;
	}

	if (argv)
		argv[flags_pos] = NULL;
}

