actions.command:
cat > /workspace/src/display.c <<'EOF'
/* Display: curses setup, windows, title and status, input and prompts */
#include "tigview.h"

struct view *display[2];
unsigned int current_view;
bool cursed;
bool input_mode;
WINDOW *status_win;

static WINDOW *display_win[2];
static WINDOW *display_title[2];
static WINDOW *display_sep;
static bool status_empty = true;
static FILE *opt_tty;
static bool display_vsplit;

#define MIN_VIEW_HEIGHT 4
#define MIN_VIEW_WIDTH 4

void
done_display(void)
{
	if (cursed) {
		if (status_win) {
			werase(status_win);
			doupdate();
		}
		curs_set(1);
		endwin();
	}
	cursed = false;
}

void
die(const char *err, ...)
{
	va_list args;

	done_display();

	va_start(args, err);
	fputs("tig: ", stderr);
	vfprintf(stderr, err, args);
	fputs("\n", stderr);
	va_end(args);
	exit(1);
}

void
enable_mouse(bool enable)
{
	if (enable)
		mousemask(ALL_MOUSE_EVENTS | REPORT_MOUSE_POSITION, NULL);
	else
		mousemask(0, NULL);
}

static void
set_terminal_modes(void)
{
	nonl();
	raw();
	noecho();
	curs_set(0);
	leaveok(stdscr, false);
}

void
init_display(void)
{
	bool no_display = !!getenv("TIG_NO_DISPLAY");
	int x, y;

	if (!no_display && isatty(STDIN_FILENO)) {
		cursed = !!initscr();
		opt_tty = stdin;
	} else {
		FILE *out_tty;

		opt_tty = fopen("/dev/tty", "r+");
		out_tty = no_display ? fopen("/dev/null", "w+") : opt_tty;
		if (!opt_tty || !out_tty)
			die("Failed to open tty for input");
		cursed = !!newterm(NULL, out_tty, opt_tty);
	}

	if (!cursed)
		die("Failed to initialize curses");

	set_terminal_modes();
	init_colors();

	getmaxyx(stdscr, y, x);
	status_win = newwin(1, x, y - 1, 0);
	if (!status_win)
		die("Failed to create status window");

	keypad(status_win, true);
	wbkgdset(status_win, get_line_attr(NULL, LINE_STATUS));
	enable_mouse(opt_mouse);
	set_tabsize(opt_tab_size);
}

/* ------------------------------------------------------------------ */
/* Layout */

static int
apply_horizontal_split(struct view *base, struct view *view)
{
	int height = apply_step(opt_split_view_height, base->height);

	(void) view;
	height = MAX(height, MIN_VIEW_HEIGHT);
	height = MIN(height, base->height - MIN_VIEW_HEIGHT);
	return height;
}

static int
apply_vertical_split(int base_width)
{
	int width = apply_step(opt_split_view_width, base_width);

	width = MAX(width, MIN_VIEW_WIDTH);
	width = MIN(width, base_width - MIN_VIEW_WIDTH);
	return width;
}

static void
redraw_display_separator(bool clear)
{
	if (display_sep) {
		chtype separator = opt_line_graphics ? ACS_VLINE : '|';

		if (clear)
			wclear(display_sep);
		wbkgd(display_sep, separator + get_line_attr(NULL, LINE_TITLE_BLUR));
		wnoutrefresh(display_sep);
	}
}

static void
create_or_move_display_separator(int height, int x)
{
	if (!display_sep) {
		display_sep = newwin(height, 1, 0, x);
	} else {
		wresize(display_sep, height, 1);
		mvwin(display_sep, 0, x);
	}
}

static void
remove_display_separator(void)
{
	if (display_sep) {
		delwin(display_sep);
		display_sep = NULL;
	}
}

void
resize_display(void)
{
	int x, y, i;
	struct view *base = display[0];
	struct view *view = display[1] ? display[1] : display[0];
	bool vsplit;

	if (!base)
		return;

	getmaxyx(stdscr, base->height, base->width);

	/* Make room for the status window. */
	base->height -= 1;

	vsplit = vertical_split_is_enabled(opt_vertical_split, base->height, base->width);
	display_vsplit = false;

	if (view != base) {
		if (vsplit) {
			display_vsplit = true;
			view->height = base->height;
			view->width  = apply_vertical_split(base->width);
			base->width -= view->width;

			/* Make room for the separator bar. */
			view->width -= 1;

			create_or_move_display_separator(base->height, base->width);
			redraw_display_separator(false);
		} else {
			remove_display_separator();

			view->width   = base->width;
			view->height  = apply_horizontal_split(base, view);
			base->height -= view->height;
		}

		/* Make room for the title bar. */
		view->height -= 1;
	} else {
		remove_display_separator();
	}

	/* Make room for the title bar. */
	base->height -= 1;

	x = y = 0;

	foreach_displayed_view (view, i) {
		if (!display_win[i]) {
			display_win[i] = newwin(view->height, view->width, y, x);
			if (!display_win[i])
				die("Failed to create %s view", view->name);

			scrollok(display_win[i], false);

			display_title[i] = newwin(1, view->width, y + view->height, x);
			if (!display_title[i])
				die("Failed to create title window");

		} else {
			wresize(display_win[i], view->height, view->width);
			mvwin(display_win[i],   y, x);
			wresize(display_title[i], 1, view->width);
			mvwin(display_title[i], y + view->height, x);
		}

		view->win = display_win[i];
		view->title = display_title[i];

		if (vsplit)
			x += view->width + 1;
		else
			y += view->height + 1;
	}

	/* Free unused windows */
	for (i = displayed_views(); i < 2; i++) {
		if (display_win[i]) {
			delwin(display_win[i]);
			delwin(display_title[i]);
			display_win[i] = display_title[i] = NULL;
		}
	}
}

void
redraw_display(bool clear)
{
	struct view *view;
	int i;

	foreach_displayed_view (view, i) {
		if (clear)
			wclear(view->win);
		redraw_view(view);
		update_view_title(view);
	}

	redraw_display_separator(clear);
}

void
maximize_view(struct view *view, bool redraw)
{
	memset(display, 0, sizeof(display));
	current_view = 0;
	display[current_view] = view;
	resize_display();
	if (redraw) {
		redraw_display(false);
		report_clear();
	}
}

void
split_view(struct view *prev, struct view *view)
{
	display[1] = view;
	current_view = opt_focus_child ? 1 : 0;
	view->parent = prev;
	resize_display();

	if (prev->pos.lineno - prev->pos.offset >= (unsigned long) prev->height) {
		/* Take the title line into account. */
		int lines = prev->pos.lineno - prev->pos.offset - prev->height + 1;

		/* Scroll the view that was split if the current line is
		 * outside the new limited view. */
		do_scroll_view(prev, lines);
	}

	if (view != prev && view_is_displayed(prev)) {
		/* "Blur" the previous view. */
		update_view_title(prev);
	}
}

/* ------------------------------------------------------------------ */
/* Title and status */

void
update_view_title(struct view *view)
{
	WINDOW *window;
	struct line *line;
	char buf[SIZEOF_STR];
	size_t bufpos = 0;
	unsigned int view_lines, lines;
	int pct_col;
	char pct[16];

	if (!view || !view_is_displayed(view) || !view->title)
		return;

	window = view->title;
	line = view->lines ? &view->line[view->pos.lineno] : NULL;

	if (view == display[current_view])
		wbkgdset(window, get_line_attr(NULL, LINE_TITLE_FOCUS));
	else
		wbkgdset(window, get_line_attr(NULL, LINE_TITLE_BLUR));

	werase(window);

	string_format_from(buf, &bufpos, "[%s]", view->name);
	if (*view->ref)
		string_format_from(buf, &bufpos, " %s", view->ref);

	if (!view_has_flags(view, VIEW_CUSTOM_STATUS) && line && view_has_line(view, line) &&
	    line->lineno) {
		string_format_from(buf, &bufpos, " - %s %u of %zu",
				   view->ops->type,
				   line->lineno,
				   view->lines - view->custom_lines);
	}

	view_lines = view->pos.offset + view->height;
	lines = view->lines ? MIN(view_lines, view->lines) * 100 / view->lines : 0;
	snprintf(pct, sizeof(pct), "%u%%", lines);
	pct_col = view->width - (int) strlen(pct);

	{
		size_t outlen;
		int max = pct_col - 1;
		const char *text = buf;
		int width = 0, trimmed = 0;
		size_t len = utf8_length(&text, -1, 0, &width, max > 0 ? max : 0, &trimmed, false, 1);
		const char *out = encoding_convert_out(buf, len, &outlen);

		if (max > 0)
			mvwaddnstr(window, 0, 0, out, outlen);
	}
	if (pct_col >= 0)
		mvwaddstr(window, 0, pct_col, pct);

	wnoutrefresh(window);
}

void
update_all_titles(void)
{
	struct view *view;
	int i;

	foreach_displayed_view (view, i)
		update_view_title(view);
}

static void
status_message(const char *msg)
{
	werase(status_win);
	wmove(status_win, 0, 0);
	if (*msg) {
		size_t outlen;
		const char *out = encoding_convert_out(msg, strlen(msg), &outlen);

		waddnstr(status_win, out, outlen);
		status_empty = false;
	} else {
		status_empty = true;
	}
	wclrtoeol(status_win);
	wnoutrefresh(status_win);
}

void
report(const char *msg, ...)
{
	struct view *view = display[current_view];
	char buf[SIZEOF_STR];
	va_list args;

	va_start(args, msg);
	vsnprintf(buf, sizeof(buf), msg, args);
	va_end(args);

	if (input_mode)
		return;

	if (!view)
		die("%s", buf);

	if (!status_empty || *buf)
		status_message(buf);

	update_view_title(view);
}

void
report_clear(void)
{
	struct view *view = display[current_view];

	if (!view)
		return;

	if (!input_mode && !status_empty) {
		werase(status_win);
		wnoutrefresh(status_win);
	}
	status_empty = true;
	update_view_title(view);
}

static void
update_status_input(const char *msg)
{
	werase(status_win);
	wmove(status_win, 0, 0);
	{
		size_t outlen;
		const char *out = encoding_convert_out(msg, strlen(msg), &outlen);

		waddnstr(status_win, out, outlen);
	}
	wclrtoeol(status_win);
	wnoutrefresh(status_win);
	status_empty = !*msg;
}

/* ------------------------------------------------------------------ */
/* Script handling */

static char *script_data;
static size_t script_len;
static size_t script_pos;
static bool script_active;
static const char *script_line = "";
static char script_line_buf[SIZEOF_MED_STR];
static bool script_line_is_prompt;

bool
open_script(const char *path)
{
	size_t len;
	char *data;

	if (!path || !*path) {
		/* read from stdin */
		data = NULL;
		{
			size_t alloc = 0;
			len = 0;
			while (true) {
				ssize_t n;
				if (alloc - len < 4096) {
					alloc = alloc ? alloc * 2 : 8192;
					data = xrealloc(data, alloc + 1);
				}
				n = read(STDIN_FILENO, data + len, alloc - len);
				if (n <= 0)
					break;
				len += n;
			}
			if (!data)
				data = xcalloc(1, 1);
			data[len] = 0;
		}
	} else {
		data = read_file(path, &len);
		if (!data)
			return false;
	}

	free(script_data);
	script_data = data;
	script_len = len;
	script_pos = 0;
	script_active = true;
	script_line = "";
	script_line_is_prompt = false;
	return true;
}

bool
is_script_executing(void)
{
	return script_active;
}

static bool
read_script(struct key *key)
{
	enum status_code code;

	while (!script_line || !*script_line) {
		if (script_line_is_prompt) {
			script_line = "<Enter>";
			script_line_is_prompt = false;
			break;
		}

		if (script_pos >= script_len) {
			script_active = false;
			return false;
		}

		{
			char *start = script_data + script_pos;
			char *eol = memchr(start, '\n', script_len - script_pos);
			size_t n = eol ? (size_t) (eol - start) : script_len - script_pos;

			if (n >= sizeof(script_line_buf))
				n = sizeof(script_line_buf) - 1;
			memcpy(script_line_buf, start, n);
			script_line_buf[n] = 0;
			script_pos += (eol ? (size_t) (eol - start) + 1 : script_len - script_pos);
		}

		{
			char *line = script_line_buf;
			size_t l = strlen(line);

			while (l > 0 && (line[l - 1] == '\r'))
				line[--l] = 0;
			if (!*line || *line == '#')
				continue;
			script_line = line;
			script_line_is_prompt = *line == ':';
		}
	}

	code = get_key_value(&script_line, key);
	if (code != SUCCESS)
		die("Error reading script: %s", get_status_message(code));
	return true;
}

/* ------------------------------------------------------------------ */
/* Input */

static void
key_from_input(int status, wint_t ch, struct key *key)
{
	memset(key, 0, sizeof(*key));

	if (status == KEY_CODE_YES) {
		key->value = ch;
		return;
	}

	if (ch == KEY_RETURN || ch == KEY_TAB || ch == KEY_ESC || ch == 0x7f) {
		key->value = ch == 0x7f ? KEY_BACKSPACE : (int) ch;
		return;
	}

	if (ch < 0x20) {
		key->control = true;
		key->value = tolower((int) (ch | 0x40));
		return;
	}

	{
		mbstate_t state;
		char buf[MB_LEN_MAX + 1];
		size_t n;

		memset(&state, 0, sizeof(state));
		n = wcrtomb(buf, (wchar_t) ch, &state);
		if (n == (size_t) -1 || n == 0) {
			key->bytes[0] = (char) ch;
			key->bytes[1] = 0;
		} else {
			if (n >= sizeof(key->bytes))
				n = sizeof(key->bytes) - 1;
			memcpy(key->bytes, buf, n);
			key->bytes[n] = 0;
		}
	}
}

int
get_input(int prompt_position, struct key *key)
{
	struct view *view;
	int i, cursor_y, cursor_x;

	if (prompt_position > 0)
		curs_set(1);
	else
		curs_set(0);

	memset(key, 0, sizeof(*key));

	while (true) {
		wint_t ch;
		int status;

		update_views();

		/* Update the cursor position. */
		if (prompt_position) {
			getbegyx(status_win, cursor_y, cursor_x);
			cursor_x = prompt_position;
		} else {
			view = display[current_view];
			getbegyx(view->win, cursor_y, cursor_x);
			cursor_x = view->width - 1;
			cursor_y += view->pos.lineno - view->pos.offset;
		}
		setsyx(cursor_y, cursor_x);
		wmove(status_win, 0, prompt_position > 0 ? prompt_position : 0);
		if (!prompt_position) {
			view = display[current_view];
			wmove(view->win, view->pos.lineno - view->pos.offset, view->width - 1);
			wnoutrefresh(view->win);
		} else {
			wnoutrefresh(status_win);
		}

		/* Refresh, accept single keystroke of input */
		doupdate();

		if (is_script_executing()) {
			if (read_script(key)) {
				if (key->value || key->control || key->escape)
					return key->control ? 0 : key->value;
				return 0;
			}
		}

		wtimeout(status_win, -1);
		status = wget_wch(status_win, &ch);

		if (status == ERR)
			continue;

		if (status == KEY_CODE_YES && ch == KEY_RESIZE) {
			int height, width;

			getmaxyx(stdscr, height, width);
			wresize(status_win, 1, width);
			mvwin(status_win, height - 1, 0);
			wnoutrefresh(status_win);
			resize_display();
			redraw_display(true);
			continue;
		}

		if (status != KEY_CODE_YES && ch == KEY_ESC) {
			/* Check for <Esc>key combos */
			wint_t next;
			int st;

			wtimeout(status_win, 0);
			st = wget_wch(status_win, &next);
			wtimeout(status_win, -1);
			if (st != ERR) {
				key_from_input(st, next, key);
				key->escape = true;
				return key->value;
			}
		}

		key_from_input(status, ch, key);
		foreach_displayed_view(view, i)
			(void) view;
		return key->control ? 0 : key->value;
	}
}

/* ------------------------------------------------------------------ */
/* Prompts */

enum input_status {
	INPUT_OK,
	INPUT_SKIP,
	INPUT_STOP,
	INPUT_CANCEL,
	INPUT_DELETE,
};

static char *
prompt_input(const char *prompt, bool allow_empty)
{
	static char buf[SIZEOF_STR];
	unsigned char chars_length[SIZEOF_STR];
	enum input_status status = INPUT_OK;
	size_t promptlen = strlen(prompt);
	int pos = 0, chars = 0;
	struct key key;

	buf[0] = 0;
	input_mode = true;

	while (status == INPUT_OK || status == INPUT_SKIP) {
		char msg[SIZEOF_STR * 2];

		snprintf(msg, sizeof(msg), "%s%.*s", prompt, pos, buf);
		update_status_input(msg);

		get_input(pos + promptlen, &key);

		if (key.value == KEY_RETURN || key.value == KEY_ENTER ||
		    (key.control && key.value == 'j')) {
			status = pos || allow_empty ? INPUT_STOP : INPUT_CANCEL;
		} else if (key.value == KEY_BACKSPACE || (key.control && key.value == 'h')) {
			if (chars > 0) {
				pos -= chars_length[--chars];
				buf[pos] = 0;
			} else {
				status = INPUT_CANCEL;
			}
		} else if (key.value == KEY_ESC || (key.control && (key.value == 'c' || key.value == 'g'))) {
			status = INPUT_CANCEL;
		} else if (key.control && key.value == 'u') {
			pos = chars = 0;
			buf[0] = 0;
		} else if (*key.bytes && !key.control && !key.escape) {
			int len = strlen(key.bytes);

			if (pos + len >= (int) sizeof(buf) - 1) {
				report("Input string too long");
				input_mode = false;
				return NULL;
			}
			memcpy(buf + pos, key.bytes, len);
			pos += len;
			buf[pos] = 0;
			chars_length[chars++] = len;
		}
	}

	input_mode = false;
	update_status_input("");

	if (status == INPUT_CANCEL)
		return NULL;

	buf[pos] = 0;
	return buf;
}

char *
read_prompt(const char *prompt)
{
	return prompt_input(prompt, false);
}

char *
read_prompt_allow_empty(const char *prompt)
{
	return prompt_input(prompt, true);
}

bool
prompt_yesno(const char *prompt)
{
	char msg[SIZEOF_STR];
	struct key key;
	bool result = false;

	snprintf(msg, sizeof(msg), "%s [Yy/Nn]", prompt);
	input_mode = true;
	while (true) {
		update_status_input(msg);
		get_input(strlen(msg), &key);
		if (*key.bytes == 'y' || *key.bytes == 'Y') {
			result = true;
			break;
		}
		if (*key.bytes == 'n' || *key.bytes == 'N' || key.value == KEY_ESC ||
		    (key.control && key.value == 'c'))
			break;
	}
	input_mode = false;
	update_status_input("");
	return result;
}

struct menu_item {
	int hotkey;
	const char *text;
	void *data;
};

bool
prompt_menu(const char *prompt, void *menu_items, int *selected)
{
	struct menu_item *items = menu_items;
	enum input_status status = INPUT_OK;
	struct key key;
	int size = 0;

	while (items[size].text)
		size++;

	input_mode = true;
	while (status == INPUT_OK) {
		struct menu_item *item = &items[*selected];
		char left[SIZEOF_STR], right[64];
		int cols = getmaxx(status_win);
		int pad;

		snprintf(left, sizeof(left), "%s %s [%c]", prompt, item->text, item->hotkey);
		snprintf(right, sizeof(right), "(%d of %d)", *selected + 1, size);
		werase(status_win);
		mvwaddstr(status_win, 0, 0, left);
		pad = cols - (int) strlen(right);
		if (pad > (int) strlen(left))
			mvwaddstr(status_win, 0, pad, right);
		wnoutrefresh(status_win);

		get_input(cols - 1, &key);

		if (key.value == KEY_RETURN || key.value == KEY_ENTER ||
		    (key.control && key.value == 'j')) {
			status = INPUT_STOP;
		} else if (key.value == KEY_LEFT || key.value == KEY_UP) {
			*selected = *selected - 1;
			if (*selected < 0)
				*selected = size - 1;
		} else if (key.value == KEY_RIGHT || key.value == KEY_DOWN) {
			*selected = (*selected + 1) % size;
		} else if (key.value == KEY_ESC || (key.control && key.value == 'c')) {
			status = INPUT_CANCEL;
		} else if (*key.bytes) {
			int i;

			for (i = 0; items[i].text; i++)
				if (items[i].hotkey == key.bytes[0] && !key.bytes[1]) {
					*selected = i;
					status = INPUT_STOP;
					break;
				}
		}
	}
	input_mode = false;
	update_status_input("");

	return status != INPUT_CANCEL;
}

/* ------------------------------------------------------------------ */
/* Saving the display */

static void
append_window_row(char *buf, size_t bufsize, size_t *pos, WINDOW *win, int row, int width)
{
	int col;

	for (col = 0; col < width; col++) {
		cchar_t cell;
		wchar_t wch[CCHARW_MAX + 1];
		attr_t attrs;
		short pair;

		if (mvwin_wch(win, row, col, &cell) == ERR) {
			if (*pos < bufsize - 1)
				buf[(*pos)++] = ' ';
			continue;
		}
		if (getcchar(&cell, wch, &attrs, &pair, NULL) == ERR || !wch[0]) {
			if (*pos < bufsize - 1)
				buf[(*pos)++] = ' ';
			continue;
		}

		{
			char mb[MB_LEN_MAX * (CCHARW_MAX + 1)];
			mbstate_t state;
			size_t n = 0;
			int k;

			memset(&state, 0, sizeof(state));
			for (k = 0; wch[k] && k < CCHARW_MAX; k++) {
				size_t r;

				if (attrs & A_ALTCHARSET) {
					mb[n++] = (char) wch[k];
					continue;
				}
				r = wcrtomb(mb + n, wch[k], &state);
				if (r == (size_t) -1) {
					mb[n++] = '?';
				} else {
					n += r;
				}
			}
			if (*pos + n < bufsize - 1) {
				memcpy(buf + *pos, mb, n);
				*pos += n;
			}
			{
				int w = wcwidth(wch[0]);

				if (w > 1 && !(attrs & A_ALTCHARSET))
					col += w - 1;
			}
		}
	}
	buf[*pos] = 0;
}

bool
save_display(const char *path)
{
	FILE *file = fopen(path, "w");
	struct view *view;
	int i, row;
	int lines = getmaxy(stdscr) - 1;

	if (!file)
		return false;

	for (row = 0; row < lines; row++) {
		char buf[SIZEOF_MED_STR];
		size_t pos = 0;

		buf[0] = 0;
		if (display_vsplit && display[1]) {
			foreach_displayed_view (view, i) {
				if (i == 1 && pos < sizeof(buf) - 1)
					buf[pos++] = '|';
				if (row < view->height)
					append_window_row(buf, sizeof(buf), &pos, view->win, row, view->width);
				else if (row == view->height)
					append_window_row(buf, sizeof(buf), &pos, view->title, 0, view->width);
			}
		} else {
			int y = 0;

			foreach_displayed_view (view, i) {
				if (row >= y && row < y + view->height) {
					append_window_row(buf, sizeof(buf), &pos, view->win, row - y, view->width);
					break;
				}
				if (row == y + view->height) {
					append_window_row(buf, sizeof(buf), &pos, view->title, 0, view->width);
					break;
				}
				y += view->height + 1;
			}
		}

		/* Trim trailing whitespace, keeping at least one character */
		while (pos > 1 && buf[pos - 1] == ' ')
			pos--;
		buf[pos] = 0;
		fprintf(file, "%s\n", buf);
	}

	fclose(file);
	return true;
}

/* ------------------------------------------------------------------ */
/* External commands */

bool
open_external_viewer(const char *argv[], const char *dir, bool silent, bool confirm,
		     bool echo, bool quick, bool do_refresh, const char *notice)
{
	bool ok;

	(void) quick;
	(void) do_refresh;

	if (echo) {
		char buf[SIZEOF_STR] = "";

		io_run_buf(argv, buf, sizeof(buf), dir, false);
		if (*buf) {
			report("%s", buf);
			return true;
		}
		report("No output");
		return true;
	}

	if (silent) {
		ok = io_run_bg(argv, dir);
	} else {
		def_prog_mode();
		endwin();
		ok = io_run_fg(argv, dir);
		if (confirm || !ok) {
			if (!ok && *notice)
				fprintf(stderr, "%s", notice);
			if (!quick) {
				FILE *tty = opt_tty ? opt_tty : stdin;
				int c;

				fprintf(stderr, "Press Enter to continue");
				fflush(stderr);
				while ((c = fgetc(tty)) != EOF && c != '\n' && c != '\r')
					;
			}
		}
		reset_prog_mode();
		refresh();
		redraw_display(true);
	}

	return ok;
}
