	va_list args;

	va_start(args, fmt);
	vsnprintf(buf, sizeof(buf), fmt, args);
	va_end(args);
	buflen = strlen(buf);

	newbox = xcalloc(1, sizeof(struct box) + cells * sizeof(struct box_cell) + textlen + buflen + 1);
	memcpy(newbox, box, sizeof(struct box) + (cells - 1) * sizeof(struct box_cell) + sizeof(struct box_cell));
	newtext = (char *) &newbox->cell[cells];
	memcpy(newtext, box->text, textlen);
	memcpy(newtext + textlen, buf, buflen);
	newtext[textlen + buflen] = 0;
	newbox->text = newtext;
	newbox->cell[cells - 1].length += buflen;
	free(box);
	line->data = newbox;
	line->dirty = 1;
	(void) view;
	return true;
}

struct line *
find_line_by_type(struct view *view, struct line *line, line_type_t type, int direction)
{
	for (; view_has_line(view, line); line += direction)
		if (line->type == type)
			return line;

	return NULL;
}

/* ------------------------------------------------------------------ */
/* Argument formatting */

struct format_var {
	const char *name;
	const char *value;
	const char *value_if_empty;
	const unsigned long *number;
};

static bool
format_expand_arg(struct format_var *vars, size_t vars_size, const char *name, const char *end,
		  char *buf, size_t bufsize, size_t *bufpos)
{
	size_t i;

	if (!prefixcmp(name, "%(prompt")) {
		const char *prompt = "Command argument: ";
		char msgbuf[SIZEOF_STR];
		const char *value;
		const char *msgstart = name + STRING_SIZE("%(prompt");
		const int msglen = end - msgstart - 1;

		if (end && msglen > 0 && string_format(msgbuf, "%.*s", msglen, msgstart)) {
			const char *msg = msgbuf;

			while (isspace((unsigned char) *msg))
				msg++;
			if (*msg)
				prompt = msg;
		}

		value = read_prompt(prompt);
		if (value == NULL)
			return false;
		return string_nformat(buf, bufsize, bufpos, "%s", value);
	}

	for (i = 0; i < vars_size; i++) {
		size_t namelen = strlen(vars[i].name);

		if (end - name != (long) namelen || strncmp(name, vars[i].name, namelen))
			continue;

		if (vars[i].number)
			return string_nformat(buf, bufsize, bufpos, "%lu", *vars[i].number);
		return string_nformat(buf, bufsize, bufpos, "%s",
				      *vars[i].value ? vars[i].value : vars[i].value_if_empty);
	}

	return false;
}

static bool
format_arg(struct format_var *vars, size_t vars_size, const char *arg, char *buf, size_t bufsize)
{
	size_t bufpos = 0;

	buf[0] = 0;
	while (arg) {
		const char *var = strstr(arg, "%(");
		const char *closing = var ? strchr(var, ')') : NULL;
		const char *next = closing ? closing + 1 : NULL;
		const int len = var ? var - arg : (int) strlen(arg);

		if (var && !closing)
			return false;

		if (len && !string_nformat(buf, bufsize, &bufpos, "%.*s", len, arg))
			return false;

		if (var && !format_expand_arg(vars, vars_size, var, next, buf, bufsize, &bufpos))
			return false;

		arg = next;
	}
	return true;
}

static bool
argv_append_nonempty(const char ***argv, const char *arg)
{
	if (!*arg && argv_size(*argv) > 0)
		return true;
	return argv_append(argv, arg);
}

#define ENV_VARS(env) \
	struct format_var vars[] = { \
		{ "%(head)", env->head, "HEAD", NULL }, \
		{ "%(commit)", env->commit, "HEAD", NULL }, \
		{ "%(blob)", env->blob, "", NULL }, \
		{ "%(branch)", env->branch, "", NULL }, \
		{ "%(remote)", env->remote, "origin", NULL }, \
		{ "%(tag)", env->tag, "", NULL }, \
		{ "%(refname)", env->refname, "", NULL }, \
		{ "%(stash)", env->stash, "", NULL }, \
		{ "%(directory)", env->directory, ".", NULL }, \
		{ "%(file)", env->file, "", NULL }, \
		{ "%(file_old)", env->file_old, "", NULL }, \
		{ "%(ref)", env->ref, "HEAD", NULL }, \
		{ "%(text)", env->text, "", NULL }, \
		{ "%(search)", env->search, "", NULL }, \
		{ "%(lineno)", "", "", &env->lineno }, \
		{ "%(lineno_old)", "", "", &env->lineno_old }, \
		{ "%(repo:head)", repo.head, "", NULL }, \
		{ "%(repo:head-id)", repo.head_id, "", NULL }, \
		{ "%(repo:remote)", repo.remote, "", NULL }, \
		{ "%(repo:upstream)", repo.upstream, "", NULL }, \
		{ "%(repo:cdup)", repo.cdup, "", NULL }, \
		{ "%(repo:prefix)", repo.prefix, "", NULL }, \
		{ "%(repo:git-dir)", repo.git_dir, "", NULL }, \
		{ "%(repo:worktree)", repo.worktree, "", NULL }, \
		{ "%(repo:is-inside-work-tree)", repo.is_inside_work_tree ? "true" : "false", "", NULL }, \
	}

bool
format_argv_string(struct argv_env *env, char *buf, size_t bufsize, const char *src)
{
	ENV_VARS(env);

	return format_arg(vars, ARRAY_SIZE(vars), src, buf, bufsize);
}

static bool
format_append_argv(struct format_var *vars, size_t vars_size, const char ***dst_argv, const char **src)
{
	int i;
	char buf[SIZEOF_MED_STR];

	for (i = 0; src && src[i]; i++) {
		if (!format_arg(vars, vars_size, src[i], buf, sizeof(buf)))
			return false;
		argv_append_nonempty(dst_argv, buf);
	}
	return true;
}

bool
argv_format(struct argv_env *env, const char ***dst_argv, const char *src_argv[], bool first, bool file_filter)
{
	ENV_VARS(env);
	int argc;
	const char **result = NULL;

	for (argc = 0; src_argv[argc]; argc++) {
		const char *arg = src_argv[argc];

		if (!strcmp(arg, "%(fileargs)")) {
			if (file_filter) {
				int i;

				for (i = 0; opt_file_args && opt_file_args[i]; i++)
					argv_append_nonempty(&result, opt_file_args[i]);
			}

		} else if (!strcmp(arg, "%(diffargs)")) {
			if (!format_append_argv(vars, ARRAY_SIZE(vars), &result, opt_diff_options))
				break;

		} else if (!strcmp(arg, "%(blameargs)")) {
			if (!format_append_argv(vars, ARRAY_SIZE(vars), &result, opt_blame_options))
				break;

		} else if (!strcmp(arg, "%(logargs)")) {
			if (!format_append_argv(vars, ARRAY_SIZE(vars), &result, opt_log_options))
				break;

		} else if (!strcmp(arg, "%(mainargs)")) {
			if (!format_append_argv(vars, ARRAY_SIZE(vars), &result, opt_main_options))
				break;

		} else if (!strcmp(arg, "%(cmdlineargs)")) {
			if (!format_append_argv(vars, ARRAY_SIZE(vars), &result, opt_cmdline_args))
				break;

		} else if (!strcmp(arg, "%(revargs)") ||
			   (first && !strcmp(arg, "%(commit)"))) {
			int i;

			for (i = 0; opt_rev_args && opt_rev_args[i]; i++)
				argv_append_nonempty(&result, opt_rev_args[i]);

		} else {
			char buf[SIZEOF_MED_STR];

			if (!format_arg(vars, ARRAY_SIZE(vars), arg, buf, sizeof(buf)))
				break;
			argv_append_nonempty(&result, buf);
		}
	}

	if (src_argv[argc] != NULL) {
		argv_free(result);
		free(result);
		return false;
	}

	if (*dst_argv) {
		argv_free(*dst_argv);
		free(*dst_argv);
	}
	if (!result)
		result = xcalloc(1, sizeof(*result));
	*dst_argv = result;
	return true;
}

/* ------------------------------------------------------------------ */
/* Loading */

void
clear_position(struct position *pos)
{
	memset(pos, 0, sizeof(*pos));
}

static inline bool
check_position(struct position *pos)
{
	return pos->lineno || pos->col || pos->offset;
}

static void
reset_search(struct view *view)
{
	(void) view;
}

void
reset_view(struct view *view)
{
	size_t i;

	if (view->ops->done && view->lines)
		; /* private data is reset by the view itself */

	for (i = 0; i < view->lines; i++)
		free(view->line[i].data);
	free(view->line);

	reset_search(view);
	view->prev_pos = view->pos;
	/* A view without a previous view is the first view */
	if (!view->prev && !view->lines && view->prev_pos.lineno == 0)
		view->prev_pos.lineno = opt_lineno > 0 ? opt_lineno - 1 : 0;
	clear_position(&view->pos);

	view->line = NULL;
	view->lines = 0;
	view->line_alloc = 0;
	view->vid[0] = 0;
	view->custom_lines = 0;
}

static void
setup_update(struct view *view, const char *vid)
{
	reset_view(view);
	string_ncopy(view->vid, vid, strlen(vid));
	view->pipe = true;
	view->start_time = time(NULL);
}

bool
view_can_refresh(struct view *view)
{
	return view_has_flags(view, VIEW_REFRESH) && !view->unrefreshable;
}

static char *stdin_data;
static size_t stdin_len;
static bool stdin_read;

static void
read_stdin_data(void)
{
	size_t alloc = 0;

	if (stdin_read)
		return;
	stdin_read = true;
	stdin_len = 0;
	while (true) {
		ssize_t n;

		if (alloc - stdin_len < 65536) {
			alloc = alloc ? alloc * 2 : 65536;
			stdin_data = xrealloc(stdin_data, alloc + 1);
		}
		n = read(STDIN_FILENO, stdin_data + stdin_len, alloc - stdin_len);
		if (n < 0 && errno == EINTR)
			continue;
		if (n <= 0)
			break;
		stdin_len += n;
	}
	if (!stdin_data)
		stdin_data = xcalloc(1, 1);
	stdin_data[stdin_len] = 0;
}

char *
get_stdin_data(size_t *len)
{
	read_stdin_data();
	*len = stdin_len;
	return stdin_data;
}

bool
begin_update(struct view *view, const char *dir, const char **argv, enum open_flags flags)
{
	bool extra = !!(flags & OPEN_EXTRA);
	bool reload = !!(flags & (OPEN_RELOAD | OPEN_REFRESH | OPEN_PREPARED | OPEN_EXTRA));
	bool refresh = flags & (OPEN_REFRESH | OPEN_PREPARED | OPEN_STDIN);
	bool use_stdin = !!(flags & OPEN_STDIN);

	if ((!reload && !strcmp(view->vid, view->ops->id)) ||
	    ((flags & OPEN_REFRESH) && !view_can_refresh(view)))
		return true;

	if (view->pipe && !extra)
		end_update(view, true);

	view->unrefreshable = use_stdin;

	if (!refresh && argv) {
		bool file_filter = !view_has_flags(view, VIEW_FILE_FILTER) || opt_file_filter;

		view->dir = dir;
		if (!argv_format(view->env, &view->argv, argv, !view->prev, file_filter)) {
			report("Failed to format %s arguments", view->name);
			return false;
		}

		string_copy_rev(view->ref, view->ops->id);
	}

	free(view->pipe_buf);
	view->pipe_buf = NULL;
	view->pipe_len = view->pipe_pos = 0;

	if (use_stdin) {
		size_t len;
		char *data = get_stdin_data(&len);

		view->pipe_buf = xstrndup(data, len);
		view->pipe_len = len;
		view->pipe_status = 0;
	} else if (view->argv && view->argv[0]) {
		size_t len;
		int status;
		const char *rundir = view->dir && *view->dir ? view->dir : NULL;
		char *out = io_capture(view->argv, rundir, &len, &status,
				       !!(flags & OPEN_WITH_STDERR));

		if (!out) {
			report("Failed to open %s view", view->name);
			return false;
		}
		view->pipe_buf = out;
		view->pipe_len = len;
		view->pipe_status = status;
	}

	if (!extra)
		setup_update(view, view->ops->id);
	view->pipe = true;

	return true;
}

bool
begin_update_from_data(struct view *view, char *data, size_t len)
{
	free(view->pipe_buf);
	view->pipe_buf = data;
	view->pipe_len = len;
	view->pipe_pos = 0;
	view->pipe_status = 0;
	view->pipe = true;
	return true;
}

void
end_update(struct view *view, bool force)
{
	if (!view->pipe)
		return;

	view->pipe = false;
	while (!view->ops->read(view, NULL, 0)) {
		if (force) {
			view->pipe = false;
			break;
		}
		if (view->pipe)
			return;
	}
	view->pipe = false;
	free(view->pipe_buf);
	view->pipe_buf = NULL;
	view->pipe_len = view->pipe_pos = 0;
}

static bool
view_read_lines(struct view *view)
{
	while (view->pipe && view->pipe_buf && view->pipe_pos < view->pipe_len) {
		char *start = view->pipe_buf + view->pipe_pos;
		char *eol = memchr(start, '\n', view->pipe_len - view->pipe_pos);
		size_t len;

		if (!eol)
			eol = view->pipe_buf + view->pipe_len;
		len = eol - start;
		*eol = 0;
		view->pipe_pos += len + 1;

		if (!view->ops->read(view, start, len)) {
			report("Allocation failure");
			end_update(view, true);
			return false;
		}
	}
	return true;
}

bool
update_view(struct view *view)
{
	bool redraw = view->lines == 0;

	if (!view->pipe)
		return true;

	while (view->pipe) {
		char *buf_before;

		if (!view_read_lines(view))
			return false;
		if (!view->pipe)
			break;

		/* EOF: notify the view which may start another command */
		buf_before = view->pipe_buf;
		view->pipe_pos = view->pipe_len;
		if (view->ops->read(view, NULL, 0)) {
			view->pipe = false;
			if (view->pipe_buf == buf_before) {
				free(view->pipe_buf);
			}
			view->pipe_buf = NULL;
			view->pipe_len = view->pipe_pos = 0;
			break;
		}
		/* read() returned false: an extra command was started */
		if (view->pipe_buf == buf_before && view->pipe_pos >= view->pipe_len) {
			view->pipe = false;
			free(view->pipe_buf);
			view->pipe_buf = NULL;
			break;
		}
		if (buf_before != view->pipe_buf)
			free(buf_before);
	}

	if (restore_view_position(view))
		redraw = true;

	if (!view_is_displayed(view))
		return true;

	(void) redraw;
	redraw_view(view);
	update_view_title(view);
	return true;
}

void
update_views(void)
{
	struct view *view;
	int i;

	foreach_view (view, i)
		if (view->pipe)
			update_view(view);
}

bool
goto_view_line(struct view *view, unsigned long offset, unsigned long lineno)
{
	if (lineno >= view->lines)
		lineno = view->lines > 0 ? view->lines - 1 : 0;

	if (offset > lineno || offset + view->height <= lineno) {
		unsigned long half = view->height / 2;

		if (lineno > half)
			offset = lineno - half;
		else
			offset = 0;
	}

	if (offset != view->pos.offset || lineno != view->pos.lineno) {
		view->pos.offset = offset;
		view->pos.lineno = lineno;
		return true;
	}

	return false;
}

void
restore_view_position_wrap(struct view *view)
{
	restore_view_position(view);
}

bool
restore_view_position_impl(struct view *view)
{
	/* Ensure that the view position is in a valid state. */
	if (!check_position(&view->prev_pos) ||
	    (view->pipe && view->lines <= view->prev_pos.lineno))
		return goto_view_line(view, view->pos.offset, view->pos.lineno);

	/* Changing the view position cancels the restoring. */
	if (check_position(&view->pos)) {
		clear_position(&view->prev_pos);
		return false;
	}

	goto_view_line(view, view->prev_pos.offset, view->prev_pos.lineno);
	view->pos.col = view->prev_pos.col;
	clear_position(&view->prev_pos);

	return true;
}

void
restore_view_position(struct view *view)
{
	restore_view_position_impl(view);
}

static bool
view_no_refresh(struct view *view, enum open_flags flags)
{
	bool reload = !!(flags & OPEN_ALWAYS_LOAD);

	return (!reload && !strcmp(view->vid, view->ops->id)) ||
	       ((flags & OPEN_REFRESH) && !view_can_refresh(view));
}

void
load_view(struct view *view, struct view *prev, enum open_flags flags)
{
	bool refresh = !view_no_refresh(view, flags);

	/* When prev == view it means this is the first loaded view. */
	if (prev && view != prev) {
		view->prev = prev;
	}

	if (refresh) {
		enum status_code code;

		if (view->pipe)
			end_update(view, true);
		if (view->ops->private_size) {
			if (!view->private) {
				view->private = xcalloc(1, view->ops->private_size);
			} else {
				if (view->ops->done)
					view->ops->done(view);
				memset(view->private, 0, view->ops->private_size);
			}
		}

		code = view->ops->open(view, flags);
		if (code != SUCCESS) {
			report("%s", get_status_message(code));
			return;
		}
	}

	if (prev) {
		bool split = !!(flags & OPEN_SPLIT);

		if (split) {
			split_view(prev, view);
		} else {
			maximize_view(view, false);
		}
	}

	if (view->pipe)
		update_view(view);

	restore_view_position(view);

	if (view_is_displayed(view)) {
		redraw_view(view);
		report_clear();
	}
	update_all_titles();
}

void
open_view(struct view *prev, struct view *view, enum open_flags flags)
{
	bool reload = !!(flags & (OPEN_RELOAD | OPEN_PREPARED));
	int nviews = displayed_views();

	if (view == prev && nviews == 1 && !reload) {
		report("Already in %s view", view->name);
		return;
	}

	if (!view_has_flags(view, VIEW_NO_GIT_DIR) && !repo.git_dir[0]) {
		report("The %s view is disabled in pager mode", view->name);
		return;
	}

	if (!view->keymap)
		view->keymap = get_keymap(view->name, strlen(view->name));

	load_view(view, prev ? prev : view, flags);
}

void
open_argv(struct view *prev, struct view *view, const char *argv[], const char *dir, enum open_flags flags)
{
	if (view->pipe)
		end_update(view, true);
	view->dir = dir;

	if (!argv_copy(&view->argv, argv)) {
		report("Failed to open %s view: %s", view->name, argv[0]);
	} else {
		open_view(prev, view, flags | OPEN_PREPARED);
	}
}

bool
view_exec(struct view *view, enum open_flags flags)
{
	char opt_env_dir[1] = "";

	(void) opt_env_dir;
	return begin_update(view, NULL, NULL, flags);
}

enum status_code
begin_update_status(struct view *view, const char *dir, const char **argv, enum open_flags flags)
{
	if (!begin_update(view, dir, argv, flags))
		return error("Failed to open %s view", view->name);
	return SUCCESS;
}

void
refresh_view(struct view *view)
{
	load_view(view, NULL, OPEN_REFRESH);
}

void
reload_view(struct view *view)
{
	load_view(view, NULL, OPEN_RELOAD);
}

/* ------------------------------------------------------------------ */
/* Navigation */

void
do_scroll_view(struct view *view, int lines)
{
	/* The rendering expects the new offset. */
	view->pos.offset += lines;

	/* Move current line into the view. */
	if (view->pos.lineno < view->pos.offset) {
		view->pos.lineno = view->pos.offset;
	} else if (view->pos.lineno >= view->pos.offset + view->height) {
		view->pos.lineno = view->pos.offset + view->height - 1;
	}

	if (view_is_displayed(view)) {
		redraw_view(view);
	}

	view->has_scrolled = true;
	report_clear();
}

void
scroll_view(struct view *view, enum request request)
{
	int lines = 1;

	switch (request) {
	case REQ_SCROLL_FIRST_COL:
		view->pos.col = 0;
		redraw_view_from(view, 0);
		report_clear();
		return;
	case REQ_SCROLL_RIGHT:
		view->pos.col += apply_step(opt_horizontal_scroll, view->width);
		redraw_view(view);
		report_clear();
		return;
	case REQ_SCROLL_LEFT:
		if (view->pos.col == 0) {
			report("Cannot scroll beyond the first column");
			return;
		}
		if (view->pos.col <= (unsigned long) apply_step(opt_horizontal_scroll, view->width))
			view->pos.col = 0;
		else
			view->pos.col -= apply_step(opt_horizontal_scroll, view->width);
		redraw_view_from(view, 0);
		report_clear();
		return;
	case REQ_SCROLL_PAGE_DOWN:
		lines = view->height;
		/* fallthrough */
	case REQ_SCROLL_HALF_PAGE_DOWN:
		if (request == REQ_SCROLL_HALF_PAGE_DOWN)
			lines = view->height / 2;
		/* fallthrough */
	case REQ_SCROLL_LINE_DOWN:
		if (view->pos.offset + lines > view->lines)
			lines = view->lines - view->pos.offset;

		if (lines == 0 || view->pos.offset + view->height >= view->lines) {
			report("Cannot scroll beyond the last line");
			return;
		}
		break;

	case REQ_SCROLL_PAGE_UP:
		lines = view->height;
		/* fallthrough */
	case REQ_SCROLL_HALF_PAGE_UP:
		if (request == REQ_SCROLL_HALF_PAGE_UP)
			lines = view->height / 2;
		/* fallthrough */
	case REQ_SCROLL_LINE_UP:
		if ((unsigned long) lines > view->pos.offset)
			lines = view->pos.offset;

		if (lines == 0) {
			report("Cannot scroll beyond the first line");
			return;
		}

		lines = -lines;
		break;

	default:
		die("request %d not handled in switch", request);
	}

	do_scroll_view(view, lines);
}

void
move_view(struct view *view, enum request request)
{
	int scroll_steps = 0;
	int steps;

	switch (request) {
	case REQ_MOVE_FIRST_LINE:
		steps = -view->pos.lineno;
		break;

	case REQ_MOVE_LAST_LINE:
		steps = view->lines - view->pos.lineno - 1;
		break;

	case REQ_MOVE_PAGE_UP:
		steps = (unsigned long) view->height > view->pos.lineno
		      ? -view->pos.lineno : -view->height;
		break;

	case REQ_MOVE_PAGE_DOWN:
		steps = view->pos.lineno + view->height >= view->lines
		      ? view->lines - view->pos.lineno - 1 : (unsigned long) view->height;
		break;

	case REQ_MOVE_HALF_PAGE_UP:
		steps = (unsigned long) view->height / 2 > view->pos.lineno
		      ? -view->pos.lineno : -(view->height / 2);
		break;

	case REQ_MOVE_HALF_PAGE_DOWN:
		steps = view->pos.lineno + view->height / 2 >= view->lines
		      ? view->lines - view->pos.lineno - 1 : (unsigned long) view->height / 2;
		break;

	case REQ_MOVE_UP:
	case REQ_PREVIOUS:
		steps = -1;
		break;

	case REQ_MOVE_DOWN:
	case REQ_NEXT:
		steps = 1;
		break;

	case REQ_MOVE_NEXT_MERGE:
	case REQ_MOVE_PREV_MERGE: {
		int dir = request == REQ_MOVE_NEXT_MERGE ? 1 : -1;
		long lineno = view->pos.lineno + dir;

		steps = 0;
		for (; lineno >= 0 && (size_t) lineno < view->lines; lineno += dir) {
			struct line *line = &view->line[lineno];

			if (view == &main_view && line->data && ((struct commit *) line->data)->is_merge) {
				steps = lineno - view->pos.lineno;
				break;
			}
		}
		if (!steps) {
			report(dir > 0 ? "Cannot move beyond the last line" : "Cannot move beyond the first line");
			return;
		}
		break;
	}

	default:
		die("request %d not handled in switch", request);
	}

	if (steps <= 0 && view->pos.lineno == 0) {
		report("Cannot move beyond the first line");
		return;

	} else if (steps >= 0 && view->pos.lineno + 1 >= view->lines) {
		report("Cannot move beyond the last line");
		return;
	}

	/* Move the current line */
	view->pos.lineno += steps;

	/* Check whether the view needs to be scrolled */
	if (view->pos.lineno < view->pos.offset ||
	    view->pos.lineno >= view->pos.offset + view->height) {
		scroll_steps = steps;
		if (steps < 0 && -steps > (long) view->pos.offset) {
			scroll_steps = -view->pos.offset;

		} else if (steps > 0) {
			if (view->pos.lineno == view->lines - 1 &&
			    view->lines > (unsigned long) view->height) {
				scroll_steps = view->lines - view->pos.offset - 1;
				if (scroll_steps >= view->height)
					scroll_steps -= view->height - 1;
			}
		}
	}

	if (!view_is_displayed(view)) {
		view->pos.offset += scroll_steps;
		view->ops->select(view, &view->line[view->pos.lineno]);
		return;
	}

	if (scroll_steps) {
		do_scroll_view(view, scroll_steps);
		return;
	}

	redraw_view(view);
	report_clear();
}

void
select_view_line(struct view *view, unsigned long lineno)
{
	if (goto_view_line(view, view->pos.offset, lineno)) {
		if (view_is_displayed(view)) {
			redraw_view(view);
		} else {
			view->ops->select(view, &view->line[view->pos.lineno]);
		}
	}
}

/* ------------------------------------------------------------------ */
/* Searching */

bool
grep_text(struct view *view, const char *text[])
{
	regmatch_t pmatch;
	size_t i;

	for (i = 0; text[i]; i++)
		if (*text[i] && !regexec(view->regex, text[i], 1, &pmatch, 0))
			return true;
	return false;
}

static bool
setup_search(struct view *view, const char *search)
{
	int regex_flags = REG_EXTENDED;
	bool ignore = false;

	if (opt_ignore_case == IGNORE_CASE_YES)
		ignore = true;
	else if (opt_ignore_case == IGNORE_CASE_SMART_CASE) {
		const char *p;

		ignore = true;
		for (p = search; *p; p++)
			if (isupper((unsigned char) *p))
				ignore = false;
	}
	if (ignore)
		regex_flags |= REG_ICASE;

	if (view->regex) {
		regfree(view->regex);
		*view->grep = 0;
	} else {
		view->regex = xcalloc(1, sizeof(*view->regex));
	}

	if (regcomp(view->regex, search, regex_flags)) {
		char buf[SIZEOF_STR];

		regerror(regcomp(view->regex, search, regex_flags), view->regex, buf, sizeof(buf));
		report("Search failed: %s", buf);
		free(view->regex);
		view->regex = NULL;
		return false;
	}

	string_copy(view->grep, search);
	return true;
}

static int
count_matches(struct view *view, size_t *first_after, size_t *pos_index)
{
	size_t lineno;
	int count = 0;

	(void) first_after;
	(void) pos_index;
	for (lineno = 0; lineno < view->lines; lineno++) {
		struct line *line = &view->line[lineno];

		line->search_result = view->ops->grep(view, line) ? 1 : 0;
		if (line->search_result)
			count++;
	}
	return count;
}

void
find_next(struct view *view, enum request request)
{
	int direction;
	long lineno;
	int total, index;

	if (!*view->grep || !view->regex) {
		if (!*view->env->search) {
			report("No previous search");
			return;
		}
		if (!setup_search(view, view->env->search))
			return;
	}

	switch (request) {
	case REQ_SEARCH:
	case REQ_FIND_NEXT:
		direction = view->search_back ? -1 : 1;
		break;
	case REQ_SEARCH_BACK:
	case REQ_FIND_PREV:
		direction = view->search_back ? 1 : -1;
		break;
	default:
		return;
	}

	total = count_matches(view, NULL, NULL);

	lineno = view->pos.lineno;
	{
		long start = lineno;
		long i;

		for (i = 1; i <= (long) view->lines; i++) {
			long candidate = start + i * direction;

			if (candidate < 0 || candidate >= (long) view->lines) {
				if (!opt_wrap_search)
					break;
				candidate = (candidate + (long) view->lines * 2) % (long) view->lines;
			}
			if (view->line[candidate].search_result) {
				long j;

				index = 0;
				for (j = 0; j <= candidate; j++)
					if (view->line[j].search_result)
						index++;
				select_view_line(view, candidate);
				report("Line %ld matches '%s' (%d of %d)", candidate + 1, view->grep, index, total);
				return;
			}
		}
	}

	report("No match found for '%s'", view->grep);
}

void
search_view(struct view *view, enum request request)
{
	const char *prompt = request == REQ_SEARCH ? "/" : "?";
	char *search = read_prompt(prompt);

	if (search) {
		enum request req = request;

		string_copy(argv_env.search, search);
		if (!setup_search(view, search))
			return;
		view->search_back = request == REQ_SEARCH_BACK;
		find_next(view, req == REQ_SEARCH_BACK ? REQ_FIND_NEXT : REQ_FIND_NEXT);
	} else if (*argv_env.search) {
		/* cancelled */
	}
}

enum status_code
setup_and_find_next(struct view *view, enum request request)
{
	if (!setup_search(view, view->env->search))
		return SUCCESS;
	view->search_back = request == REQ_FIND_PREV;
	find_next(view, REQ_FIND_NEXT);
	return SUCCESS;
}
EOF
