cat > /workspace/src/draw.c <<'EOF'
/* Drawing of view lines and columns */
#include "tigview.h"

int
get_view_attr(struct view *view, line_type_t type)
{
	if (type == LINE_CURSOR && view != display[current_view])
		type = LINE_CURSOR_BLUR;
	return get_line_attr(view->name, type);
}

int
get_view_color(struct view *view, line_type_t type)
{
	if (type == LINE_CURSOR && view != display[current_view])
		type = LINE_CURSOR_BLUR;
	return get_line_color(view->name, type);
}

void
set_view_attr(struct view *view, line_type_t type)
{
	if (!view->curline->selected && view->curtype != type) {
		(void) wattrset(view->win, get_view_attr(view, type));
		wchgat(view->win, -1, 0, PAIR_NUMBER(get_view_color(view, type)), NULL);
		view->curtype = type;
	}
}

static bool
draw_chars(struct view *view, line_type_t type, const char *string, int length,
	   int max_width, bool use_tilde)
{
	int len = 0;
	int col = 0;
	int trimmed = false;
	size_t skip = view->pos.col > (unsigned long) view->col ? view->pos.col - view->col : 0;

	if (max_width <= 0)
		return VIEW_MAX_LEN(view) <= 0;

	len = utf8_length(&string, length, skip, &col, max_width, &trimmed, use_tilde, opt_tab_size);

	set_view_attr(view, type);
	if (len > 0) {
		size_t outlen;
		const char *out = encoding_convert_out(string, len, &outlen);

		waddnstr(view->win, out, outlen);
	}

	if (trimmed && use_tilde) {
		set_view_attr(view, LINE_DELIMITER);
		waddstr(view->win, opt_truncation_delimiter);
		col++;
	}

	view->col += col;
	return VIEW_MAX_LEN(view) <= 0;
}

bool
draw_space(struct view *view, line_type_t type, int max, int spaces)
{
	static char space[] = "                    ";

	spaces = MIN(max, spaces);

	while (spaces > 0) {
		int len = MIN(spaces, (int) sizeof(space) - 1);

		if (draw_chars(view, type, space, len, len, false))
			return true;
		spaces -= len;
	}

	return VIEW_MAX_LEN(view) <= 0;
}

static bool
draw_text_expanded(struct view *view, line_type_t type, const char *string, int length, int max_width, bool use_tilde)
{
	static char text[SIZEOF_MED_STR];

	if (length == -1)
		length = strlen(string);

	do {
		size_t pos = string_expand(text, sizeof(text), string, length, opt_tab_size);
		size_t col = view->col;

		if (draw_chars(view, type, text, -1, max_width, use_tilde))
			return true;
		string += pos;
		length -= pos;
		max_width -= view->col - col;
	} while (*string && length > 0);

	return VIEW_MAX_LEN(view) <= 0;
}

bool
draw_textn(struct view *view, line_type_t type, const char *string, int length)
{
	return draw_text_expanded(view, type, string, length, VIEW_MAX_LEN(view), false);
}

bool
draw_text(struct view *view, line_type_t type, const char *string)
{
	return draw_textn(view, type, string, -1);
}

static bool
draw_text_overflow(struct view *view, const char *text, line_type_t type,
		   int overflow_length, int offset)
{
	bool on = overflow_length > 0;

	if (on) {
		int overflow = overflow_length + offset;
		int max = MIN(VIEW_MAX_LEN(view), overflow);
		const char *tmp = text;
		int text_width = 0;
		int trimmed = false;
		size_t len = utf8_length(&tmp, -1, 0, &text_width, max, &trimmed, false, 1);

		if (draw_text_expanded(view, type, text, -1, text_width, max < overflow))
			return true;

		text += len;
		type = LINE_OVERFLOW;
	}

	if (*text && draw_text(view, type, text))
		return true;

	return VIEW_MAX_LEN(view) <= 0;
}

bool
draw_formatted(struct view *view, line_type_t type, const char *format, ...)
{
	char text[SIZEOF_MED_STR];
	va_list args;

	va_start(args, format);
	vsnprintf(text, sizeof(text), format, args);
	va_end(args);
	return draw_text(view, type, text);
}

bool
draw_graphic(struct view *view, line_type_t type, const chtype graphic[], size_t size, bool separator)
{
	size_t skip = view->pos.col > (unsigned long) view->col ? view->pos.col - view->col : 0;
	size_t i;

	if (VIEW_MAX_LEN(view) <= 0)
		return true;

	set_view_attr(view, type);
	/* Using waddch() instead of waddnstr() ensures that
	 * they'll be rendered correctly for the cursor line. */
	for (i = skip; i < size; i++)
		waddch(view->win, graphic[i]);

	view->col += size;
	if (separator) {
		if (size < skip)
			;
		else
			waddch(view->win, ' ');
		view->col++;
	}

	return VIEW_MAX_LEN(view) <= 0;
}

bool
draw_field(struct view *view, line_type_t type, const char *text, int width, int align, bool trim)
{
	int max = MIN(VIEW_MAX_LEN(view), width + 1);
	int col = view->col;

	if (!text)
		return draw_space(view, type, max, max);

	if (align == ALIGN_RIGHT) {
		int textlen = utf8_width_max(text, max);
		int leftpad = max - textlen - 1;

		if (leftpad > 0) {
			if (draw_space(view, type, leftpad, leftpad))
				return true;
			max -= leftpad;
			col += leftpad;
		}
	}

	return draw_chars(view, type, text, -1, max - 1, trim)
	    || draw_space(view, type, max - (view->col - col), max);
}

static bool
draw_date(struct view *view, struct view_column *column, const struct time *time)
{
	int date = column->opt.display;
	const char *text = mkdate(time, date, column->opt.local, column->opt.format);
	int align = date == DATE_RELATIVE || date == DATE_RELATIVE_COMPACT ? ALIGN_RIGHT : ALIGN_LEFT;

	if (date == DATE_NO)
		return false;

	return draw_field(view, LINE_DATE, time ? text : NULL, column->width, align, false);
}

static bool
author_trim(int cols)
{
	return cols == 0 || cols > 5;
}

static bool
draw_author(struct view *view, struct view_column *column, const struct ident *author, line_type_t type)
{
	bool trim = author_trim(column->width);
	const char *text = author ? mkauthor(author, column->opt.width, column->opt.display) : NULL;

	if (column->opt.display == AUTHOR_NO)
		return false;

	return draw_field(view, type, text, column->width, ALIGN_LEFT, trim);
}

static bool
draw_id(struct view *view, struct view_column *column, const char *id)
{
	line_type_t type = LINE_ID;

	if (!column->opt.display)
		return false;

	if (column->opt.color && id) {
		unsigned long color = string_hash(id) % GRAPH_COLORS;

		type = LINE_PALETTE_0 + color;
	}

	return draw_field(view, type, id, column->width, ALIGN_LEFT, false);
}

static bool
draw_filename(struct view *view, struct view_column *column, const char *filename, mode_t mode)
{
	int width = filename ? utf8_width(filename) : 0;
	bool trim = width >= column->width;
	line_type_t type = S_ISDIR(mode) ? LINE_DIRECTORY : LINE_FILE;
	int column_width = column->width ? column->width : width;

	if (column->opt.display == FILENAME_NO)
		return false;

	return draw_field(view, type, filename, column_width, ALIGN_LEFT, trim);
}

static bool
draw_file_size(struct view *view, struct view_column *column, unsigned long size, mode_t mode)
{
	const char *str = S_ISDIR(mode) ? NULL : mkfilesize(size, column->opt.display);

	if (!column->width || column->opt.display == FILE_SIZE_NO)
		return false;

	return draw_field(view, LINE_FILE_SIZE, str, column->width, ALIGN_RIGHT, false);
}

static bool
draw_mode(struct view *view, struct view_column *column, mode_t mode)
{
	const char *str = mkmode(mode);

	if (!column->width || !column->opt.display)
		return false;

	return draw_field(view, LINE_MODE, str, column->width, ALIGN_LEFT, false);
}

bool
draw_lineno(struct view *view, struct view_column *column, unsigned int lineno, bool add_separator)
{
	char number[10];
	unsigned long digits3 = column->width < 3 ? 3 : column->width;
	int max = MIN(VIEW_MAX_LEN(view), (int) digits3);
	char *text = NULL;
	chtype separator = opt_line_graphics ? ACS_VLINE : '|';
	int interval = column->opt.interval > 0 ? column->opt.interval : 5;

	if (!column->opt.display)
		return false;

	if (lineno == 1 || (lineno % interval) == 0) {
		static char fmt[] = "%ld";

		fmt[1] = '0' + (digits3 <= 9 ? digits3 : 1);
		if (string_format(number, fmt, (long) lineno))
			text = number;
	}
	if (text)
		draw_chars(view, LINE_LINE_NUMBER, text, -1, max, true);
	else
		draw_space(view, LINE_LINE_NUMBER, max, digits3);
	if (!add_separator)
		return VIEW_MAX_LEN(view) <= 0;
	return draw_graphic(view, LINE_DEFAULT, &separator, 1, true);
}

static bool
draw_ref(struct view *view, struct view_column *column, const struct ref *ref)
{
	line_type_t type = !ref || !ref->valid ? LINE_DEFAULT : get_line_type_from_ref(ref);
	const char *name = ref ? ref->name : NULL;

	return draw_field(view, type, name, column->width, ALIGN_LEFT, false);
}

static bool
draw_refs(struct view *view, struct view_column *column, const struct ref *refs)
{
	if (!column->opt.refs || !refs)
		return false;

	for (; refs; refs = refs->next) {
		const struct ref *ref = refs;
		line_type_t type = get_line_type_from_ref(ref);
		const struct ref_format *format = get_ref_format(ref);

		if (!strcmp(format->start, "hide:") && !*format->end)
			continue;

		if (draw_formatted(view, type, "%s%s%s", format->start, ref->name, format->end))
			return true;

		if (draw_text(view, LINE_DEFAULT, " "))
			return true;
	}

	return false;
}

static const char *
mkstatus(const char status, int label)
{
	static char default_label[] = { '?', 0 };
	static const char *labels[][2] = {
		{ "!", "ignored" },
		{ "?", "untracked" },
		{ "A", "added" },
		{ "C", "copied" },
		{ "D", "deleted" },
		{ "M", "modified" },
		{ "R", "renamed" },
		{ "U", "unmerged" },
	};
	size_t i;

	if (label == STATUS_LABEL_NO)
		return "";

	for (i = 0; i < ARRAY_SIZE(labels); i++) {
		if (status == *labels[i][0]) {
			if (label == STATUS_LABEL_LONG)
				return labels[i][1];
			else
				return labels[i][0];
		}
	}

	default_label[0] = status;
	return default_label;
}

static bool
draw_status(struct view *view, struct view_column *column, line_type_t type, const char *status)
{
	const char *label = status ? mkstatus(*status, column->opt.display) : NULL;

	if (column->opt.display == STATUS_LABEL_NO)
		return false;

	return draw_field(view, type, label, column->width, ALIGN_LEFT, false);
}

static size_t
get_graph_indent(const char *text)
{
	size_t i;

	for (i = 0; text[i]; i++)
		if (text[i] != ' ' && text[i] != '|' && text[i] != '\\' && text[i] != '/' && text[i] != '*' && text[i] != '_')
			break;
	return i;
}

bool
view_column_draw(struct view *view, struct line *line, unsigned int lineno)
{
	struct view_column *column = view->columns;
	struct view_column_data column_data = {0};

	if (!view->ops->get_column_data(view, line, &column_data))
		return true;

	if (column_data.section)
		column = column_data.section;

	for (; column; column = column->next) {
		mode_t mode = column_data.mode ? *column_data.mode : 0;

		if (column->hidden)
			continue;

		switch (column->type) {
		case VIEW_COLUMN_DATE:
			if (draw_date(view, column, column_data.date))
				return true;
			continue;

		case VIEW_COLUMN_AUTHOR:
			if (draw_author(view, column, column_data.author, LINE_AUTHOR))
				return true;
			continue;

		case VIEW_COLUMN_COMMITTER:
			if (draw_author(view, column, column_data.committer, LINE_COMMITTER))
				return true;
			continue;

		case VIEW_COLUMN_REF:
			if (!column->opt.display)
				continue;
			if (draw_ref(view, column, column_data.ref))
				return true;
			continue;

		case VIEW_COLUMN_ID:
			if (draw_id(view, column, column_data.reflog ? column_data.reflog : column_data.id))
				return true;
			continue;

		case VIEW_COLUMN_LINE_NUMBER:
			if (draw_lineno(view, column, column_data.line_number ? *column_data.line_number : lineno, true))
				return true;
			continue;

		case VIEW_COLUMN_MODE:
			if (draw_mode(view, column, mode))
				return true;
			continue;

		case VIEW_COLUMN_FILE_SIZE:
			if (draw_file_size(view, column, column_data.file_size ? *column_data.file_size : 0, mode))
				return true;
			continue;

		case VIEW_COLUMN_COMMIT_TITLE:
			if (!column->opt.display)
				continue;
			if (column_data.graph && column_data.graph_canvas && column->opt.graph &&
			    draw_graph(view, column_data.graph, column_data.graph_canvas))
				return true;
			if (draw_refs(view, column, column_data.refs))
				return true;
			if (draw_text_overflow(view, column_data.commit_title ? column_data.commit_title : "",
					       LINE_DEFAULT, column->opt.overflow, 0))
				return true;
			continue;

		case VIEW_COLUMN_FILE_NAME:
			if (draw_filename(view, column, column_data.file_name, mode))
				return true;
			continue;

		case VIEW_COLUMN_SECTION:
			if (draw_text(view, column->opt.display, column_data.text ? column_data.text : ""))
				return true;
			continue;

		case VIEW_COLUMN_STATUS:
			if (draw_status(view, column, line->type, column_data.status))
				return true;
			continue;

		case VIEW_COLUMN_TEXT:
		{
			line_type_t type = line->type;
			const char *text = column_data.text ? column_data.text : "";

			if (line->wrapped && draw_text(view, LINE_DELIMITER, "+"))
				return true;

			if (line->graph_indent) {
				size_t indent = get_graph_indent(text);

				if (draw_text_expanded(view, LINE_DEFAULT, text, -1, indent, false))
					return true;
				text += indent;
			}

			if (line->commit_title) {
				if (draw_text_overflow(view, text, LINE_DEFAULT,
						       column->opt.overflow, 4))
					return true;
			} else if (column_data.box) {
				const struct box *box = column_data.box;
				const char *btext = box->text;
				size_t i;

				for (i = 0; i < box->cells; i++) {
					const struct box_cell *cell = &box->cell[i];

					if (draw_textn(view, cell->type, btext, cell->length))
						return true;

					btext += cell->length;
				}

			} else if (draw_text(view, type, text)) {
				return true;
			}
		}
			continue;

		default:
			continue;
		}
	}

	return true;
}

bool
draw_view_line(struct view *view, unsigned int lineno)
{
	struct line *line;
	bool selected = (view->pos.offset + lineno == view->pos.lineno);

	if (view->pos.offset + lineno >= view->lines)
		return false;

	line = &view->line[view->pos.offset + lineno];

	wmove(view->win, lineno, 0);
	if (line->cleareol)
		wclrtoeol(view->win);
	view->col = 0;
	view->curline = line;
	view->curtype = LINE_NONE;
	line->selected = false;
	line->dirty = line->cleareol = 0;

	if (selected) {
		set_view_attr(view, LINE_CURSOR);
		line->selected = true;
		view->ops->select(view, line);
	}

	view->ops->draw(view, line, view->pos.offset + lineno);
	return true;
}

void
redraw_view_from(struct view *view, int lineno)
{
	if (!view->win)
		return;

	if (view->columns && view_columns_changed(view)) {
		size_t i;

		view_column_init(view);
		for (i = 0; i < view->lines; i++)
			view_column_info_update(view, &view->line[i]);
	}

	for (; lineno < view->height; lineno++) {
		if (!draw_view_line(view, lineno))
			break;
	}

	wnoutrefresh(view->win);
}

void
redraw_view(struct view *view)
{
	if (!view->win)
		return;
	werase(view->win);
	redraw_view_from(view, 0);
}

void
redraw_view_dirty(struct view *view)
{
	redraw_view(view);
}

/* ------------------------------------------------------------------ */
/* Columns */

struct view_column *
get_view_column(struct view *view, enum view_column_type type)
{
	struct view_column *column;

	for (column = view->columns; column; column = column->next)
		if (column->type == type)
			return column;
	return NULL;
}

bool
view_columns_changed(struct view *view)
{
	struct view_config *cfg = find_view_config(view->name);

	return cfg && cfg->version != view->columns_version;
}

bool
view_column_init(struct view *view)
{
	struct view_config *cfg = find_view_config(view->name);
	struct view_column *column, *next, **pos;
	int i;

	for (column = view->columns; column; column = next) {
		next = column->next;
		free(column);
	}
	view->columns = NULL;

	if (!cfg)
		return false;

	pos = &view->columns;
	for (i = 0; i < cfg->count; i++) {
		column = xcalloc(1, sizeof(*column));
		column->type = cfg->types[i];
		column->opt = cfg->opts[i];
		*pos = column;
		pos = &column->next;
	}
	view->columns_version = cfg->version;
	return true;
}

void
view_column_reset(struct view *view)
{
	struct view_column *column;

	if (view_columns_changed(view) || !view->columns)
		view_column_init(view);
	for (column = view->columns; column; column = column->next) {
		column->width = 0;
		column->hidden = false;
		if (column->type == VIEW_COLUMN_FILE_NAME && column->opt.display == FILENAME_AUTO)
			column->hidden = true;
	}
}

static int
resolve_max_width(struct view *view, int maxwidth)
{
	if (maxwidth < 0) {
		int pct = -maxwidth - 1;

		return view->width * pct / 100;
	}
	return maxwidth;
}

bool
view_column_info_update(struct view *view, struct line *line)
{
	struct view_column_data column_data = {0};
	struct view_column *column;
	bool changed = false;

	if (!view->columns)
		view_column_reset(view);

	if (!view->ops->get_column_data(view, line, &column_data))
		return false;

	for (column = view->columns; column; column = column->next) {
		const char *text = "";
		int width = 0;
		int maxwidth = 0;

		switch (column->type) {
		case VIEW_COLUMN_AUTHOR:
			width = column->opt.width;
			maxwidth = column->opt.maxwidth;
			if (column_data.author)
				text = mkauthor(column_data.author, column->opt.width, column->opt.display);
			break;

		case VIEW_COLUMN_COMMITTER:
			width = column->opt.width;
			maxwidth = column->opt.maxwidth;
			if (column_data.committer)
				text = mkauthor(column_data.committer, column->opt.width, column->opt.display);
			break;

		case VIEW_COLUMN_COMMIT_TITLE:
			break;

		case VIEW_COLUMN_DATE:
			width = column->opt.width;
			if (column_data.date)
				text = mkdate(column_data.date, column->opt.display,
					      column->opt.local, column->opt.format);
			break;

		case VIEW_COLUMN_REF:
			width = column->opt.width;
			maxwidth = column->opt.maxwidth;
			if (column_data.ref)
				text = column_data.ref->name;
			break;

		case VIEW_COLUMN_FILE_NAME:
			width = column->opt.width;
			maxwidth = column->opt.maxwidth;
			if (column_data.file_name) {
				text = column_data.file_name;
				if (*text)
					column->hidden = false;
			}
			break;

		case VIEW_COLUMN_FILE_SIZE:
			width = column->opt.width;
			if (column_data.file_size && !(column_data.mode && S_ISDIR(*column_data.mode)))
				text = mkfilesize(*column_data.file_size, column->opt.display);
			break;

		case VIEW_COLUMN_ID:
			width = column->opt.width;
			if (!width)
				width = opt_id_width;
			if (!width && git_config_abbrev)
				width = git_config_abbrev;
			if (!column_data.reflog && !width)
				width = 7;
			if (column->opt.display)
				text = column_data.reflog ? column_data.reflog : column_data.id;
			if (!text)
				text = "";
			if (!column_data.reflog && width)
				text = "";
			break;

		case VIEW_COLUMN_LINE_NUMBER:
			width = column->opt.width;
			if (!width) {
				if (column_data.line_number)
					width = count_digits(*column_data.line_number);
				else
					width = count_digits(view->lines);
			}
			if (width < 3)
				width = 3;
			break;

		case VIEW_COLUMN_MODE:
			width = column->opt.width;
			if (column_data.mode)
				text = mkmode(*column_data.mode);
			break;

		case VIEW_COLUMN_STATUS:
			if (column_data.status)
				text = mkstatus(*column_data.status, column->opt.display);
			break;

		default:
			break;
		}

		if (text && *text && !width)
			width = utf8_width(text);

		maxwidth = resolve_max_width(view, maxwidth);
		if (maxwidth > 0 && width > maxwidth)
			width = maxwidth;

		if (width > column->width) {
			column->width = width;
			changed = true;
		}
	}

	if (changed)
		view->force_redraw = true;
	return changed;
}
