		free(canvas->symbols);
}

static unsigned long
id_hash(const char *id)
{
	return string_hash(id) % COLOR_HASH_SIZE;
}

static void
colors_remove_id(struct colors *colors, const char *id)
{
	struct id_color **pos = &colors->map[id_hash(id)];

	for (; *pos; pos = &(*pos)->next) {
		if (!strcmp((*pos)->id, id)) {
			struct id_color *node = *pos;

			colors->count[node->color]--;
			*pos = node->next;
			free(node);
			return;
		}
	}
}

static void
colors_add_id(struct colors *colors, const char *id, const size_t color)
{
	struct id_color *node = xcalloc(1, sizeof(*node));
	unsigned long hash = id_hash(id);

	string_ncopy(node->id, id, strlen(id));
	node->color = color;
	node->next = colors->map[hash];
	colors->map[hash] = node;
	colors->count[color]++;
}

static size_t
colors_get_color(struct colors *colors, const char *id)
{
	struct id_color *node;

	for (node = colors->map[id_hash(id)]; node; node = node->next)
		if (!strcmp(node->id, id))
			return node->color;
	return (size_t) -1;
}

static size_t
colors_get_free_color(struct colors *colors)
{
	size_t free_color = 0;
	size_t lowest = (size_t) -1;
	int i;

	for (i = 0; i < GRAPH_COLORS; i++) {
		if (colors->count[i] < lowest) {
			lowest = colors->count[i];
			free_color = i;
		}
	}
	return free_color;
}

static size_t
get_color(struct graph *graph, const char *new_id)
{
	size_t color = colors_get_color(&graph->colors, new_id);

	if (color < (size_t) -1)
		return color;

	color = colors_get_free_color(&graph->colors);
	colors_add_id(&graph->colors, new_id, color);

	return color;
}

static bool
realloc_graph_columns(struct graph_row *row, size_t extra)
{
	size_t needed = row->size + extra;

	if (needed + 1 > row->alloc) {
		size_t alloc = ((needed + 1 + 31) / 32) * 32;

		row->columns = xrealloc(row->columns, alloc * sizeof(*row->columns));
		memset(row->columns + row->alloc, 0, (alloc - row->alloc) * sizeof(*row->columns));
		row->alloc = alloc;
	}
	return true;
}

static bool
graph_column_has_commit(struct graph_column *column)
{
	return !!column->id[0];
}

static size_t
graph_find_column_by_id(struct graph_row *row, const char *id)
{
	size_t free_column = row->size;
	size_t i;

	for (i = 0; i < row->size; i++) {
		if (!graph_column_has_commit(&row->columns[i]) && free_column == row->size)
			free_column = i;
		else if (!strcmp(row->columns[i].id, id))
			return i;
	}

	return free_column;
}

static size_t
graph_find_free_column(struct graph_row *row)
{
	size_t i;

	for (i = 0; i < row->size; i++) {
		if (!graph_column_has_commit(&row->columns[i]))
			return i;
	}

	return row->size;
}

static struct graph_column *
graph_insert_column(struct graph *graph, struct graph_row *row, size_t pos, const char *id)
{
	struct graph_column *column;

	realloc_graph_columns(row, 1);

	column = &row->columns[pos];
	if (pos < row->size) {
		memmove(column + 1, column, sizeof(*column) * (row->size - pos));
	}

	row->size++;
	memset(column, 0, sizeof(*column));
	string_ncopy_do(column->id, SIZEOF_REV, id, strlen(id));
	column->symbol.boundary = !!graph->is_boundary;

	return column;
}

bool
graph_add_parent(struct graph *graph, const char *parent)
{
	if (graph->has_parents)
		return true;
	return graph_insert_column(graph, &graph->parents, graph->parents.size, parent) != NULL;
}

static bool
graph_needs_expansion(struct graph *graph)
{
	return graph->position + graph->parents.size > graph->row.size;
}

static bool
graph_expand(struct graph *graph)
{
	while (graph_needs_expansion(graph)) {
		if (!graph_insert_column(graph, &graph->prev_row, graph->prev_row.size, ""))
			return false;

		if (!graph_insert_column(graph, &graph->row, graph->row.size, ""))
			return false;

		if (!graph_insert_column(graph, &graph->next_row, graph->next_row.size, ""))
			return false;
	}

	return true;
}

static bool
graph_needs_collapsing(struct graph *graph)
{
	return graph->row.size > 1
	    && !graph_column_has_commit(&graph->row.columns[graph->row.size - 1]);
}

static bool
graph_collapse(struct graph *graph)
{
	while (graph_needs_collapsing(graph)) {
		graph->prev_row.size--;
		graph->row.size--;
		graph->next_row.size--;
	}

	return true;
}

static void
graph_reorder_parents(struct graph *graph)
{
	struct graph_row *row = &graph->row;
	struct graph_row *parents = &graph->parents;
	size_t i;

	if (parents->size == 1)
		return;

	for (i = 0; i < parents->size; i++) {
		struct graph_column *column = &parents->columns[i];
		size_t match = graph_find_column_by_id(row, column->id);

		if (match < graph->position && graph_column_has_commit(&row->columns[match])) {
			struct graph_column swap = parents->columns[0];

			parents->columns[0] = *column;
			*column = swap;
		}
	}
}

static void
graph_canvas_append_symbol(struct graph *graph, struct graph_symbol *symbol)
{
	struct graph_canvas *canvas = graph->canvas;

	canvas->symbols = xrealloc(canvas->symbols, sizeof(*canvas->symbols) * (canvas->size + 1));
	canvas->symbols[canvas->size++] = *symbol;
}

static void
graph_row_clear_commit(struct graph_row *row, const char *id)
{
	size_t i;

	for (i = 0; i < row->size; i++) {
		if (strcmp(row->columns[i].id, id) == 0) {
			row->columns[i].id[0] = 0;
		}
	}
}

static void
graph_insert_parents(struct graph *graph)
{
	struct graph_row *prev_row = &graph->prev_row;
	struct graph_row *row = &graph->row;
	struct graph_row *next_row = &graph->next_row;
	struct graph_row *parents = &graph->parents;
	size_t i;

	for (i = 0; i < parents->size; i++) {
		struct graph_column *new = &parents->columns[i];

		if (graph_column_has_commit(new)) {
			size_t match = graph_find_free_column(next_row);

			if (match == next_row->size) {
				graph_insert_column(graph, next_row, next_row->size, new->id);
				graph_insert_column(graph, row, row->size, "");
				graph_insert_column(graph, prev_row, prev_row->size, "");
			} else {
				next_row->columns[match] = *new;
			}
		}
	}
}

static bool
commit_is_in_row(const char *id, struct graph_row *row)
{
	size_t i;

	for (i = 0; i < row->size; i++) {
		if (!graph_column_has_commit(&row->columns[i]))
			continue;

		if (strcmp(id, row->columns[i].id) == 0)
			return true;
	}

	return false;
}

static void
graph_remove_collapsed_columns(struct graph *graph)
{
	struct graph_row *row = &graph->next_row;
	long i;

	realloc_graph_columns(row, 1);
	realloc_graph_columns(&graph->prev_row, 1);

	for (i = row->size - 1; i > 0; i--) {
		if ((size_t) i == graph->position)
			continue;

		if ((size_t) i == graph->position + 1)
			continue;

		if (strcmp(row->columns[i].id, graph->id) == 0)
			continue;

		if (strcmp(row->columns[i].id, row->columns[i - 1].id) != 0)
			continue;

		if (commit_is_in_row(row->columns[i].id, &graph->parents) &&
		    !graph_column_has_commit(&graph->prev_row.columns[i]))
			continue;

		if (strcmp(row->columns[i - 1].id, graph->prev_row.columns[i - 1].id) != 0 ||
		    graph->prev_row.columns[i - 1].symbol.shift_left)
			row->columns[i] = row->columns[i + 1];
	}
}

static void
graph_fill_empty_columns(struct graph *graph)
{
	struct graph_row *row = &graph->next_row;
	long i;

	for (i = row->size - 2; i >= 0; i--) {
		if (!graph_column_has_commit(&row->columns[i])) {
			row->columns[i] = row->columns[i + 1];
		}
	}
}

static void
graph_generate_next_row(struct graph *graph)
{
	graph_row_clear_commit(&graph->next_row, graph->id);
	graph_insert_parents(graph);
	graph_remove_collapsed_columns(graph);
	graph_fill_empty_columns(graph);
}

static int
commits_in_row(struct graph_row *row)
{
	int count = 0;
	size_t i;

	for (i = 0; i < row->size; i++) {
		if (graph_column_has_commit(&row->columns[i]))
			count++;
	}

	return count;
}

static void
graph_commit_next_row(struct graph *graph)
{
	size_t i;

	for (i = 0; i < graph->row.size; i++) {
		graph->prev_row.columns[i] = graph->row.columns[i];

		if (i == graph->position && commits_in_row(&graph->parents) > 0)
			graph->prev_row.columns[i] = graph->next_row.columns[i];

		if (!graph_column_has_commit(&graph->prev_row.columns[i]))
			graph->prev_row.columns[i] = graph->next_row.columns[i];

		graph->row.columns[i] = graph->next_row.columns[i];
	}

	graph->prev_position = graph->position;
}

static bool
continued_down(struct graph_row *row, struct graph_row *next_row, int pos)
{
	if (strcmp(row->columns[pos].id, next_row->columns[pos].id) != 0)
		return false;

	if (row->columns[pos].symbol.shift_left)
		return false;

	return true;
}

static bool
shift_left(struct graph_row *row, struct graph_row *prev_row, int pos)
{
	int i;

	if (!graph_column_has_commit(&row->columns[pos]))
		return false;

	for (i = pos - 1; i >= 0; i--) {
		if (!graph_column_has_commit(&row->columns[i]))
			continue;

		if (strcmp(row->columns[i].id, row->columns[pos].id) != 0)
			continue;

		if (!continued_down(prev_row, row, i))
			return true;

		break;
	}

	return false;
}

static bool
new_column(struct graph_row *row, struct graph_row *prev_row, int pos)
{
	size_t i;

	if (!graph_column_has_commit(&prev_row->columns[pos]))
		return true;

	for (i = pos; i < row->size; i++) {
		if (strcmp(row->columns[pos].id, prev_row->columns[i].id) == 0)
			return false;
	}

	return true;
}

static bool
continued_right(struct graph_row *row, int pos, int commit_pos)
{
	int i, end;

	if (pos < commit_pos)
		end = commit_pos;
	else
		end = row->size;

	for (i = pos + 1; i < end; i++) {
		if (strcmp(row->columns[pos].id, row->columns[i].id) == 0)
			return true;
	}

	return false;
}

static bool
continued_left(struct graph_row *row, int pos, int commit_pos)
{
	int i, start;

	if (pos < commit_pos)
		start = 0;
	else
		start = commit_pos;

	for (i = start; i < pos; i++) {
		if (!graph_column_has_commit(&row->columns[i]))
			continue;

		if (strcmp(row->columns[pos].id, row->columns[i].id) == 0)
			return true;
	}

	return false;
}

static bool
parent_down(struct graph_row *parents, struct graph_row *next_row, int pos)
{
	size_t parent;

	for (parent = 0; parent < parents->size; parent++) {
		if (!graph_column_has_commit(&parents->columns[parent]))
			continue;

		if (strcmp(parents->columns[parent].id, next_row->columns[pos].id) == 0)
			return true;
	}

	return false;
}

static bool
parent_right(struct graph_row *parents, struct graph_row *row, struct graph_row *next_row, int pos)
{
	size_t parent, i;

	for (parent = 0; parent < parents->size; parent++) {
		if (!graph_column_has_commit(&parents->columns[parent]))
			continue;

		for (i = pos + 1; i < next_row->size; i++) {
			if (strcmp(parents->columns[parent].id, next_row->columns[i].id) != 0)
				continue;

			if (strcmp(parents->columns[parent].id, row->columns[i].id) != 0)
				return true;
		}
	}

	return false;
}

static bool
flanked(struct graph_row *row, int pos, int commit_pos, const char *commit_id)
{
	int i, start, end;

	if (pos < commit_pos) {
		start = 0;
		end = pos;
	} else {
		start = pos + 1;
		end = row->size;
	}

	for (i = start; i < end; i++) {
		if (strcmp(row->columns[i].id, commit_id) == 0)
			return true;
	}

	return false;
}

static bool
below_commit(int pos, struct graph *graph)
{
	if ((size_t) (!pos) == graph->prev_position)
		return false;

	if ((!strcmp(graph->row.columns[pos].id, graph->prev_row.columns[pos].id)) == 0)
		return false;

	return true;
}

static void
graph_generate_symbols(struct graph *graph, struct graph_canvas *canvas)
{
	struct graph_row *prev_row = &graph->prev_row;
	struct graph_row *row = &graph->row;
	struct graph_row *next_row = &graph->next_row;
	struct graph_row *parents = &graph->parents;
	size_t pos;

	(void) canvas;
	for (pos = 0; pos < row->size; pos++) {
		struct graph_column *column = &row->columns[pos];
		struct graph_symbol *symbol = &column->symbol;
		const char *id = next_row->columns[pos].id;

		symbol->commit            = (pos == graph->position);
		symbol->boundary          = (pos == graph->position && next_row->columns[pos].symbol.boundary);
		symbol->initial           = !graph_column_has_commit(&next_row->columns[pos]);
		symbol->merge             = (pos == graph->position && parents->size > 1);

		symbol->continued_up      = continued_down(prev_row, row, pos);
		symbol->continued_up_left = continued_left(prev_row, pos, prev_row->size);
		symbol->continued_down    = continued_down(row, next_row, pos);
		symbol->continued_right   = continued_right(row, pos, graph->position);
		symbol->continued_left    = continued_left(row, pos, graph->position);

		symbol->parent_down       = parent_down(parents, next_row, pos);
		symbol->parent_right      = (pos > graph->position && parent_right(parents, row, next_row, pos));

		symbol->below_commit      = below_commit(pos, graph);
		symbol->flanked           = flanked(row, pos, graph->position, graph->id);
		symbol->next_right        = continued_right(next_row, pos, 0);
		symbol->matches_commit    = (strcmp(column->id, graph->id) == 0);

		symbol->shift_left        = shift_left(row, prev_row, pos);
		symbol->continue_shift    = (pos + 1 < row->size) ? shift_left(row, prev_row, pos + 1) : 0;
		symbol->below_shift       = prev_row->columns[pos].symbol.shift_left;

		symbol->new_column        = new_column(row, prev_row, pos);
		symbol->empty             = (!graph_column_has_commit(&row->columns[pos]));

		if (graph_column_has_commit(column)) {
			id = column->id;
		}
		symbol->color = get_color(graph, id);

		graph_canvas_append_symbol(graph, symbol);
	}

	colors_remove_id(&graph->colors, graph->id);
}

bool
graph_render_parents(struct graph *graph, struct graph_canvas *canvas)
{
	(void) canvas;
	if (!graph_expand(graph))
		return false;

	graph_reorder_parents(graph);
	graph_generate_next_row(graph);
	graph_generate_symbols(graph, graph->canvas);
	graph_commit_next_row(graph);

	graph->parents.size = graph->position = 0;

	if (!graph_collapse(graph))
		return false;

	return true;
}

bool
graph_add_commit(struct graph *graph, struct graph_canvas *canvas,
		 const char *id, const char *parents, bool is_boundary)
{
	int has_parents = 0;

	graph->canvas = canvas;
	graph->position = graph_find_column_by_id(&graph->row, id);
	string_copy_rev(graph->id, id);
	graph->is_boundary = is_boundary;
	graph->has_parents = false;

	while ((parents = strchr(parents, ' '))) {
		parents++;
		if (!graph_add_parent(graph, parents))
			return false;
		has_parents++;
	}

	graph->has_parents = has_parents > 0;

	return true;
}

bool
graph_is_merge(struct graph_canvas *canvas)
{
	size_t i;

	for (i = 0; i < canvas->size; i++)
		if (canvas->symbols[i].commit && canvas->symbols[i].merge)
			return true;
	return false;
}

struct graph *
init_graph(int display)
{
	struct graph *graph = xcalloc(1, sizeof(*graph));

	(void) display;
	return graph;
}

void
done_graph(struct graph *graph)
{
	int i;

	if (!graph)
		return;
	free(graph->row.columns);
	free(graph->parents.columns);
	free(graph->prev_row.columns);
	free(graph->next_row.columns);
	for (i = 0; i < COLOR_HASH_SIZE; i++) {
		struct id_color *node = graph->colors.map[i], *next;

		for (; node; node = next) {
			next = node->next;
			free(node);
		}
	}
	free(graph);
}

void
graph_done_rendering(struct graph *graph)
{
	(void) graph;
}

/* ------------------------------------------------------------------ */
/* Symbol rendering */

static bool
graph_symbol_forks(const struct graph_symbol *symbol)
{
	if (!symbol->continued_down)
		return false;

	if (!symbol->continued_right)
		return false;

	if (!symbol->continued_up)
		return false;

	return true;
}

static bool
graph_symbol_cross_merge(const struct graph_symbol *symbol)
{
	if (symbol->empty)
		return false;

	if (!symbol->continued_up && !symbol->new_column && !symbol->below_commit)
		return false;

	if (!symbol->shift_left)
		return false;

	if (symbol->parent_down)
		return false;

	if (symbol->flanked)
		return false;

	return true;
}

static bool
graph_symbol_vertical_merge(const struct graph_symbol *symbol)
{
	if (symbol->empty)
		return false;

	if (!symbol->continued_up && !symbol->new_column && !symbol->below_commit)
		return false;

	if (!symbol->shift_left)
		return false;

	if (!symbol->parent_down)
		return false;

	if (symbol->flanked)
		return false;

	return true;
}

static bool
graph_symbol_cross_over(const struct graph_symbol *symbol)
{
	if (symbol->empty)
		return false;

	if (!symbol->continued_down)
		return false;

	if (!symbol->continued_up && !symbol->new_column && !symbol->below_commit)
		return false;

	if (symbol->flanked)
		return true;

	if (symbol->merge)
		return true;

	return false;
}

static bool
graph_symbol_turn_left(const struct graph_symbol *symbol)
{
	if (symbol->continued_down)
		return false;

	if (!symbol->continued_left)
		return false;

	if (symbol->continued_up || symbol->new_column)
		return true;

	if (symbol->below_commit)
		return true;

	return false;
}

static bool
graph_symbol_turn_down_cross_over(const struct graph_symbol *symbol)
{
	if (!symbol->continued_down)
		return false;

	if (!symbol->continued_right)
		return false;

	if (symbol->flanked)
		return true;

	if (symbol->merge)
		return true;

	return false;
}

static bool
graph_symbol_turn_down(const struct graph_symbol *symbol)
{
	if (!symbol->continued_down)
		return false;

	if (!symbol->continued_right)
		return false;

	return true;
}

static bool
graph_symbol_merge(const struct graph_symbol *symbol)
{
	if (symbol->continued_down)
		return false;

	if (!symbol->parent_down)
		return false;

	if (symbol->parent_right)
		return false;

	return true;
}

static bool
graph_symbol_multi_merge(const struct graph_symbol *symbol)
{
	if (!symbol->parent_down)
		return false;

	if (!symbol->parent_right)
		return false;

	return true;
}

static bool
graph_symbol_vertical_bar(const struct graph_symbol *symbol)
{
	if (symbol->empty)
		return false;

	if (symbol->shift_left)
		return false;

	if (!symbol->continued_down)
		return false;

	if (symbol->continued_up)
		return true;

	if (symbol->parent_right)
		return false;

	if (symbol->flanked)
		return false;

	if (symbol->continued_right)
		return false;

	return true;
}

static bool
graph_symbol_horizontal_bar(const struct graph_symbol *symbol)
{
	if (!symbol->next_right)
		return false;

	if (symbol->shift_left)
		return true;

	if (symbol->continued_down)
		return false;

	if (!symbol->parent_right && !symbol->continued_right)
		return false;

	if ((symbol->continued_up && !symbol->continued_up_left))
		return false;

	if (!symbol->below_commit)
		return true;

	return false;
}

static bool
graph_symbol_multi_branch(const struct graph_symbol *symbol)
{
	if (symbol->continued_down)
		return false;

	if (!symbol->continued_right)
		return false;

	if (symbol->below_shift)
		return false;

	if (symbol->continued_up || symbol->new_column || symbol->below_commit) {
		if (symbol->matches_commit)
			return true;

		if (symbol->shift_left)
			return true;
	}

	return false;
}

static const char *
graph_symbol_to_utf8(const struct graph_symbol *symbol)
{
	if (symbol->commit) {
		if (symbol->boundary)
			return " \xe2\x97\xaf";
		else if (symbol->initial)
			return " \xe2\x97\x8e";
		else if (symbol->merge)
			return " \xe2\x97\x8f";
		return " \xe2\x88\x99";
	}

	if (graph_symbol_cross_merge(symbol))
		return "\xe2\x94\x80\xe2\x94\xbc";

	if (graph_symbol_vertical_merge(symbol))
		return "\xe2\x94\x80\xe2\x94\xa4";

	if (graph_symbol_cross_over(symbol))
		return "\xe2\x94\x80\xe2\x94\x82";

	if (graph_symbol_vertical_bar(symbol))
		return " \xe2\x94\x82";

	if (graph_symbol_turn_left(symbol))
		return "\xe2\x94\x80\xe2\x95\xaf";

	if (graph_symbol_multi_branch(symbol))
		return "\xe2\x94\x80\xe2\x94\xb4";

	if (graph_symbol_horizontal_bar(symbol))
		return "\xe2\x94\x80\xe2\x94\x80";

	if (graph_symbol_forks(symbol))
		return " \xe2\x94\x9c";

	if (graph_symbol_turn_down_cross_over(symbol))
		return "\xe2\x94\x80\xe2\x95\xad";

	if (graph_symbol_turn_down(symbol))
		return " \xe2\x95\xad";

	if (graph_symbol_merge(symbol))
		return "\xe2\x94\x80\xe2\x95\xae";

	if (graph_symbol_multi_merge(symbol))
		return "\xe2\x94\x80\xe2\x94\xac";

	return "  ";
}

static const chtype *
graph_symbol_to_chtype(const struct graph_symbol *symbol)
{
	static chtype graphics[2];

	if (symbol->commit) {
		graphics[0] = ' ';
		if (symbol->boundary)
			graphics[1] = 'o';
		else if (symbol->initial)
			graphics[1] = 'I';
		else if (symbol->merge)
			graphics[1] = 'M';
		else
			graphics[1] = 'o';
		return graphics;
	}

	if (graph_symbol_cross_merge(symbol)) {
		graphics[0] = ACS_HLINE;
		graphics[1] = ACS_PLUS;
		return graphics;
	}

	if (graph_symbol_vertical_merge(symbol)) {
		graphics[0] = ACS_HLINE;
		graphics[1] = ACS_RTEE;
		return graphics;
	}

	if (graph_symbol_cross_over(symbol)) {
		graphics[0] = ACS_HLINE;
		graphics[1] = ACS_VLINE;
		return graphics;
	}

	if (graph_symbol_vertical_bar(symbol)) {
		graphics[0] = ' ';
		graphics[1] = ACS_VLINE;
		return graphics;
	}

	if (graph_symbol_turn_left(symbol)) {
		graphics[0] = ACS_HLINE;
		graphics[1] = ACS_LRCORNER;
		return graphics;
	}

	if (graph_symbol_multi_branch(symbol)) {
		graphics[0] = ACS_HLINE;
		graphics[1] = ACS_BTEE;
		return graphics;
	}

	if (graph_symbol_horizontal_bar(symbol)) {
		graphics[0] = graphics[1] = ACS_HLINE;
		return graphics;
	}

	if (graph_symbol_forks(symbol)) {
		graphics[0] = ' ';
		graphics[1] = ACS_LTEE;
		return graphics;
	}

	if (graph_symbol_turn_down_cross_over(symbol)) {
		graphics[0] = ACS_HLINE;
		graphics[1] = ACS_ULCORNER;
		return graphics;
	}

	if (graph_symbol_turn_down(symbol)) {
		graphics[0] = ' ';
		graphics[1] = ACS_ULCORNER;
		return graphics;
	}

	if (graph_symbol_merge(symbol)) {
		graphics[0] = ACS_HLINE;
		graphics[1] = ACS_URCORNER;
		return graphics;
	}

	if (graph_symbol_multi_merge(symbol)) {
		graphics[0] = ACS_HLINE;
		graphics[1] = ACS_TTEE;
		return graphics;
	}

	graphics[0] = graphics[1] = ' ';
	return graphics;
}

static const char *
graph_symbol_to_ascii(const struct graph_symbol *symbol)
{
	if (symbol->commit) {
		if (symbol->boundary)
			return " o";
		else if (symbol->initial)
			return " I";
		else if (symbol->merge)
			return " M";
		return " *";
	}

	if (graph_symbol_cross_merge(symbol))
		return "-+";

	if (graph_symbol_vertical_merge(symbol))
		return "-|";

	if (graph_symbol_cross_over(symbol))
		return "-|";

	if (graph_symbol_vertical_bar(symbol))
		return " |";

	if (graph_symbol_turn_left(symbol))
		return "-'";

	if (graph_symbol_multi_branch(symbol))
		return "-+";

	if (graph_symbol_horizontal_bar(symbol))
		return "--";

	if (graph_symbol_forks(symbol))
		return " +";

	if (graph_symbol_turn_down_cross_over(symbol))
		return "-.";

	if (graph_symbol_turn_down(symbol))
		return " .";

	if (graph_symbol_merge(symbol))
		return "-.";

	if (graph_symbol_multi_merge(symbol))
		return "-+";

	return "  ";
}

bool
draw_graph(struct view *view, const struct graph *graph, const struct graph_canvas *canvas)
{
	size_t i;

	(void) graph;
	for (i = 0; i < canvas->size; i++) {
		struct graph_symbol *symbol = &canvas->symbols[i];
		line_type_t color_id = symbol->commit ? LINE_GRAPH_COMMIT : LINE_PALETTE_0 + symbol->color % GRAPH_COLORS;
		bool first = i == 0;

		switch (opt_line_graphics) {
		case GRAPHIC_ASCII:
			if (draw_text(view, color_id, graph_symbol_to_ascii(symbol) + !!first))
				return true;
			break;
		case GRAPHIC_UTF_8: {
			const char *chars = graph_symbol_to_utf8(symbol);

			if (first)
				chars += utf8_char_length(chars);
			if (draw_text(view, color_id, chars))
				return true;
			break;
		}
		default: {
			const chtype *chars = graph_symbol_to_chtype(symbol);

			if (draw_graphic(view, color_id, chars + !!first, 2 - !!first, false))
				return true;
			break;
		}
		}
	}

	return draw_text(view, LINE_DEFAULT, " ");
}
EOF
echo ok"}

