static const struct ident not_committed_ident = { "Not Committed Yet", "" };

static bool
main_status_line_type(line_type_t type)
{
	return type == LINE_STAT_STAGED || type == LINE_STAT_UNSTAGED || type == LINE_STAT_UNTRACKED;
}

bool
index_diff(struct index_diff *diff, bool untracked, bool count_all)
{
	const char *untracked_arg = !untracked ? "--untracked-files=no" :
				     count_all ? "--untracked-files=all" :
						 "--untracked-files=normal";
	const char *status_argv[] = {
		"git", "status", "--porcelain", "-z", untracked_arg, NULL
	};
	size_t len;
	int status;
	char *out = io_capture(status_argv, repo.cdup[0] ? NULL : NULL, &len, &status, false);
	char *pos, *end;

	memset(diff, 0, sizeof(*diff));
	if (!out)
		return false;
	if (status != 0) {
		free(out);
		return false;
	}

	pos = out;
	end = out + len;
	while (pos < end) {
		size_t entrylen = strnlen(pos, end - pos);

		if (entrylen <= 3)
			break;
		if (pos[0] == '?')
			diff->untracked++;
		else if (pos[0] != ' ' && pos[0] != 'U')
			diff->staged++;
		if (pos[1] != ' ' && pos[1] != '?')
			diff->unstaged++;

		if (pos[0] == 'R' || pos[0] == 'C') {
			pos += entrylen + 1;
			if (pos >= end)
				break;
			entrylen = strnlen(pos, end - pos);
		}
		pos += entrylen + 1;
	}

	free(out);
	return true;
}

static struct commit *
main_add_commit(struct view *view, line_type_t type, struct commit *template,
		const char *title, bool custom)
{
	struct main_state *state = view->private;
	struct commit *commit;
	char buf[SIZEOF_STR / 2];
	struct line *line;

	string_expand(buf, sizeof(buf), title, strlen(title), 1);

	line = add_line_alloc(view, &commit, type, 0, custom);
	if (!line)
		return NULL;

	*commit = *template;
	commit->title = xstrdup(buf);
	memset(template, 0, sizeof(*template));
	state->reflogmsg[0] = 0;

	view_column_info_update(view, line);

	if (view->env->goto_id[0] && !strncmp(view->env->goto_id, commit->id, strlen(view->env->goto_id))) {
		view->prev_pos.lineno = view->lines - 1;
		view->prev_pos.offset = 0;
		view->env->goto_id[0] = 0;
		state->goto_done = true;
	}

	return commit;
}

static void
main_register_commit(struct view *view, struct commit *commit, const char *ids, bool is_boundary);

static void
main_add_changes_commit(struct view *view, line_type_t type, const char *parent, const char *title)
{
	char ids[SIZEOF_STR] = NULL_ID " ";
	struct main_state *state = view->private;
	struct commit commit;
	struct timeval now;

	if (!parent)
		return;

	memset(&commit, 0, sizeof(commit));
	string_ncopy_do(ids + STRING_SIZE(NULL_ID " "), sizeof(ids) - STRING_SIZE(NULL_ID " "), parent, strlen(parent));

	if (time_now(&now)) {
		commit.time.tz = 0;
		commit.time.sec = now.tv_sec;
		commit.ctime = commit.time;
	}

	commit.author = &not_committed_ident;
	commit.committer = &not_committed_ident;
	main_register_commit(view, &commit, ids, false);
	if (state->with_graph && *parent)
		graph_render_parents(state->graph, commit.graph);

	main_add_commit(view, type, &commit, title, true);
}

static void
main_add_changes(struct view *view, struct main_state *state, const char *parent)
{
	const char *staged_parent = parent;
	const char *unstaged_parent = NULL_ID;
	const char *untracked_parent = NULL_ID;

	if (!state->add_changes_staged) {
		staged_parent = NULL;
		unstaged_parent = parent;
	}

	if (!state->add_changes_unstaged) {
		unstaged_parent = NULL;
		if (!state->add_changes_staged)
			untracked_parent = parent;
	}

	if (!state->add_changes_untracked) {
		untracked_parent = NULL;
	}

	main_add_changes_commit(view, LINE_STAT_UNTRACKED, untracked_parent, "Untracked changes");
	main_add_changes_commit(view, LINE_STAT_UNSTAGED, unstaged_parent, "Unstaged changes");
	main_add_changes_commit(view, LINE_STAT_STAGED, staged_parent, "Staged changes");
}

static void
main_register_commit(struct view *view, struct commit *commit, const char *ids, bool is_boundary)
{
	struct main_state *state = view->private;

	string_copy_rev(commit->id, ids);

	if ((state->add_changes_untracked || state->add_changes_unstaged || state->add_changes_staged) &&
	    *repo.head_id && !strncmp(commit->id, repo.head_id, SIZEOF_REV - 1)) {
		state->add_changes_untracked |= 0;
		main_add_changes(view, state, ids);
		state->add_changes_untracked = state->add_changes_unstaged = state->add_changes_staged = false;
	}

	if (state->with_graph) {
		if (!commit->graph)
			commit->graph = xcalloc(1, graph_canvas_size());
		graph_add_commit(state->graph, commit->graph, commit->id, ids, is_boundary);
	}
}

static bool
main_check_index(struct view *view, struct main_state *state)
{
	struct index_diff diff;

	(void) view;
	if (!index_diff(&diff, opt_show_untracked, false))
		return false;

	if (diff.untracked)
		state->add_changes_untracked = true;
	if (diff.unstaged)
		state->add_changes_unstaged = true;
	if (diff.staged)
		state->add_changes_staged = true;

	return true;
}

static int
main_with_graph(struct view *view, enum open_flags flags)
{
	struct view_column *column;

	if (!view->columns || view_columns_changed(view))
		view_column_reset(view);
	column = get_view_column(view, VIEW_COLUMN_COMMIT_TITLE);

	return column && column->opt.display && column->opt.graph &&
	       opt_commit_order != COMMIT_ORDER_REVERSE &&
	       !(flags & OPEN_PAGER_MODE)
		? column->opt.graph : GRAPH_DISPLAY_NO;
}

static void
main_free_commit(struct commit *commit)
{
	if (!commit)
		return;
	free(commit->title);
	if (commit->graph) {
		graph_canvas_free(commit->graph);
		free(commit->graph);
	}
}

void
main_done(struct view *view)
{
	struct main_state *state = view->private;
	size_t i;

	for (i = 0; i < view->lines; i++)
		main_free_commit(view->line[i].data);

	if (!state)
		return;

	if (state->graph)
		done_graph(state->graph);
	state->graph = NULL;
	for (i = 0; i < state->reflogs; i++)
		free(state->reflog[i]);
	free(state->reflog);
	state->reflog = NULL;
	state->reflogs = 0;
}

static enum status_code
main_open(struct view *view, enum open_flags flags)
{
	struct main_state *state = view->private;
	int graph_display;
	const char *main_argv[] = {
		"git", "log", "--encoding=UTF-8", "--no-color",
		"", "%(mainargs)", "%(cmdlineargs)", "%(revargs)",
		"--date=raw", log_custom_pretty_arg(), "--parents",
		"--", "%(fileargs)", NULL
	};

	main_done(view);
	view_column_reset(view);
	graph_display = main_with_graph(view, flags);
	main_argv[4] = commit_order_arg_with_graph(graph_display);

	if (!opt_rev_filter)
		main_argv[7] = "";

	if (opt_show_changes && repo.is_inside_work_tree && !(flags & OPEN_PAGER_MODE))
		main_check_index(view, state);

	state->with_graph = graph_display != GRAPH_DISPLAY_NO;
	if (state->with_graph)
		state->graph = init_graph(graph_display);

	if (!begin_update(view, NULL, main_argv, flags))
