actions.command:
cat > /workspace/src/main_view.c <<'EOF'
/* Main view: commit list with revision graph */
#include "tigview.h"

struct main_state {
	struct graph *graph;
	struct commit current;
	char **reflog;
	size_t reflogs;
	int reflog_width;
	char reflogmsg[SIZEOF_STR / 2];
	bool in_header;
	bool with_graph;
	bool add_changes_staged;
	bool add_changes_unstaged;
	bool add_changes_untracked;
	bool is_reflog;
	bool goto_done;
};

static const struct ident not_committed_ident = { "Not Committed Yet", "" };

static bool
main_status_line_type(line_type_t type)
{
	return type == LINE_STAT_STAGED || type == LINE_STAT_UNSTAGED || type == LINE_STAT_UNTRACKED;
}

bool
index_diff(struct index_diff *diff, bool untracked, bool count_all)
{
	const char *untracked_arg = !untracked ? "--untracked-files=no" :
				     count_all ? "--untracked-files=all" :
						 "--untracked-files=normal";
	const char *status_argv[] = {
		"git", "status", "--porcelain", "-z", untracked_arg, NULL
	};
	size_t len;
	int status;
	char *out = io_capture(status_argv, repo.cdup[0] ? NULL : NULL, &len, &status, false);
	char *pos, *end;

	memset(diff, 0, sizeof(*diff));
	if (!out)
		return false;
	if (status != 0) {
		free(out);
		return false;
	}

	pos = out;
	end = out + len;
	while (pos < end) {
		size_t entrylen = strnlen(pos, end - pos);

		if (entrylen <= 3)
			break;
		if (pos[0] == '?')
			diff->untracked++;
		else if (pos[0] != ' ' && pos[0] != 'U')
			diff->staged++;
		if (pos[1] != ' ' && pos[1] != '?')
			diff->unstaged++;

		if (pos[0] == 'R' || pos[0] == 'C') {
			pos += entrylen + 1;
			if (pos >= end)
				break;
			entrylen = strnlen(pos, end - pos);
		}
		pos += entrylen + 1;
	}

	free(out);
	return true;
}

static struct commit *
main_add_commit(struct view *view, line_type_t type, struct commit *template,
		const char *title, bool custom)
{
	struct main_state *state = view->private;
	struct commit *commit;
	char buf[SIZEOF_STR / 2];
	struct line *line;

	string_expand(buf, sizeof(buf), title, strlen(title), 1);

	line = add_line_alloc(view, &commit, type, 0, custom);
	if (!line)
		return NULL;

	*commit = *template;
	commit->title = xstrdup(buf);
	memset(template, 0, sizeof(*template));
	state->reflogmsg[0] = 0;

	view_column_info_update(view, line);

	if (view->env->goto_id[0] && !strncmp(view->env->goto_id, commit->id, strlen(view->env->goto_id))) {
		view->prev_pos.lineno = view->lines - 1;
		view->prev_pos.offset = 0;
		view->env->goto_id[0] = 0;
		state->goto_done = true;
	}

	return commit;
}

static void
main_register_commit(struct view *view, struct commit *commit, const char *ids, bool is_boundary);

static void
main_add_changes_commit(struct view *view, line_type_t type, const char *parent, const char *title)
{
	char ids[SIZEOF_STR] = NULL_ID " ";
	struct main_state *state = view->private;
	struct commit commit;
	struct timeval now;

	if (!parent)
		return;

	memset(&commit, 0, sizeof(commit));
	string_ncopy_do(ids + STRING_SIZE(NULL_ID " "), sizeof(ids) - STRING_SIZE(NULL_ID " "), parent, strlen(parent));

	if (time_now(&now)) {
		commit.time.tz = 0;
		commit.time.sec = now.tv_sec;
		commit.ctime = commit.time;
	}

	commit.author = &not_committed_ident;
	commit.committer = &not_committed_ident;
	main_register_commit(view, &commit, ids, false);
	if (state->with_graph && *parent)
		graph_render_parents(state->graph, commit.graph);

	main_add_commit(view, type, &commit, title, true);
}

static void
main_add_changes(struct view *view, struct main_state *state, const char *parent)
{
	const char *staged_parent = parent;
	const char *unstaged_parent = NULL_ID;
	const char *untracked_parent = NULL_ID;

	if (!state->add_changes_staged) {
		staged_parent = NULL;
		unstaged_parent = parent;
	}

	if (!state->add_changes_unstaged) {
		unstaged_parent = NULL;
		if (!state->add_changes_staged)
			untracked_parent = parent;
	}

	if (!state->add_changes_untracked) {
		untracked_parent = NULL;
	}

	main_add_changes_commit(view, LINE_STAT_UNTRACKED, untracked_parent, "Untracked changes");
	main_add_changes_commit(view, LINE_STAT_UNSTAGED, unstaged_parent, "Unstaged changes");
	main_add_changes_commit(view, LINE_STAT_STAGED, staged_parent, "Staged changes");
}

static void
main_register_commit(struct view *view, struct commit *commit, const char *ids, bool is_boundary)
{
	struct main_state *state = view->private;

	string_copy_rev(commit->id, ids);

	if ((state->add_changes_untracked || state->add_changes_unstaged || state->add_changes_staged) &&
	    *repo.head_id && !strncmp(commit->id, repo.head_id, SIZEOF_REV - 1)) {
		state->add_changes_untracked |= 0;
		main_add_changes(view, state, ids);
		state->add_changes_untracked = state->add_changes_unstaged = state->add_changes_staged = false;
	}

	if (state->with_graph) {
		if (!commit->graph)
			commit->graph = xcalloc(1, graph_canvas_size());
		graph_add_commit(state->graph, commit->graph, commit->id, ids, is_boundary);
	}
}

static bool
main_check_index(struct view *view, struct main_state *state)
{
	struct index_diff diff;

	(void) view;
	if (!index_diff(&diff, opt_show_untracked, false))
		return false;

	if (diff.untracked)
		state->add_changes_untracked = true;
	if (diff.unstaged)
		state->add_changes_unstaged = true;
	if (diff.staged)
		state->add_changes_staged = true;

	return true;
}

static int
main_with_graph(struct view *view, enum open_flags flags)
{
	struct view_column *column;

	if (!view->columns || view_columns_changed(view))
		view_column_reset(view);
	column = get_view_column(view, VIEW_COLUMN_COMMIT_TITLE);

	return column && column->opt.display && column->opt.graph &&
	       opt_commit_order != COMMIT_ORDER_REVERSE &&
	       !(flags & OPEN_PAGER_MODE)
		? column->opt.graph : GRAPH_DISPLAY_NO;
}

static void
main_free_commit(struct commit *commit)
{
	if (!commit)
		return;
	free(commit->title);
	if (commit->graph) {
		graph_canvas_free(commit->graph);
		free(commit->graph);
	}
}

void
main_done(struct view *view)
{
	struct main_state *state = view->private;
	size_t i;

	for (i = 0; i < view->lines; i++)
		main_free_commit(view->line[i].data);

	if (!state)
		return;

	if (state->graph)
		done_graph(state->graph);
	state->graph = NULL;
	for (i = 0; i < state->reflogs; i++)
		free(state->reflog[i]);
	free(state->reflog);
	state->reflog = NULL;
	state->reflogs = 0;
}

static enum status_code
main_open(struct view *view, enum open_flags flags)
{
	struct main_state *state = view->private;
	int graph_display;
	const char *main_argv[] = {
		"git", "log", "--encoding=UTF-8", "--no-color",
		"", "%(mainargs)", "%(cmdlineargs)", "%(revargs)",
		"--date=raw", log_custom_pretty_arg(), "--parents",
		"--", "%(fileargs)", NULL
	};

	main_done(view);
	view_column_reset(view);
	graph_display = main_with_graph(view, flags);
	main_argv[4] = commit_order_arg_with_graph(graph_display);

	if (!opt_rev_filter)
		main_argv[7] = "";

	if (opt_show_changes && repo.is_inside_work_tree && !(flags & OPEN_PAGER_MODE))
		main_check_index(view, state);

	state->with_graph = graph_display != GRAPH_DISPLAY_NO;
	if (state->with_graph)
		state->graph = init_graph(graph_display);

	if (!begin_update(view, NULL, main_argv, flags))
		return error("Failed to open main view");

	return SUCCESS;
}

static bool
main_read(struct view *view, char *line, size_t len)
{
	struct main_state *state = view->private;
	struct commit *commit = &state->current;

	(void) len;
	if (!line) {
		if (*commit->id)
			main_add_commit(view, LINE_MAIN_COMMIT, commit, commit->title ? commit->title : "", false);

		if (state->graph) {
			graph_done_rendering(state->graph);
		}
		if (view->lines == 0 && view == display[0] && !view->prev && view->pipe_status != 0)
			die("No revisions match the given arguments.");
		if (view->lines == 0 && view == display[0] && !view->prev && !view->parent &&
		    !state->is_reflog && view->pipe_status != 0)
			die("No revisions match the given arguments.");
		return true;
	}

	if (!prefixcmp(line, "commit ")) {
		char *fields[5] = {0};
		char *pos = line + STRING_SIZE("commit ");
		char *end = line + len;
		bool is_boundary;
		int n = 0;
		char *ids;
		char *title_buf;

		is_boundary = *pos == '-';
		while (*pos && !isalnum((unsigned char) *pos))
			pos++;
		ids = pos;

		/* NUL separated fields */
		{
			char *p = pos + strlen(pos) + 1;

			while (p < end && n < 4) {
				fields[n++] = p;
				p += strlen(p) + 1;
			}
		}

		memset(commit, 0, sizeof(*commit));
		main_register_commit(view, commit, ids, is_boundary);

		if (fields[0])
			parse_author_line(fields[0], &commit->author, &commit->time);
		if (fields[1])
			parse_author_line(fields[1], &commit->committer, &commit->ctime);
		title_buf = fields[2] ? fields[2] : (char *) "";

		if (state->with_graph) {
			graph_render_parents(state->graph, commit->graph);
			commit->is_merge = graph_is_merge(commit->graph);
		} else {
			char *sp = strchr(ids, ' ');

			commit->is_merge = sp && strchr(sp + 1, ' ');
		}

		{
			char title[SIZEOF_STR];

			string_copy(title, title_buf);
			main_add_commit(view, LINE_MAIN_COMMIT, commit, title, false);
		}
		return true;
	}

	return true;
}

bool
main_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	struct main_state *state = view->private;
	struct commit *commit = line->data;
	struct view_column *date = get_view_column(view, VIEW_COLUMN_DATE);

	column_data->author = commit->author;
	column_data->committer = commit->committer;
	column_data->date = date && date->opt.use_author ? &commit->time : &commit->ctime;
	column_data->id = commit->id;
	if (state->reflogs && line->lineno > 0 && line->lineno <= state->reflogs)
		column_data->reflog = state->reflog[line->lineno - 1];

	column_data->commit_title = commit->title;
	if (state->with_graph) {
		column_data->graph = state->graph;
		column_data->graph_canvas = commit->graph;
	}

	if (!main_status_line_type(line->type))
		column_data->refs = get_ref_list(commit->id);

	return true;
}

static bool
main_draw(struct view *view, struct line *line, unsigned int lineno)
{
	struct commit *commit = line->data;

	if (!commit->author)
		return false;

	return view_column_draw(view, line, lineno);
}

static bool
main_grep(struct view *view, struct line *line)
{
	struct commit *commit = line->data;
	struct view_column *column;
	const char *text[16];
	char buf[SIZEOF_MED_STR];
	size_t pos = 0;
	int n = 0;
	const struct ref *ref;

	for (column = view->columns; column && n < 12; column = column->next) {
		switch (column->type) {
		case VIEW_COLUMN_AUTHOR:
			if (column->opt.display && commit->author)
				text[n++] = mkauthor(commit->author, column->opt.width, column->opt.display);
			break;
		case VIEW_COLUMN_DATE:
			break;
		case VIEW_COLUMN_ID:
			if (column->opt.display)
				text[n++] = commit->id;
			break;
		case VIEW_COLUMN_COMMIT_TITLE:
			if (column->opt.refs && !main_status_line_type(line->type)) {
				buf[0] = 0;
				for (ref = get_ref_list(commit->id); ref; ref = ref->next)
					string_nformat(buf, sizeof(buf), &pos, "%s%s", pos ? " " : "", ref->name);
				text[n++] = buf;
			}
			text[n++] = commit->title;
			break;
		default:
			break;
		}
	}
	text[n] = NULL;
	return grep_text(view, text);
}

void
main_select(struct view *view, struct line *line)
{
	struct commit *commit = line->data;
	struct main_state *state = view->private;

	if (main_status_line_type(line->type)) {
		string_ncopy(view->ref, commit->title, strlen(commit->title));
	} else if (state->reflogs && line->lineno > 0 && line->lineno <= state->reflogs) {
		string_copy(view->ref, state->reflog[line->lineno - 1]);
	} else {
		string_copy_rev(view->ref, commit->id);
	}
	string_copy_rev(view->env->commit, commit->id);
	if (main_status_line_type(line->type))
		view->env->blob[0] = 0;
}

static enum request
main_request(struct view *view, enum request request, struct line *line)
{
	enum open_flags flags = (view_is_displayed(view) && request != REQ_VIEW_DIFF)
				? OPEN_SPLIT : OPEN_DEFAULT;

	switch (request) {
	case REQ_NEXT:
	case REQ_PREVIOUS:
		if (view_is_displayed(view) && display[0] != view)
			return request;
		return request == REQ_NEXT ? REQ_MOVE_DOWN : REQ_MOVE_UP;

	case REQ_VIEW_DIFF:
	case REQ_ENTER:
		if (view_is_displayed(view) && display[0] != view)
			maximize_view(view, true);

		if (line->type == LINE_STAT_UNSTAGED || line->type == LINE_STAT_STAGED)
			open_stage_view(view, NULL, line->type, flags);
		else if (line->type == LINE_STAT_UNTRACKED)
			open_status_view(view, true, flags);
		else
			open_diff_view(view, flags);
		break;

	case REQ_REFRESH:
		load_refs(true);
		refresh_view(view);
		break;

	case REQ_PARENT: {
		struct commit *commit = line->data;
		const char *parent_argv[] = { "git", "rev-parse", "--verify", "-q", NULL, NULL };
		char rev[SIZEOF_STR];
		char buf[SIZEOF_REV + 1];
		size_t i;

		snprintf(rev, sizeof(rev), "%s^", commit->id);
		parent_argv[4] = rev;
		if (!io_run_buf(parent_argv, buf, sizeof(buf), NULL, false)) {
			report("Parent not found");
			break;
		}
		for (i = 0; i < view->lines; i++) {
			struct commit *c = view->line[i].data;

			if (!strncmp(c->id, buf, SIZEOF_REV - 1)) {
				select_view_line(view, i);
				report_clear();
				return REQ_NONE;
			}
		}
		report("Parent not found in view");
		break;
	}

	default:
		return request;
	}

	return REQ_NONE;
}

static struct view_ops main_ops = {
	"commit",
	argv_env.head,
	VIEW_SEND_CHILD_ENTER | VIEW_FILE_FILTER | VIEW_LOG_LIKE | VIEW_REFRESH | VIEW_HAS_ID,
	sizeof(struct main_state),
	main_open,
	main_read,
	main_draw,
	main_request,
	main_grep,
	main_select,
	main_done,
	main_get_column_data,
};

struct view main_view = {
	"main",
