static enum status_code
reflog_open(struct view *view, enum open_flags flags)
{
	struct main_state *state = view->private;
	const char *reflog_argv[] = {
		"git", "reflog", "show", "--encoding=UTF-8", "--no-color",
		"%(cmdlineargs)", "%(revargs)", "--date=raw",
		opt_mailmap ? "--pretty=format:commit %m %H %P%x00%aN <%aE> %ad%x00%cN <%cE> %cd%x00%gs%x00%gd"
			    : "--pretty=format:commit %m %H %P%x00%an <%ae> %ad%x00%cn <%ce> %cd%x00%gs%x00%gd",
		"--parents", NULL
	};

	main_done(view);
	view_column_reset(view);
	state->is_reflog = true;
	state->with_graph = false;

	if (!begin_update(view, NULL, reflog_argv, flags))
		return error("Failed to open reflog view");

	return SUCCESS;
}

static bool
reflog_read(struct view *view, char *line, size_t len)
{
	struct main_state *state = view->private;
	struct commit *commit = &state->current;

	if (!line)
		return true;

	if (!prefixcmp(line, "commit ")) {
		char *fields[5] = {0};
		char *pos = line + STRING_SIZE("commit ");
		char *end = line + len;
		int n = 0;
		char *ids;

		while (*pos && !isalnum((unsigned char) *pos))
			pos++;
		ids = pos;
		{
			char *p = pos + strlen(pos) + 1;

			while (p < end && n < 5) {
				fields[n++] = p;
				p += strlen(p) + 1;
			}
		}

		memset(commit, 0, sizeof(*commit));
		string_copy_rev(commit->id, ids);
		if (fields[0])
			parse_author_line(fields[0], &commit->author, &commit->time);
		if (fields[1])
			parse_author_line(fields[1], &commit->committer, &commit->ctime);

		state->reflog = xrealloc(state->reflog, sizeof(*state->reflog) * (state->reflogs + 1));
		state->reflog[state->reflogs++] = xstrdup(fields[3] ? fields[3] : "");

		main_add_commit(view, LINE_MAIN_COMMIT, commit, fields[2] ? fields[2] : "", false);
	}
	return true;
}

static enum request
reflog_request(struct view *view, enum request request, struct line *line)
{
	switch (request) {
	case REQ_REFRESH:
		load_refs(true);
		refresh_view(view);
		return REQ_NONE;
	default:
		return main_request(view, request, line);
	}
}

static void
reflog_select(struct view *view, struct line *line)
{
	struct commit *commit = line->data;
	struct main_state *state = view->private;

	if (state->reflogs && line->lineno > 0 && line->lineno <= state->reflogs)
		string_copy(view->ref, state->reflog[line->lineno - 1]);
	else
		string_copy_rev(view->ref, commit->id);
	string_copy_rev(view->env->commit, commit->id);
	{
		const struct ref *ref;

		view->env->branch[0] = 0;
		for (ref = get_ref_list(commit->id); ref; ref = ref->next)
			if (ref->type == REFERENCE_HEAD || ref->type == REFERENCE_BRANCH) {
				string_copy(view->env->branch, ref->name);
				break;
			}
	}
}

