void
add_pager_refs(struct view *view, const char *commit_id)
{
	char buf[SIZEOF_STR];
	char id[SIZEOF_REV];
	const struct ref *list;
	size_t bufpos = 0;
	const char *sep = "Refs: ";

	string_copy_rev(id, commit_id);
