/* ------------------------------------------------------------------ */
/* Diff common */

static unsigned int
chunk_header_marker_length(const char *data)
{
	int len = 0;

	for (; *data == '@'; data++)
		len++;
	return len;
}

static void
box_add_cell(struct box *box, line_type_t type, size_t length)
{
	if (!length)
		return;
	if (box->cells && box->cell[box->cells - 1].type == type) {
		box->cell[box->cells - 1].length += length;
		return;
	}
	box->cell[box->cells].type = type;
	box->cell[box->cells].length = length;
	box->cells++;
}

bool
diff_common_add_diff_stat(struct view *view, const char *text, size_t offset)
{
	const char *start = text + offset;
	const char *data = start + strspn(start, " ");
	size_t len = strlen(data);
	const char *pipe = strchr(data, '|');
	size_t textlen = strlen(text);

	/* Ensure that '|' is present and the file name part contains
	 * non-space characters. */
	if (!pipe || pipe == data || strcspn(data, " ") == 0 || !len)
		return false;

	if ((data[len - 1] == '-' || data[len - 1] == '+') ||
	    strstr(pipe, " 0") ||
	    strstr(pipe, "Bin") ||
	    strstr(pipe, "Unmerged") ||
	    (data[len - 1] == '0' && (strstr(data, "=>") || !prefixcmp(data, "...")))) {
		size_t size = sizeof(struct box) + 16 * sizeof(struct box_cell) + textlen + 1;
		struct line *line = add_line(view, NULL, LINE_DIFF_STAT, size, false);
		struct box *box;
		char *box_text_ptr;
		const char *pos;

		if (!line)
			return false;

		box = line->data;
		box_text_ptr = (char *) &box->cell[16];
		memcpy(box_text_ptr, text, textlen + 1);
		box->text = box_text_ptr;
		box->cells = 0;

		box_add_cell(box, LINE_DIFF_STAT, pipe - text);
		pos = pipe;

		if (strstr(pipe, "Bin")) {
			const char *bin = strstr(pipe, "Bin");
			const char *arrow = strstr(bin, "->");
			const char *bytes = arrow ? strstr(arrow, "bytes") : NULL;

			box_add_cell(box, LINE_DEFAULT, bin - pos);
			box->cell[box->cells].type = LINE_DEFAULT;
			box->cell[box->cells].length = 3;
			box->cells++;
			pos = bin + 3;
			if (arrow && bytes) {
				box->cell[box->cells].type = LINE_DIFF_DEL;
				box->cell[box->cells].length = arrow - pos;
				box->cells++;
				box->cell[box->cells].type = LINE_DEFAULT;
				box->cell[box->cells].length = 2;
				box->cells++;
				pos = arrow + 2;
				box->cell[box->cells].type = LINE_DIFF_ADD;
				box->cell[box->cells].length = bytes - pos;
				box->cells++;
				pos = bytes;
			}
			if (*pos) {
				box->cell[box->cells].type = LINE_DEFAULT;
				box->cell[box->cells].length = strlen(pos);
				box->cells++;
			}
		} else {
			const char *signs = pos + 1 + strcspn(pos + 1, "+-");

			box_add_cell(box, LINE_DEFAULT, signs - pos);
			pos = signs;
			while (*pos) {
				size_t n;

				if (*pos == '+') {
					n = strspn(pos, "+");
					box->cell[box->cells].type = LINE_DIFF_ADD;
				} else if (*pos == '-') {
					n = strspn(pos, "-");
					box->cell[box->cells].type = LINE_DIFF_DEL;
				} else {
					n = strcspn(pos, "+-");
					box->cell[box->cells].type = LINE_DEFAULT;
				}
				box->cell[box->cells].length = n;
				box->cells++;
				pos += n;
				if (box->cells >= 15)
					break;
			}
		}

		return true;
	}

	return false;
}

bool
diff_common_read(struct view *view, const char *data, struct diff_state *state)
{
	line_type_t type = get_line_type(data);

	/* ADD2 and DEL2 are only valid in combined diff hunks */
	if (!state->combined_diff && (type == LINE_DIFF_ADD2 || type == LINE_DIFF_DEL2))
		type = LINE_DEFAULT;

	/* DEL_FILE, ADD_FILE and START are only valid outside diff chunks */
	if (state->reading_diff_chunk) {
		if (type == LINE_DIFF_DEL_FILE || type == LINE_DIFF_START)
			type = LINE_DIFF_DEL;
		else if (type == LINE_DIFF_ADD_FILE)
			type = LINE_DIFF_ADD;
	}

	if (!view->lines && type != LINE_COMMIT)
		state->reading_diff_stat = true;

	if (state->reading_diff_stat) {
		if (diff_common_add_diff_stat(view, data, 0))
			return true;
		state->reading_diff_stat = false;

	} else if (!strcmp(data, "---")) {
		state->reading_diff_stat = true;

	} else if (!state->after_diff && !state->reading_diff_chunk &&
		   data[0] == ' ' && data[1] != ' ' && strchr(data, '|') &&
		   state->after_commit_title) {
		if (diff_common_add_diff_stat(view, data, 0)) {
			state->reading_diff_stat = true;
			return true;
		}
	}

	if (!state->after_commit_title && !prefixcmp(data, "    ")) {
		struct line *line = add_line_text(view, data, LINE_DEFAULT);

		if (line)
			line->commit_title = 1;
		state->after_commit_title = true;
		return line != NULL;
	}

	if (type == LINE_DIFF_HEADER) {
		state->after_diff = true;
		state->reading_diff_chunk = false;

	} else if (type == LINE_DIFF_CHUNK) {
		const unsigned int len = chunk_header_marker_length(data);
		const char *context = strstr(data + len, "@@");
		struct line *line =
			context ? add_line_text_at(view, view->lines, data, LINE_DIFF_CHUNK, len)
				: NULL;
		struct box *box;

		if (!line)
			return pager_common_read(view, data, type, NULL);

		box = line->data;
		box->cell[0].length = (context + len) - data;
		box->cell[1].length = strlen(context + len);
		box->cell[box->cells++].type = LINE_DIFF_STAT;
		state->combined_diff = data[2] == '@';
		state->reading_diff_chunk = true;
		return true;

	} else if (type == LINE_COMMIT) {
		state->reading_diff_chunk = false;
		state->after_commit_title = false;
		state->after_diff = false;
	}

	return pager_common_read(view, data, type, NULL);
}

static struct line *
find_next_line_by_type_from(struct view *view, struct line *line, line_type_t type)
{
	for (line++; view_has_line(view, line); line++)
		if (line->type == type)
			return line;
	return NULL;
}

const char *
diff_get_pathname(struct view *view, struct line *line, bool old)
{
	struct line *header;
	const char *prefixes[] = { "diff --cc ", "diff --combined " };
	const char *name;
	size_t i;

	header = find_prev_line_by_type(view, line, LINE_DIFF_HEADER);
	if (!header)
		return NULL;

	for (i = 0; i < ARRAY_SIZE(prefixes); i++) {
		const char *dst = strstr(box_text(header), prefixes[i]);

		if (dst)
			return dst + strlen(prefixes[i]);
	}

	header = find_next_line_by_type_from(view, header, old ? LINE_DIFF_DEL_FILE : LINE_DIFF_ADD_FILE);
	if (!header)
		return NULL;

	name = box_text(header) + STRING_SIZE("+++ ");
	if (!opt_diff_noprefix && (!prefixcmp(name, "a/") || !prefixcmp(name, "b/")))
		name += 2;
	return name;
}

unsigned int
diff_get_lineno(struct view *view, struct line *line, bool old)
{
	const struct line *header, *chunk;
	unsigned int lineno;
	unsigned long first, last;

	/* Verify that we are after a diff header and one of its chunks */
	header = find_prev_line_by_type(view, line, LINE_DIFF_HEADER);
	chunk = find_prev_line_by_type(view, line, LINE_DIFF_CHUNK);
	if (!header || !chunk || chunk < header)
		return 0;

	{
		const char *text = box_text(chunk);
		const char *marker = strchr(text, old ? '-' : '+');

		if (!marker)
			return 0;
		first = strtoul(marker + 1, NULL, 10);
		last = first;
	}
	(void) last;

	/* Count the lines from the chunk header */
	lineno = first;
	for (chunk++; chunk < line; chunk++) {
		const char *text = box_text(chunk);

		if (*text != (old ? '+' : '-'))
			lineno++;
	}

	if (lineno == 0)
		lineno = 1;
	return lineno;
}

struct line *
diff_find_header_from_stat(struct view *view, struct line *line)
{
	if (line->type == LINE_DIFF_STAT) {
		int file_number = 0;

		while (view_has_line(view, line) && line->type == LINE_DIFF_STAT) {
			file_number++;
			line--;
		}

		for (line = view->line; view_has_line(view, line); line++) {
			line = find_next_line_by_type(view, line, LINE_DIFF_HEADER);
			if (!line)
				break;

			if (--file_number == 0)
				return line;
		}
	}

	return NULL;
}

enum request
diff_common_enter(struct view *view, enum request request, struct line *line)
{
	if (line->type == LINE_DIFF_STAT) {
		line = diff_find_header_from_stat(view, line);
		if (!line) {
			report("Failed to find file diff");
			return REQ_NONE;
		}

		select_view_line(view, line - view->line);
		report_clear();
		return REQ_NONE;

	} else {
		return pager_request(view, request, line);
	}
}

void
diff_common_select(struct view *view, struct line *line, const char *changes_msg)
{
	if (line->type == LINE_DIFF_STAT) {
		struct line *header = diff_find_header_from_stat(view, line);

		if (header) {
			const char *file = diff_get_pathname(view, header, false);

			if (file) {
				string_format(view->env->file, "%s", file);
				view->env->lineno = view->env->goto_lineno = 0;
				view->env->blob[0] = 0;
			}
		}

		string_format(view->ref, "Press '%s' to jump to file diff",
			      get_keys(view->keymap, REQ_ENTER, false)[0] ? get_keys(view->keymap, REQ_ENTER, false) : get_keys(generic_keymap, REQ_ENTER, false));
	} else {
		const char *file = diff_get_pathname(view, line, false);

		if (file) {
			if (changes_msg)
				string_format(view->ref, "%s to '%s'", changes_msg, file);
			string_format(view->env->file, "%s", file);
			view->env->lineno = view->env->goto_lineno = diff_get_lineno(view, line, false);
			view->env->blob[0] = 0;
		} else {
			string_ncopy(view->ref, view->ops->id, strlen(view->ops->id));
			pager_select(view, line);
		}
	}
}

bool
diff_grep(struct view *view, struct line *line)
{
	const char *text[] = { box_text(line), NULL };

	return grep_text(view, text);
}

/* ------------------------------------------------------------------ */
/* Diff view */

static void
diff_save_line_pos(struct view *view, struct diff_state *state, enum open_flags flags)
{
	if (flags & OPEN_RELOAD) {
		struct line *line = view->lines ? &view->line[view->pos.lineno] : NULL;
		const char *file = line ? diff_get_pathname(view, line, false) : NULL;

		if (file) {
			state->file = xstrdup(file);
			state->lineno = diff_get_lineno(view, line, false);
			state->pos = view->pos;
		}
	}
}

static void
diff_restore_line_pos(struct view *view, struct diff_state *state)
{
	struct line *line = &view->line[view->lines - 1];

	if (!state->file || !view->lines)
		return;

	while ((line = find_prev_line_by_type(view, line, LINE_DIFF_HEADER))) {
		const char *file = diff_get_pathname(view, line, false);

		if (file && !strcmp(file, state->file))
			break;
		line--;
	}

	free((void *) state->file);
	state->file = NULL;

	if (!line)
		return;

	while ((line = find_next_line_by_type(view, line, LINE_DIFF_CHUNK))) {
		unsigned int lineno = diff_get_lineno(view, line, false);

		for (line++; view_has_line(view, line) && line->type != LINE_DIFF_CHUNK; line++) {
			if (lineno == state->lineno) {
				unsigned long lineno = line - view->line;
				unsigned long offset = lineno - (state->pos.lineno - state->pos.offset);

				goto_view_line(view, offset, lineno);
				redraw_view(view);
				return;
			}
			if (*box_text(line) != '-')
				lineno++;
		}
	}
}

static enum status_code
diff_open(struct view *view, enum open_flags flags)
{
	struct diff_state *state = view->private;
	const char *diff_argv[] = {
		"git", "show", "--encoding=UTF-8", "--pretty=fuller", "--root",
			"--patch-with-stat", use_mailmap_arg(),
			show_notes_arg(), diff_context_arg(), ignore_space_arg(),
			"%(diffargs)", "%(cmdlineargs)", word_diff_arg(),
			opt_diff_noprefix ? "--no-prefix" : "",
			"--no-color", "%(commit)", "--", "%(fileargs)", NULL
	};

	diff_save_line_pos(view, state, flags);
	return begin_update(view, NULL, diff_argv, flags) ? SUCCESS : error("Failed to open diff view");
}

static bool
diff_read_describe(struct view *view, char *data, struct diff_state *state)
{
	struct line *line = view->lines ? find_next_line_by_type(view, view->line, LINE_PP_REFS) : NULL;

	(void) state;
	if (data && line) {
		char buf[SIZEOF_STR];
		const char *ref;
		const char *sep;

		string_copy(buf, data);
		ref = string_trim(buf);
		sep = !strcmp("Refs: ", box_text(line)) ? "" : ", ";

		if (*ref && !append_line_format(view, line, "%s%s", sep, ref))
			return false;
	}

	return true;
}

static bool
diff_read(struct view *view, char *data, size_t len)
{
	struct diff_state *state = view->private;

	(void) len;
	if (state->adding_describe_ref)
		return diff_read_describe(view, data, state);

	if (!data) {
		diff_restore_line_pos(view, state);

		if (!state->adding_describe_ref && !ref_list_contains_tag(get_ref_list(view->vid)) &&
		    view->lines && !view->unrefreshable) {
			const char *describe_argv[] = { "git", "describe", view->vid, NULL };
			const char *argv_buf[4];
			int i, j = 0;
			size_t outlen;
			int status;
			char *out;

			for (i = 0; describe_argv[i]; i++)
				if (*describe_argv[i] || i == 0)
					argv_buf[j++] = describe_argv[i];
			argv_buf[j] = NULL;

			out = io_capture(argv_buf, NULL, &outlen, &status, false);
			state->adding_describe_ref = true;
			if (out) {
				char *eol = strchr(out, '\n');

				if (eol)
					*eol = 0;
				if (status == 0)
					diff_read_describe(view, out, state);
				free(out);
			}
		}

		return true;
	}

	return diff_common_read(view, data, state);
}

static enum request
diff_trace_origin(struct view *view, struct line *line)
{
	(void) view;
	(void) line;
	report("Tracing the origin is not supported in this view");
	return REQ_NONE;
}

static enum request
diff_request(struct view *view, enum request request, struct line *line)
{
	switch (request) {
	case REQ_VIEW_BLAME:
		return diff_trace_origin(view, line);

	case REQ_EDIT:
		return diff_common_edit(view, request, line);

	case REQ_ENTER:
		return diff_common_enter(view, request, line);

	case REQ_REFRESH:
		reload_view(view);
		return REQ_NONE;

	default:
		return pager_request(view, request, line);
	}
}

enum request
diff_common_edit(struct view *view, enum request request, struct line *line)
{
	const char *file;
	char path[SIZEOF_STR];
	unsigned int lineno;

	(void) request;
	if (line->type == LINE_DIFF_STAT) {
		file = view->env->file;
		lineno = view->env->lineno;
	} else {
		file = diff_get_pathname(view, line, false);
		lineno = diff_get_lineno(view, line, false);
	}

	if (!file) {
		report("Nothing to edit");
		return REQ_NONE;
	}

	snprintf(path, sizeof(path), "%s%s", repo.cdup, file);
	if (access(path, R_OK)) {
		report("Failed to open file: %s", file);
		return REQ_NONE;
	}

	open_editor(path, lineno);
	return REQ_NONE;
}

static void
diff_select(struct view *view, struct line *line)
{
	diff_common_select(view, line, "Changes");
}

static void
diff_done(struct view *view)
{
	struct diff_state *state = view->private;

	if (state && state->file) {
		free((void *) state->file);
		state->file = NULL;
	}
}

static struct view_ops diff_ops = {
	"line",
	argv_env.commit,
	VIEW_DIFF_LIKE | VIEW_ADD_DESCRIBE_REF | VIEW_ADD_PAGER_REFS | VIEW_FILE_FILTER | VIEW_REFRESH | VIEW_FLEX_WIDTH,
	sizeof(struct diff_state),
	diff_open,
	diff_read,
	pager_draw,
	diff_request,
	diff_grep,
	diff_select,
	diff_done,
	pager_get_column_data,
};

struct view diff_view = {
	"diff",
	&diff_ops,
	NULL,
	&argv_env,
};

void
open_diff_view(struct view *prev, enum open_flags flags)
{
	open_view(prev, &diff_view, flags);
}

/* ------------------------------------------------------------------ */
/* Log view */

struct log_state {
	long last_lineno;
	line_type_t last_type;
	bool commit_title_read;
	bool after_commit_header;
	bool reading_diff_stat;
};

static void
log_copy_rev(struct view *view, struct line *line)
{
	const char *text = box_text(line);
	size_t offset = get_graph_indent_text(text);

	string_copy_rev_from_commit_line(view->ref, text + offset);
	view->vid[0] = 0;
	(void) offset;
}

static void
log_select(struct view *view, struct line *line)
{
	struct log_state *state = view->private;
	long last_lineno = state->last_lineno;

	if (!last_lineno || labs(last_lineno - (long) line->lineno) > 1
	    || (state->last_type == LINE_COMMIT && last_lineno > (long) line->lineno)) {
		struct line *commit_line = find_prev_line_by_type(view, line, LINE_COMMIT);

		if (commit_line)
			log_copy_rev(view, commit_line);
	}

	if (line->type == LINE_COMMIT && !view_has_flags(view, VIEW_NO_REF))
		log_copy_rev(view, line);
	string_copy_rev(view->env->commit, view->ref);
	state->last_lineno = line->lineno;
	state->last_type = line->type;
}

static enum status_code
log_open(struct view *view, enum open_flags flags)
{
	const char *log_argv[] = {
		"git", "log", "--encoding=UTF-8", "--no-color", "--cc", "--stat", use_mailmap_arg(),
			"%(logargs)", "%(cmdlineargs)", "%(revargs)", "--no-color",
			"--", "%(fileargs)", NULL
	};

	if (opt_log_options && opt_log_options[0]) {
		log_argv[4] = "";
		log_argv[5] = "";
	}
	if (!opt_rev_filter)
		log_argv[9] = "";

	return begin_update(view, NULL, log_argv, flags) ? SUCCESS : error("Failed to open log view");
}

static enum request
log_request(struct view *view, enum request request, struct line *line)
{
	switch (request) {
	case REQ_REFRESH:
		load_refs(true);
		refresh_view(view);
		return REQ_NONE;

	case REQ_ENTER:
		if (!display[1] || strcmp(display[1]->vid, view->ref)) {
			string_copy_rev(view->env->commit, view->ref);
			open_diff_view(view, OPEN_SPLIT);
		}
		return REQ_NONE;

	default:
		return request;
	}
}

static bool
log_read(struct view *view, char *data, size_t len)
{
	struct log_state *state = view->private;
	line_type_t type;
	struct line *line;

	(void) len;
	if (!data)
		return true;

	type = get_line_type(data);

	if (type == LINE_COMMIT) {
		state->commit_title_read = true;
		state->reading_diff_stat = false;
	} else if (state->commit_title_read && !prefixcmp(data, "    ")) {
		line = add_line_text(view, data, LINE_DEFAULT);
		if (line)
			line->commit_title = 1;
		state->commit_title_read = false;
		return line != NULL;
	}

	if (!strcmp(data, "---"))
		state->reading_diff_stat = true;

	if (type != LINE_COMMIT && data[0] == ' ' && data[1] != ' ' && strchr(data, '|')) {
		if (diff_common_add_diff_stat(view, data, 0))
			return true;
	}

	return pager_common_read(view, data, type, NULL);
}

static struct view_ops log_ops = {
	"line",
	argv_env.head,
	VIEW_ADD_PAGER_REFS | VIEW_OPEN_DIFF | VIEW_SEND_CHILD_ENTER | VIEW_LOG_LIKE | VIEW_REFRESH | VIEW_FLEX_WIDTH,
	sizeof(struct log_state),
	log_open,
	log_read,
	pager_draw,
	log_request,
	pager_grep,
	log_select,
	NULL,
	pager_get_column_data,
};

struct view log_view = {
	"log",
	&log_ops,
	NULL,
	&argv_env,
};

void
open_log_view(struct view *prev, enum open_flags flags)
{
	open_view(prev, &log_view, flags);
}
