/* ------------------------------------------------------------------ */
/* Command line */

static int
read_filter_args(char *name, size_t namelen, char *value, size_t valuelen, void *data)
{
	const char ***filter_args = data;

	(void) namelen;
	(void) value;
	(void) valuelen;
	return argv_append(filter_args, name) ? OK : ERR;
}

static bool
filter_rev_parse(const char ***args, const char *arg1, const char *arg2, const char *argv[])
{
	const char *rev_parse_argv[SIZEOF_ARG] = { "git", "rev-parse", arg1, arg2 };
	const char **all_argv = NULL;
	size_t len;
	int status;
	char *out;

	if (!argv_append_array(&all_argv, rev_parse_argv) ||
	    !argv_append_array(&all_argv, argv))
		die("Failed to run rev-parse");

	out = io_capture(all_argv, NULL, &len, &status, false);
	argv_free(all_argv);
	free(all_argv);
	if (!out || status != 0) {
		free(out);
		return false;
	}

	{
		char *pos = out, *end = out + len;

		while (pos < end) {
			char *eol = memchr(pos, '\n', end - pos);

			if (!eol)
				eol = end;
			*eol = 0;
			if (*pos)
				read_filter_args(pos, strlen(pos), (char *) "", 0, args);
			pos = eol + 1;
		}
	}
	free(out);
	return true;
}

static void
filter_options(const char *argv[], bool rev_parse)
{
	const char **flags = NULL;
	int next, flags_pos;

	update_options_from_argv(argv);

	if (!rev_parse) {
		opt_cmdline_args = argv;
		return;
	}

	if (!filter_rev_parse(&opt_file_args, "--no-revs", "--no-flags", argv))
		die("No revisions match the given arguments.");
	if (!filter_rev_parse(&flags, "--flags", "--no-revs", argv))
		die("No revisions match the given arguments.");

	if (flags) {
		for (next = flags_pos = 0; flags && flags[next]; next++) {
			const char *flag = flags[next];

			if (argv_parse_rev_flag(flag))
				argv_append(&opt_rev_args, flag);
			else
				flags[flags_pos++] = flag;
		}

		flags[flags_pos] = NULL;

		opt_cmdline_args = flags;
	}

	if (!filter_rev_parse(&opt_rev_args, "--symbolic", "--revs-only", argv))
		die("No revisions match the given arguments.");
}

static enum request
parse_options(int argc, const char *argv[], bool pager_mode)
{
	enum request request;
	const char *subcommand;
	bool seen_dashdash = false;
	bool rev_parse = true;
	const char **filter_argv = NULL;
	int i;

	request = pager_mode ? REQ_VIEW_PAGER : REQ_VIEW_MAIN;

	/* Options that must come before any subcommand. */
	for (i = 1; i < argc; i++) {
		const char *opt = argv[i];

		if (!strcmp(opt, "-C") && i + 1 < argc) {
			i++;
			if (chdir(argv[i]))
				die("Failed to change directory to %s", argv[i]);
			continue;
		} else if (!strncmp(opt, "-C", 2) && opt[2]) {
			if (chdir(opt + 2))
				die("Failed to change directory to %s", opt + 2);
			continue;
		} else {
			break;
		}
	}

	if (argc <= i)
		return request;

	subcommand = argv[i++];
	if (!strcmp(subcommand, "status")) {
		request = REQ_VIEW_STATUS;

	} else if (!strcmp(subcommand, "blame")) {
		request = REQ_VIEW_BLAME;

	} else if (!strcmp(subcommand, "grep")) {
		request = REQ_VIEW_GREP;
		rev_parse = false;

	} else if (!strcmp(subcommand, "show")) {
		request = REQ_VIEW_DIFF;

	} else if (!strcmp(subcommand, "log")) {
		request = REQ_VIEW_LOG;

	} else if (!strcmp(subcommand, "reflog")) {
		request = REQ_VIEW_REFLOG;

	} else if (!strcmp(subcommand, "stash")) {
		request = REQ_VIEW_STASH;

	} else if (!strcmp(subcommand, "refs")) {
		request = REQ_VIEW_REFS;

	} else {
		subcommand = NULL;
		i--; /* revisit option in loop below */
	}

	for (; i < argc; i++) {
		const char *opt = argv[i];

		if (!seen_dashdash) {
			if (!strcmp(opt, "--")) {
				seen_dashdash = true;
				if (!argv_append(&filter_argv, opt))
					die("command too long");
				continue;

			} else if (!strcmp(opt, "-v") || !strcmp(opt, "--version")) {
				printf("tig version %s\n", TIG_VERSION);
				printf("ncursesw version %s.%d\n", NCURSES_VERSION, NCURSES_VERSION_PATCH);
				exit(EXIT_SUCCESS);

			} else if (!strcmp(opt, "-h") || !strcmp(opt, "--help")) {
				printf("%s\n", usage_string);
				exit(EXIT_SUCCESS);

			} else if (strlen(opt) >= 2 && *opt == '+' && string_isnumber(opt + 1)) {
				int lineno = atoi(opt + 1);

				opt_lineno = lineno;
				continue;
			}
		}

		if (!argv_append(&filter_argv, opt))
			die("command too long");
	}

	if (filter_argv) {
		if (!repo.git_dir[0] && rev_parse && request != REQ_VIEW_PAGER)
			die("No revisions match the given arguments.");
		filter_options(filter_argv, rev_parse);
	}

	/* Finish validating and setting up blame options */
	if (request == REQ_VIEW_BLAME) {
		if (!opt_file_args || opt_file_args[1] || (opt_rev_args && opt_rev_args[1]))
			usage("Invalid number of options to blame");

		if (opt_rev_args) {
			string_ncopy(argv_env.ref, opt_rev_args[0], strlen(opt_rev_args[0]));
		}

		string_ncopy(argv_env.file, opt_file_args[0], strlen(opt_file_args[0]));

	} else if (request == REQ_VIEW_GREP) {
		/* grep arguments are passed as-is */
	}

	(void) subcommand;
	return request;
}

/* ------------------------------------------------------------------ */
/* Editor */

void
open_editor(const char *file, unsigned int lineno)
{
	const char *editor_argv[SIZEOF_ARG + 3] = { "vi", file, NULL };
	char editor_cmd[SIZEOF_STR];
	char lineno_cmd[SIZEOF_STR];
	const char *editor;
	int argc = 0;

	editor = getenv("TIG_EDITOR");
	if (!editor || !*editor)
		editor = getenv("GIT_EDITOR");
	if ((!editor || !*editor) && *git_core_editor)
		editor = git_core_editor;
	if (!editor || !*editor)
		editor = getenv("VISUAL");
	if (!editor || !*editor)
		editor = getenv("EDITOR");
	if (!editor || !*editor)
		editor = "vi";

	string_copy(editor_cmd, editor);
	if (!argv_from_string_no_quotes(editor_argv, &argc, editor_cmd)) {
		report("Failed to read editor command");
		return;
	}

	if (lineno && opt_editor_line_number && string_format(lineno_cmd, "+%u", lineno))
		editor_argv[argc++] = lineno_cmd;
	editor_argv[argc++] = file;
	editor_argv[argc] = NULL;

	{
		const char *sh_argv[] = { "sh", "-c", NULL, NULL };
		char cmd[SIZEOF_MED_STR];
		size_t pos = 0;
		int i;

		/* Let the shell interpret the editor command */
		for (i = 0; editor_argv[i]; i++)
			string_nformat(cmd, sizeof(cmd), &pos, "%s%s", i ? " " : "", editor_argv[i]);
		sh_argv[2] = cmd;
		if (!open_external_viewer(sh_argv, repo.cdup[0] ? repo.cdup : NULL, false, false, false, true, true, ""))
			report("Failed to open editor");
	}
}

/* ------------------------------------------------------------------ */
/* Run requests */

static bool
run_request_confirm(const char **argv)
{
	char *cmd = argv_to_string_alloc(argv, " ");
	char prompt[SIZEOF_STR];

	snprintf(prompt, sizeof(prompt), "Run `%s`?", cmd);
	return prompt_yesno(prompt);
}

enum request run_prompt_command(struct view *view, const char *argv[]);

static enum request
exec_run_request(struct view *view, struct run_request *req)
{
	const char **argv = NULL;
	bool confirmed = false;
	enum request request = REQ_NONE;
	char cmd[SIZEOF_MED_STR];
	const char *req_argv[SIZEOF_ARG];
	int req_argc = 0;

	if (!argv_to_string_alloc(req->argv, " ") ||
	    !string_format(cmd, "%s", argv_to_string_alloc(req->argv, " ")) ||
	    !argv_from_string_no_quotes(req_argv, &req_argc, cmd) ||
	    !argv_format(view->env, &argv, req_argv, false, true)) {
		report("Failed to format arguments");
		return REQ_NONE;
	}

	if (req->flags.internal) {
		request = run_prompt_command(view, argv);

	} else {
		confirmed = !req->flags.confirm;

		if (req->flags.confirm) {
			confirmed = run_request_confirm(argv);
		}

		if (confirmed) {
			bool ok;

			argv_remove_quotes_in_place:
			{
				int i;

				for (i = 0; argv[i]; i++) {
					char *arg = (char *) argv[i];
					size_t len = strlen(arg);

					if (len >= 2 && (arg[0] == '"' || arg[0] == '\'') && arg[len - 1] == arg[0]) {
						memmove(arg, arg + 1, len - 2);
						arg[len - 2] = 0;
					}
				}
			}

			ok = open_external_viewer(argv, NULL, req->flags.silent,
						  !req->flags.exit, req->flags.echo, req->flags.quick,
						  false, "");

			if (req->flags.exit)
				request = REQ_QUIT;
			else if (ok || true) {
				struct view *v;
				int i;

				load_refs(true);
				foreach_displayed_view (v, i) {
					if (view_can_refresh(v))
						refresh_view(v);
				}
			}
		}
	}

	argv_free(argv);
	free(argv);

	return request;
}

static enum request
open_run_request(struct view *view, enum request request)
{
	struct run_request *req = get_run_request(request);

	if (!req) {
		report("Unknown run request");
		return REQ_NONE;
	}

	return exec_run_request(view, req);
}

