int
get_toggle_menu_items(const char ***keys, const char ***names, const char ***helps)
{
	static const char *k[32], *n[32], *h[32];
	static char keybufs[32][2];
	static char helpbufs[32][64];
	int i;

	for (i = 0; toggle_menu_items[i].text; i++) {
		keybufs[i][0] = toggle_menu_items[i].hotkey;
		keybufs[i][1] = 0;
		k[i] = keybufs[i];
