static enum request toggle_and_report(struct view *view, const char *option, const char *arg);

static void
open_option_menu(struct view *view)
{
	static int selected = 0;

	if (prompt_menu("Toggle option", toggle_menu_items, &selected)) {
		toggle_and_report(view, toggle_menu_items[selected].data, NULL);
	}
}

/* ------------------------------------------------------------------ */
/* Prompt commands */

extern enum status_code toggle_option_full(struct view *view, const char *option, const char *arg,
					   char *msg, size_t msgsize, enum view_flag *flags);
extern enum status_code execute_option_argv(int argc, const char *argv[]);
extern void sort_view_request(struct view *view, bool change_field, char *msg, size_t msgsize);

static void
reload_affected_views(enum view_flag flags)
{
	struct view *view;
	int i;

	foreach_displayed_view (view, i) {
		if (flags && view_has_flags(view, flags) && view->lines) {
			reload_view(view);
		}
	}
}

static enum request
toggle_and_report(struct view *view, const char *option, const char *arg)
{
	char msg[SIZEOF_STR];
	enum view_flag flags = 0;
	enum status_code code = toggle_option_full(view, option, arg, msg, sizeof(msg), &flags);

	if (code != SUCCESS) {
		const char *message = get_status_message(code);

		if (!prefixcmp(message, "SORT:")) {
			sort_view_request(view, !strcmp(message + 5, "sort-field"), msg, sizeof(msg));
			report("%s", msg);
			return REQ_NONE;
		}
		report("%s", message);
		return REQ_NONE;
	}

	/* Some toggles change how views are loaded */
	if (!strcmp(option, "commit-title-graph")) {
		struct view_config *cfg = find_view_config(view->name);
		int c;

		for (c = 0; cfg && c < cfg->count; c++)
			if (cfg->types[c] == VIEW_COLUMN_COMMIT_TITLE &&
			    (cfg->opts[c].graph == GRAPH_DISPLAY_NO || cfg->opts[c].graph == GRAPH_DISPLAY_V2) &&
			    opt_commit_order == COMMIT_ORDER_AUTO)
				flags |= VIEW_LOG_LIKE;
		if (flags & VIEW_LOG_LIKE) {
			if (view->lines && view_has_flags(view, VIEW_LOG_LIKE))
				reload_view(view);
			flags = 0;
		}
	}

	if (!strcmp(option, "line-graphics") || !strcmp(option, "vertical-split") ||
	    !strcmp(option, "split-view-height") || !strcmp(option, "split-view-width")) {
		resize_display();
	}

	if (flags)
		reload_affected_views(flags);

	redraw_display(false);
	report("%s", msg);
	return REQ_NONE;
}

static bool
save_view(struct view *view, const char *path)
{
	FILE *file = fopen(path, "w");
	size_t i;

	if (!file)
		return false;

	fprintf(file, "View: %s\n", view->name);
	if (view->prev && view->prev != view)
		fprintf(file, "Prev: %s\n", view->prev->name);
	if (view->parent && view->parent != view)
		fprintf(file, "Parent: %s\n", view->parent->name);
	fprintf(file, "Ref: %s\n", view->ref);
	fprintf(file, "Dimensions: height=%d width=%d\n", view->height, view->width);
	fprintf(file, "Position: offset=%ld column=%ld lineno=%ld\n",
		view->pos.offset, view->pos.col, view->pos.lineno);

	for (i = 0; i < view->lines; i++) {
		struct view_column_data column_data = {0};
		struct line *line = &view->line[i];

		fprintf(file, "line[%3zu] type=%s selected=%d\n",
			i, line_type_name(line->type), line->selected);

		if (!view->ops->get_column_data(view, line, &column_data))
			continue;

		if (column_data.box) {
			const struct box *box = column_data.box;
			size_t j;
			size_t offset;

			fprintf(file, "line[%3zu] cells=%zu text=", i, box->cells);

			for (j = 0, offset = 0; j < box->cells; j++) {
				const struct box_cell *cell = &box->cell[j];

				fprintf(file, "[%.*s]", (int) cell->length, box->text + offset);
				offset += cell->length;
			}

			fprintf(file, "\n");
		}
	}

	fclose(file);
	return true;
}

static enum request
goto_commit(struct view *view, const char *rev)
{
	const char *rev_parse_argv[] = { "git", "rev-parse", "--revs-only", rev, NULL };
	char id[SIZEOF_STR];
	size_t lineno;

	if (!view_has_flags(view, VIEW_HAS_ID)) {
		report("Jumping to commits is not supported by the %s view", view->name);
		return REQ_NONE;
	}

	if (!io_run_buf(rev_parse_argv, id, sizeof(id), NULL, false) || !iscommit(id)) {
		report("Failed to parse '%s'", rev);
		return REQ_NONE;
	}

	for (lineno = 0; lineno < view->lines; lineno++) {
		struct view_column_data column_data = {0};
		struct line *line = &view->line[lineno];

		if (view->ops->get_column_data(view, line, &column_data) &&
		    column_data.id && !strncmp(column_data.id, id, SIZEOF_REV - 1)) {
			select_view_line(view, lineno);
			report_clear();
			return REQ_NONE;
		}
	}

	report("Unable to find commit '%s'", rev);
	return REQ_NONE;
}

enum request
run_prompt_command(struct view *view, const char *argv[])
{
	enum request request;
	const char *cmd = argv[0];
	size_t cmdlen = cmd ? strlen(cmd) : 0;

	if (!cmd)
		return REQ_NONE;

	if (string_isnumber(cmd)) {
		int lineno = view->pos.lineno + 1;

		if (parse_int(&lineno, cmd, 0, view->lines + 1) == SUCCESS) {
			if (!lineno)
				lineno = 1;
			select_view_line(view, lineno - 1);
			report_clear();
		} else {
			report("Unable to parse '%s' as a line number", cmd);
		}

	} else if (iscommit(cmd)) {
		size_t lineno;

		if (!view_has_flags(view, VIEW_HAS_ID)) {
			report("Jumping to commits is not supported by the %s view", view->name);
			return REQ_NONE;
		}

		for (lineno = 0; lineno < view->lines; lineno++) {
			struct view_column_data column_data = {0};
			struct line *line = &view->line[lineno];

			if (view->ops->get_column_data(view, line, &column_data) &&
			    column_data.id &&
			    !strncasecmp(column_data.id, cmd, cmdlen)) {
				string_ncopy(view->env->search, cmd, cmdlen);
				select_view_line(view, lineno);
				report_clear();
				return REQ_NONE;
			}
		}

		string_ncopy(view->env->search, cmd, cmdlen);
		report("Unable to find commit '%s'", view->env->search);
		return REQ_NONE;

	} else if (cmdlen > 1 && (cmd[0] == '/' || cmd[0] == '?')) {
		char search[SIZEOF_STR];
		char *joined = argv_to_string_alloc(argv, " ");

		string_copy(search, joined);
		string_copy(view->env->search, search + 1);
		setup_and_find_next(view, cmd[0] == '/' ? REQ_FIND_NEXT : REQ_FIND_PREV);
		return REQ_NONE;

	} else if (cmdlen > 1 && cmd[0] == '!') {
		struct view *next = &pager_view;
		const char **fmt_argv = NULL;
		const char *copy[SIZEOF_ARG];
		int i;

		for (i = 0; argv[i] && i < SIZEOF_ARG - 1; i++)
			copy[i] = argv[i];
		copy[i] = NULL;
		copy[0] = cmd + 1;

		if (!argv_format(view->env, &fmt_argv, copy, false, true)) {
			report("Argument formatting failed");
		} else {
			char *title = argv_to_string_alloc(fmt_argv, " ");

			argv_free(next->argv);
			free(next->argv);
			next->argv = fmt_argv;
			string_copy(next->ref, title);
			next->dir = NULL;
			open_pager_view(view, OPEN_PREPARED | OPEN_WITH_STDERR);
		}

	} else if (!strcmp(cmd, "save-display")) {
		const char *path = argv[1] ? argv[1] : "tig-display.txt";

		if (!save_display(path))
			report("Failed to save screen to %s", path);
		else
			report("Saved screen to %s", path);

	} else if (!strcmp(cmd, "save-options")) {
		const char *path = argv[1] ? argv[1] : "tig-options.txt";

		if (!save_options(path))
			report("Failed to save options: %s", strerror(errno));
		else
			report("Saved options to %s", path);

	} else if (!strcmp(cmd, "save-view")) {
		const char *path = argv[1] ? argv[1] : "tig-view.txt";

		if (!save_view(view, path))
			report("Failed to save view: %s", strerror(errno));
		else
			report("Saved view to %s", path);

	} else if (!strcmp(cmd, "exec")) {
		struct run_request req = { view->keymap, {0}, argv + 1 };
		const char *first = argv[1];
		enum status_code code;

		if (!argv[1]) {
			report("No command given to exec");
			return REQ_NONE;
		}
		code = parse_run_request_flags(&req.flags, argv + 1);
		if (code != SUCCESS) {
			report("Failed to execute command: %s", get_status_message(code));
		} else {
			request = exec_run_request(view, &req);
			argv[1] = first;
			return request;
		}
		argv[1] = first;

	} else if (!strcmp(cmd, "echo")) {
		const char **fmt_argv = NULL;
		char text[SIZEOF_STR] = "";

		if (argv[1] && strlen(argv[1]) > 0) {
			if (!argv_format(view->env, &fmt_argv, &argv[1], false, true)) {
				report("Failed to format echo string");
				return REQ_NONE;
			}
			string_copy(text, argv_to_string_alloc(fmt_argv, " "));
			argv_free(fmt_argv);
			free(fmt_argv);
		}

		report("%s", text);
		return REQ_NONE;

	} else if (!strcmp(cmd, "script")) {
		if (!argv[1] || !open_script(argv[1]))
			report("Failed to open script %s", argv[1] ? argv[1] : "");
		return REQ_NONE;

	} else if (!strcmp(cmd, "goto")) {
		if (!argv[1]) {
			report("goto requires an argument");
			return REQ_NONE;
		}
		{
			const char **fmt_argv = NULL;

			if (!argv_format(view->env, &fmt_argv, &argv[1], false, true) || !fmt_argv[0]) {
				report("Failed to format goto argument");
				return REQ_NONE;
			}
			request = goto_commit(view, fmt_argv[0]);
			argv_free(fmt_argv);
			free(fmt_argv);
			return request;
		}

	} else if (!strcmp(cmd, "toggle")) {
		return toggle_and_report(view, argv[1], argv[1] ? argv[2] : NULL);

	} else {
		struct key key = {0};
		enum status_code code;
		const char *keyname = cmd;

		/* Try :<key> */
		if (get_key_value(&keyname, &key) == SUCCESS && !*keyname) {
			request = get_keybinding(view->keymap, &key, 1, NULL);
			if (request != REQ_UNKNOWN)
				return request;
		}

		/* Try :<command> */
		request = get_request(cmd);
		if (request != REQ_UNKNOWN)
			return request;

		code = execute_option_argv(argv_size(argv), argv);
		if (code != SUCCESS) {
			report("%s", get_status_message(code));
			return REQ_NONE;
		}

		if (!strcmp(cmd, "color"))
			init_colors();
		resize_display();
		{
			struct view *v;
			int i;

			foreach_displayed_view (v, i) {
				if (v->lines && (v->ops->flags & (VIEW_DIFF_LIKE | VIEW_LOG_LIKE)) &&
				    !strcmp(cmd, "set") && argv[1] &&
				    (strstr(argv[1], "options") || !strcmp(argv[1], "diff-context") ||
				     !strcmp(argv[1], "ignore-space") || !strcmp(argv[1], "commit-order") ||
				     !strcmp(argv[1], "show-changes") || !strcmp(argv[1], "word-diff")))
					reload_view(v);
			}
		}
		redraw_display(true);
		report_clear();
	}
	return REQ_NONE;
}

static enum request
run_prompt(struct view *view, const char *prompt)
{
	char *cmd = read_prompt(prompt);
	const char *argv[SIZEOF_ARG] = { NULL };
	int argc = 0;
	char buf[SIZEOF_STR];

	if (!cmd)
		return REQ_NONE;

	if (*cmd == '!') {
		/* Keep quotes for shell-like commands */
		string_copy(buf, cmd);
		if (!argv_from_string_no_quotes(argv, &argc, buf)) {
			report("Too many arguments");
			return REQ_NONE;
		}
		return run_prompt_command(view, argv);
	}

	string_copy(buf, cmd);
	if (!argv_from_string(argv, &argc, buf)) {
		report("Too many arguments");
		return REQ_NONE;
	}

	return run_prompt_command(view, argv);
}

/* ------------------------------------------------------------------ */
/* Request driver */

static bool
forward_request_to_child(struct view *child, enum request request)
{
	return displayed_views() == 2 && view_is_displayed(child) &&
		!strcmp(child->vid, child->ops->id);
	(void) request;
}

static enum request
view_request(struct view *view, enum request request)
{
	if (!view || !view->lines)
		return request;

	if (request == REQ_ENTER && !opt_focus_child && opt_send_child_enter &&
	    view_has_flags(view, VIEW_SEND_CHILD_ENTER)) {
		struct view *child = display[1];

		if (forward_request_to_child(child, request)) {
			view_request(child, request);
			return REQ_NONE;
		}
	}

	if (request == REQ_REFRESH && !view_can_refresh(view)) {
		report("This view can not be refreshed");
		return REQ_NONE;
	}

	return view->ops->request(view, request, &view->line[view->pos.lineno]);
}

static const char *
get_view_key(struct view *view, enum request request)
{
	const char *key = get_keys(view->keymap, request, false);

	if (!*key)
		key = get_keys(generic_keymap, request, false);
	return *key ? key : "(no key)";
}

static bool
view_driver(struct view *view, enum request request)
{
	int i;

	if (request == REQ_NONE)
		return true;

	if (request >= REQ_RUN_REQUESTS) {
		request = open_run_request(view, request);

		if (request == REQ_QUIT)
			return false;
	}

	request = view_request(view, request);
	if (request == REQ_NONE)
		return true;

	switch (request) {
	case REQ_MOVE_UP:
	case REQ_MOVE_DOWN:
	case REQ_MOVE_PAGE_UP:
	case REQ_MOVE_PAGE_DOWN:
	case REQ_MOVE_HALF_PAGE_UP:
	case REQ_MOVE_HALF_PAGE_DOWN:
	case REQ_MOVE_FIRST_LINE:
	case REQ_MOVE_LAST_LINE:
	case REQ_MOVE_NEXT_MERGE:
	case REQ_MOVE_PREV_MERGE:
		move_view(view, request);
		break;

	case REQ_SCROLL_FIRST_COL:
	case REQ_SCROLL_LEFT:
	case REQ_SCROLL_RIGHT:
	case REQ_SCROLL_LINE_DOWN:
	case REQ_SCROLL_LINE_UP:
	case REQ_SCROLL_PAGE_DOWN:
	case REQ_SCROLL_PAGE_UP:
	case REQ_SCROLL_HALF_PAGE_DOWN:
	case REQ_SCROLL_HALF_PAGE_UP:
		scroll_view(view, request);
		break;

	case REQ_VIEW_GREP:
		open_grep_view(view);
		break;

	case REQ_VIEW_MAIN:
		open_main_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_DIFF:
		open_diff_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_LOG:
		open_log_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_REFLOG:
		open_reflog_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_TREE:
		open_tree_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_BLOB:
		open_blob_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_BLAME:
		open_blame_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_REFS:
		open_refs_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_HELP:
		open_help_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_PAGER:
		open_pager_view(view, OPEN_DEFAULT);
		break;
	case REQ_VIEW_STAGE:
		open_stage_view(view, NULL, 0, OPEN_DEFAULT);
		break;
	case REQ_VIEW_STATUS:
		open_status_view(view, false, OPEN_DEFAULT);
		break;
	case REQ_VIEW_STASH:
		open_stash_view(view, OPEN_DEFAULT);
		break;

	case REQ_NEXT:
	case REQ_PREVIOUS:
		if (view->parent && view_is_displayed(view->parent)) {
			unsigned long line;

			view = view->parent;
			line = view->pos.lineno;
			view_request(view, request);
			move_view(view, request);
			if (view_is_displayed(view))
				update_view_title(view);
			if (line != view->pos.lineno)
				view_request(view, REQ_ENTER);
		} else {
			move_view(view, request);
		}
		break;

	case REQ_VIEW_NEXT:
	{
		int nviews = displayed_views();
		int next_view = nviews ? (current_view + 1) % nviews : current_view;

		if (next_view == (int) current_view) {
			report("Only one view is displayed");
			break;
		}

		current_view = next_view;
		/* Blur out the title of the previous view. */
		update_view_title(view);
		redraw_display(false);
		report_clear();
		break;
	}
	case REQ_REFRESH:
		report("Refreshing is not supported by the %s view", view->name);
		break;

	case REQ_PARENT:
		report("Moving to parent is not supported by the %s view", view->name);
		break;

	case REQ_BACK:
		report("Going back is not supported by the %s view", view->name);
		break;

	case REQ_MAXIMIZE:
		if (displayed_views() == 2)
			maximize_view(view, true);
		break;

	case REQ_OPTIONS:
		open_option_menu(view);
		break;

	case REQ_SEARCH:
	case REQ_SEARCH_BACK:
		search_view(view, request);
		break;

	case REQ_FIND_NEXT:
	case REQ_FIND_PREV:
		find_next(view, request);
		break;

	case REQ_STOP_LOADING:
		foreach_view(view, i) {
			if (view->pipe)
				report("Stopped loading the %s view", view->name);
			end_update(view, true);
		}
		break;

	case REQ_SHOW_VERSION:
		report("tig-%s", TIG_VERSION);
		return true;

	case REQ_SCREEN_REDRAW:
		redraw_display(true);
		break;

	case REQ_EDIT:
		report("Nothing to edit");
		break;

	case REQ_ENTER:
		report("Nothing to enter");
		break;

	case REQ_VIEW_CLOSE_NO_QUIT:
	case REQ_VIEW_CLOSE:
		/* XXX: Mark closed views by letting view->prev point to the
		 * view itself. Parents to closed view should never be
		 * followed. */
		if (view->prev && view->prev != view) {
			maximize_view(view->prev, true);
			view->prev = view;
			view->parent = NULL;
			break;
		}
		if (request == REQ_VIEW_CLOSE_NO_QUIT) {
			report("Can't close last remaining view");
			break;
		}
		/* fall-through */
	case REQ_QUIT:
		return false;

	case REQ_PROMPT:
		request = run_prompt(view, ":");
		if (request != REQ_NONE)
			return view_driver(display[current_view], request);
		break;

	default:
		report("Unknown key, press %s for help",
		       get_view_key(view, REQ_VIEW_HELP));
		return true;
	}

	return true;
}

/* ------------------------------------------------------------------ */
/* Key combos */

static enum request
read_key_combo(struct keymap *keymap)
{
	struct key key[16];
	size_t keys = 0;
	int matches;
	enum request request;

	while (true) {
		get_input(0, &key[keys]);
		keys++;
		request = get_keybinding(keymap, key, keys, &matches);
		if (request != REQ_UNKNOWN || matches <= 1 || keys >= ARRAY_SIZE(key))
			return request == REQ_UNKNOWN && matches > 0 && keys < ARRAY_SIZE(key) ? REQ_UNKNOWN : request;
	}
}

/* ------------------------------------------------------------------ */
/* Main */

static void
handle_sigint(int sig)
{
	(void) sig;
	done_display();
	exit(1);
}

int
main(int argc, const char *argv[])
{
	const char *codeset = "UTF-8";
	bool pager_mode = !isatty(STDIN_FILENO);
	enum request request;
	struct view *view;
	const char *script;

	signal(SIGPIPE, SIG_IGN);
	setlocale(LC_ALL, "");
	{
		const char *cs = nl_langinfo(CODESET);

		if (cs && *cs)
			codeset = cs;
	}

	if (strcmp(codeset, "UTF-8") && strcmp(codeset, "utf8")) {
		char buf[128];

		snprintf(buf, sizeof(buf), "%s//TRANSLIT", codeset);
		opt_iconv_out = iconv_open(buf, "UTF-8");
	}

	/* Handle -C before loading repository information */
	{
		int i;

		for (i = 1; i < argc; i++) {
			if (!strcmp(argv[i], "-C") && i + 1 < argc) {
				if (chdir(argv[i + 1]))
					die("Failed to change directory to %s", argv[i + 1]);
				i++;
				continue;
			}
			if (!strncmp(argv[i], "-C", 2) && argv[i][2]) {
				if (chdir(argv[i] + 2))
					die("Failed to change directory to %s", argv[i] + 2);
				continue;
			}
			if (!strcmp(argv[i], "-v") || !strcmp(argv[i], "--version") ||
			    !strcmp(argv[i], "-h") || !strcmp(argv[i], "--help"))
				break;
			break;
		}
	}

	/* Version and help do not need a repository */
	{
		int i;

		for (i = 1; i < argc; i++) {
			if (!strcmp(argv[i], "--"))
				break;
			if (!strcmp(argv[i], "-v") || !strcmp(argv[i], "--version")) {
				printf("tig version %s\n", TIG_VERSION);
				printf("ncursesw version %s.%d\n", NCURSES_VERSION, NCURSES_VERSION_PATCH);
				return 0;
			}
			if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
				printf("%s\n", usage_string);
				return 0;
			}
		}
	}

	load_repo_info();
	load_options();
	if (repo.git_dir[0])
		load_git_config();

	{
		const char **argv_copy = xcalloc(argc + 1, sizeof(*argv_copy));
		int i, j = 0;
		bool skip_c = true;

		argv_copy[j++] = argv[0];
		for (i = 1; i < argc; i++) {
			if (skip_c && !strcmp(argv[i], "-C") && i + 1 < argc) {
				i++;
				continue;
			}
			if (skip_c && !strncmp(argv[i], "-C", 2) && argv[i][2])
				continue;
			skip_c = false;
			argv_copy[j++] = argv[i];
		}
		argv_copy[j] = NULL;
		request = parse_options(j, argv_copy, pager_mode);
	}

	if (pager_mode && request != REQ_VIEW_PAGER && !argv_contains(opt_rev_args, "--stdin")) {
		/* Commands such as `git show | tig show` still use pager mode */
	}

	if (!repo.git_dir[0] && request != REQ_VIEW_PAGER)
		die("Not a git repository");

	if (repo.git_dir[0])
		load_refs(false);

	init_display();
	signal(SIGINT, handle_sigint);

	script = getenv("TIG_SCRIPT");
	if (script) {
		if (!open_script(script))
			die("Failed to open script %s", script);
	}

	{
		struct view *v;
		int i;

		foreach_view (v, i) {
			v->keymap = get_keymap(v->name, strlen(v->name));
		}
	}

	if (request == REQ_VIEW_PAGER || (pager_mode && request == REQ_VIEW_MAIN && !argv_contains(opt_rev_args, "--stdin"))) {
		if (pager_mode) {
			open_pager_view(NULL, OPEN_STDIN);
		} else {
			die("No pager content");
		}
		request = REQ_NONE;
	} else if (request == REQ_VIEW_DIFF && pager_mode) {
		open_pager_view(NULL, OPEN_STDIN);
		request = REQ_NONE;
	}

	view = display[current_view];
	if (request != REQ_NONE) {
		view_driver(NULL ? NULL : &main_view, request == REQ_VIEW_MAIN ? REQ_NONE : REQ_NONE);
		switch (request) {
		case REQ_VIEW_MAIN: open_main_view(NULL, OPEN_DEFAULT); break;
		case REQ_VIEW_DIFF: open_diff_view(NULL, OPEN_DEFAULT); break;
		case REQ_VIEW_LOG: open_log_view(NULL, OPEN_DEFAULT); break;
		case REQ_VIEW_REFLOG: open_reflog_view(NULL, OPEN_DEFAULT); break;
		case REQ_VIEW_BLAME: open_blame_view(NULL, OPEN_DEFAULT); break;
		case REQ_VIEW_REFS: open_refs_view(NULL, OPEN_DEFAULT); break;
		case REQ_VIEW_STATUS: open_status_view(NULL, false, OPEN_DEFAULT); break;
		case REQ_VIEW_STASH: open_stash_view(NULL, OPEN_DEFAULT); break;
		case REQ_VIEW_GREP: open_grep_view(NULL); break;
		default: open_main_view(NULL, OPEN_DEFAULT); break;
		}
	}

	if (!display[current_view])
		die("No view to display");

	while (true) {
		view = display[current_view];
		update_all_titles();
		request = read_key_combo(view->keymap);
		if (!view_driver(display[current_view], request))
			break;
	}

	done_display();
	return 0;
}
