/* Help view */
#include "tigview.h"

enum help_type {
	HELP_HEADER,
	HELP_TOGGLE_ALL,
	HELP_BLANK,
	HELP_SECTION,
	HELP_GROUP,
	HELP_REQUEST,
	HELP_RUN_REQUEST,
	HELP_TOGGLE,
};

struct help {
	enum help_type type;
	struct keymap *keymap;
	enum request request;
	const char *text;
	const char *name;
	const char *key;
};

struct help_state {
	int keys_width;
	int name_width;
};

extern int get_toggle_menu_items(const char ***keys, const char ***names, const char ***helps);

static bool help_all_collapsed;

static bool
help_keymap_has_bindings(struct keymap *keymap)
{
	return keymap->size > 0;
}

static void
help_add(struct view *view, enum help_type type, line_type_t ltype, struct keymap *keymap,
	 enum request request, const char *text, const char *name, const char *key)
{
	struct help *help;
	struct line *line = add_line_alloc(view, &help, ltype, 0, false);

	if (!line)
		return;
	help->type = type;
	help->keymap = keymap;
	help->request = request;
	help->text = text;
	help->name = name;
	help->key = key ? xstrdup(key) : NULL;
}

static void
help_update_widths(struct help_state *state, const char *key, const char *name)
{
	int keylen = key ? utf8_width(key) : 0;
	int namelen = name ? utf8_width(name) : 0;

	if (keylen > state->keys_width)
		state->keys_width = keylen;
	if (namelen > state->name_width)
		state->name_width = namelen;
}

static void
help_keymap_lines(struct view *view, struct help_state *state, struct keymap *keymap, bool add)
{
	const char *group = NULL;
	const char *last_group = NULL;
	int r, i, g;

	for (r = 0; r < req_info_count; r++) {
		const struct request_info *info = &req_info[r];
		const char *key;

		if (info->group)
			group = info->group;

		key = get_keys(keymap, info->request, true);
		if (!*key)
			continue;

		help_update_widths(state, key, enum_name(info->name));
		if (!add)
			continue;

		if (group != last_group) {
			help_add(view, HELP_GROUP, LINE_HELP_GROUP, keymap, REQ_NONE, group, NULL, NULL);
			last_group = group;
		}
		{
			const char *name = xstrdup(enum_name(info->name));

			help_add(view, HELP_REQUEST, LINE_DEFAULT, keymap, info->request, info->help, name, key);
		}
	}

	for (g = 0; g < 3; g++) {
		static const char *groups[] = { "Option toggling:", "Internal commands:", "External commands:" };
		bool printed = false;

		for (i = 0; i < keymap->size; i++) {
			struct keybinding *kb = &keymap->data[i];
			struct run_request *req = get_run_request(kb->request);
			int kind;
			const char *key;

			if (!req)
				continue;
			kind = !req->flags.internal ? 2 :
			       (req->argv[0] && !strcmp(req->argv[0], "toggle")) ? 0 : 1;
			if (kind != g)
				continue;

			key = get_key_name(kb->key, kb->keys, true);
			help_update_widths(state, key, NULL);
			if (!add)
				continue;
			if (!printed) {
				help_add(view, HELP_GROUP, LINE_HELP_GROUP, keymap, REQ_NONE, groups[g], NULL, NULL);
				printed = true;
			}
			help_add(view, HELP_RUN_REQUEST, LINE_DEFAULT, keymap, kb->request, NULL, NULL, key);
		}
	}
}

static void
help_toggle_lines(struct view *view, struct help_state *state, struct keymap *keymap, bool add)
{
	const char **keys, **names, **helps;
	int n = get_toggle_menu_items(&keys, &names, &helps);
	int i;

	for (i = 0; i < n; i++) {
		help_update_widths(state, keys[i], names[i]);
		if (!add)
			continue;
		if (i == 0)
			help_add(view, HELP_GROUP, LINE_HELP_GROUP, keymap, REQ_NONE, "Toggle keys (enter: o <key>):", NULL, NULL);
		help_add(view, HELP_TOGGLE, LINE_DEFAULT, keymap, REQ_NONE, helps[i], names[i], keys[i]);
	}
}

static bool help_keymaps_initialized;

static void
help_init_collapsed(struct view *prev)
{
	int k;

	for (k = 0; k < get_keymaps_count(); k++) {
		struct keymap *keymap = get_keymap_by_index(k);

		keymap->hidden = !(keymap == generic_keymap || keymap == search_keymap ||
				   keymap == toggle_keymap ||
				   (prev && prev->keymap == keymap));
	}
	help_all_collapsed = false;
}

static struct keymap *
help_keymap_order(int i)
{
	static struct keymap *order[32];
	static int count = -1;

	if (count < 0) {
		struct view *view;
		int v;

		count = 0;
		order[count++] = generic_keymap;
		order[count++] = search_keymap;
		foreach_view (view, v) {
			struct keymap *km = get_keymap(view->name, strlen(view->name));

			if (km)
				order[count++] = km;
		}
		order[count++] = toggle_keymap;
	}
	return i < count ? order[i] : NULL;
}

static enum status_code
help_open(struct view *view, enum open_flags flags)
{
	struct help_state *state = view->private;
	struct keymap *keymap;
	int i;

	(void) flags;
	reset_view(view);
	state->keys_width = 0;
	state->name_width = 0;

	if (!help_keymaps_initialized || !(flags & OPEN_RELOAD)) {
		help_init_collapsed(view->prev && view->prev != view ? view->prev : NULL);
		help_keymaps_initialized = true;
	}

	/* Compute widths over all keymaps */
	for (i = 0; (keymap = help_keymap_order(i)); i++) {
		if (keymap == toggle_keymap)
			help_toggle_lines(view, state, keymap, false);
		else
			help_keymap_lines(view, state, keymap, false);
	}

	help_add(view, HELP_HEADER, LINE_HEADER, NULL, REQ_NONE, "Quick reference for tig keybindings:", NULL, NULL);
	help_add(view, HELP_TOGGLE_ALL, LINE_SECTION, NULL, REQ_NONE, NULL, NULL, NULL);
	help_add(view, HELP_BLANK, LINE_DEFAULT, NULL, REQ_NONE, "", NULL, NULL);

	for (i = 0; (keymap = help_keymap_order(i)); i++) {
		if (keymap != toggle_keymap && !help_keymap_has_bindings(keymap))
			continue;
		help_add(view, HELP_SECTION, LINE_SECTION, keymap, REQ_NONE, NULL, NULL, NULL);
		if (keymap->hidden)
			continue;
		if (keymap == toggle_keymap)
			help_toggle_lines(view, state, keymap, true);
		else
			help_keymap_lines(view, state, keymap, true);
	}

	return SUCCESS;
}

static bool
help_read(struct view *view, char *line, size_t len)
{
	(void) view;
	(void) line;
	(void) len;
	return true;
}

static bool
help_draw(struct view *view, struct line *line, unsigned int lineno)
{
	struct help *help = line->data;
	struct help_state *state = view->private;

	(void) lineno;
	switch (help->type) {
	case HELP_HEADER:
	case HELP_GROUP:
	case HELP_BLANK:
		draw_text(view, line->type, help->text);
		break;

	case HELP_TOGGLE_ALL:
		draw_text(view, line->type, help_all_collapsed ? "[+] Expand all sections" : "[-] Collapse all sections");
		break;

	case HELP_SECTION:
		draw_formatted(view, line->type, "[%c] %s bindings",
			       help->keymap->hidden ? '+' : '-', help->keymap->name);
		break;

	case HELP_RUN_REQUEST: {
		struct run_request *req = get_run_request(help->request);
		const char *sep;
		int i;

		if (draw_field(view, LINE_DEFAULT, help->key, state->keys_width + 2, ALIGN_RIGHT, false))
			return true;
		if (!req)
			break;
		sep = format_run_request_flags(req);
		for (i = 0; req->argv[i]; i++) {
			if (draw_formatted(view, LINE_HELP_ACTION, "%s%s", sep, req->argv[i]))
				return true;
			sep = " ";
		}
		break;
	}

	case HELP_REQUEST:
	case HELP_TOGGLE:
		if (draw_field(view, LINE_DEFAULT, help->key, state->keys_width + 2, ALIGN_RIGHT, false))
			return true;
		if (draw_field(view, LINE_HELP_ACTION, help->name, state->name_width, ALIGN_LEFT, false))
			return true;
		draw_text(view, LINE_DEFAULT, help->text);
		break;
	}

	return true;
}

static bool
help_grep(struct view *view, struct line *line)
{
	struct help *help = line->data;
	const char *text[4] = { NULL };
	char buf[SIZEOF_STR];
	int n = 0;

	switch (help->type) {
	case HELP_SECTION:
		snprintf(buf, sizeof(buf), "[%c] %s bindings", help->keymap->hidden ? '+' : '-', help->keymap->name);
		text[n++] = buf;
		break;
	case HELP_TOGGLE_ALL:
		text[n++] = help_all_collapsed ? "[+] Expand all sections" : "[-] Collapse all sections";
		break;
	case HELP_RUN_REQUEST: {
		struct run_request *req = get_run_request(help->request);

		text[n++] = help->key;
		if (req) {
			snprintf(buf, sizeof(buf), "%s%s", format_run_request_flags(req), argv_to_string_alloc(req->argv, " "));
			text[n++] = buf;
		}
		break;
	}
	default:
		if (help->key)
			text[n++] = help->key;
		if (help->name)
			text[n++] = help->name;
		if (help->text)
			text[n++] = help->text;
		break;
	}
	text[n] = NULL;
	return grep_text(view, text);
}

static enum request
help_request(struct view *view, enum request request, struct line *line)
{
	struct help *help = line->data;

	switch (request) {
	case REQ_ENTER:
		if (help->type == HELP_SECTION) {
			help->keymap->hidden = !help->keymap->hidden;
			load_view(view, NULL, OPEN_RELOAD);
		} else if (help->type == HELP_TOGGLE_ALL) {
			int k;

			help_all_collapsed = !help_all_collapsed;
			for (k = 0; k < get_keymaps_count(); k++)
				get_keymap_by_index(k)->hidden = help_all_collapsed;
			load_view(view, NULL, OPEN_RELOAD);
		}
		return REQ_NONE;

	case REQ_REFRESH:
		load_view(view, NULL, OPEN_RELOAD);
		return REQ_NONE;

	default:
		return request;
	}
}

static void
help_select(struct view *view, struct line *line)
{
	(void) view;
	(void) line;
}

static void
help_done(struct view *view)
{
	size_t i;

	for (i = 0; i < view->lines; i++) {
		struct help *help = view->line[i].data;

		if (help && help->key) {
			free((void *) help->key);
			help->key = NULL;
		}
	}
}

static bool
help_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	(void) view;
	(void) line;
	(void) column_data;
	return true;
}

static struct view_ops help_ops = {
	"line",
	"",
	VIEW_NO_GIT_DIR | VIEW_REFRESH,
	sizeof(struct help_state),
	help_open,
	help_read,
	help_draw,
	help_request,
	help_grep,
	help_select,
	help_done,
	help_get_column_data,
};

struct view help_view = {
	"help",
	&help_ops,
	NULL,
	&argv_env,
};

void
open_help_view(struct view *prev, enum open_flags flags)
{
	open_view(prev, &help_view, flags | OPEN_RELOAD? 0 : 0);
}
