}

static int
tree_compare_entry(const struct line *line1, const struct line *line2)
{
	if (line1->type != line2->type)
		return line1->type == LINE_DIRECTORY ? -1 : 1;
	return strcmp(tree_path(line1), tree_path(line2));
}

static struct line *
tree_entry(struct view *view, line_type_t type, const char *path,
	   const char *mode, const char *id, unsigned long size, bool has_size)
{
	bool custom = type == LINE_HEADER || tree_path_is_parent(path);
	struct tree_entry *entry;
	struct line *line = add_line_alloc(view, &entry, type, strlen(path), custom);

	if (!line)
		return NULL;

	memcpy(entry->name, path, strlen(path));
	if (mode)
		entry->mode = strtoul(mode, NULL, 8);
	if (id)
		string_copy_rev(entry->id, id);
	entry->size = size;
	entry->has_size = has_size;

	return line;
}

static void
push_tree_stack_entry(struct view *view, const char *name, struct position *position)
{
	size_t pathlen = strlen(view->env->directory);

	if (tree_stack_size < (int) ARRAY_SIZE(tree_stack)) {
		string_copy(tree_stack[tree_stack_size].directory, view->env->directory);
		tree_stack[tree_stack_size].pos = *position;
		tree_stack_size++;
	}

	string_format_from(view->env->directory, &pathlen, "%s/", name);
	clear_position(position);
}

static void
pop_tree_stack_entry(struct view *view, struct position *position)
{
	if (tree_stack_size > 0) {
		tree_stack_size--;
		string_copy(view->env->directory, tree_stack[tree_stack_size].directory);
		if (position)
			*position = tree_stack[tree_stack_size].pos;
	} else {
		view->env->directory[0] = 0;
		if (position)
			clear_position(position);
	}
}

static bool
tree_read_date(struct view *view, char *text, struct tree_state *state)
{
	if (!text && state->read_date) {
		state->read_date = false;
		if (view->pos.lineno == 0 && view->lines > 1 && !view->prev_pos.lineno)
			view->pos.lineno = 1;
		return true;

	} else if (!text) {
		/* Find next entry to process */
		const char *log_file[] = {
			"git", "log", "--encoding=UTF-8", "--no-color", "--pretty=raw",
				"--cc", "--raw", view->vid, "--", "%(directory)", NULL
		};

		if (!view->lines) {
			tree_entry(view, LINE_HEADER, view->env->directory, NULL, NULL, 0, false);
			tree_entry(view, LINE_FILE, view->ref, NULL, NULL, 0, false);
			report("Tree is empty");
			return true;
		}

		if (!begin_update(view, repo.cdup[0] ? repo.cdup : NULL, log_file, OPEN_EXTRA)) {
			report("Failed to load tree data");
			return true;
		}

		state->read_date = true;
		return false;

	} else if (*text == 'c' && !prefixcmp(text, "commit ")) {
		string_copy_rev(state->commit, text + STRING_SIZE("commit "));

	} else if (*text == 'a' && !prefixcmp(text, "author ")) {
		char buf[SIZEOF_STR];

		string_copy(buf, text + STRING_SIZE("author "));
		parse_author_line(buf, &state->author, &state->author_time);

	} else if (*text == 'c' && !prefixcmp(text, "committer ")) {
		char buf[SIZEOF_STR];
		const struct ident *ident;

		string_copy(buf, text + STRING_SIZE("committer "));
		parse_author_line(buf, &ident, &state->committer_time);

	} else if (*text == ':') {
		char *pos;
		size_t i;

		pos = strrchr(text, '\t');
		if (!pos)
			return true;
		text = pos + 1;
		if (*view->env->directory && !strncmp(text, view->env->directory, strlen(view->env->directory)))
			text += strlen(view->env->directory);
		pos = strchr(text, '/');
		if (pos)
			*pos = 0;

		for (i = 1; i < view->lines; i++) {
			struct line *line = &view->line[i];
			struct tree_entry *entry = line->data;

			if (entry->author || strcmp(entry->name, text))
				continue;

			string_copy_rev(entry->commit, state->commit);
			entry->author = state->author;
			entry->time = state->author_time;
			entry->ctime = state->committer_time;
			line->dirty = 1;
			view_column_info_update(view, line);
			break;
		}
	}
	return true;
}

static bool
tree_read(struct view *view, char *text, size_t len)
{
	struct tree_state *state = view->private;
	struct tree_entry *data;
	struct line *entry, *line;
	line_type_t type;
	char *path;
	char *size_str;
	unsigned long size = 0;
	bool has_size = false;

	if (state->read_date || !text)
		return tree_read_date(view, text, state);

	/* "<mode> SP <type> SP <object> SP <object size> TAB <file>" */
	if (len <= 53)
		return true;
	if (view->lines == 0 &&
	    !tree_entry(view, LINE_HEADER, view->env->directory, NULL, NULL, 0, false))
		return false;

	path = strchr(text, '\t');
	if (!path)
		return true;
	*path++ = 0;

	size_str = strrchr(text, ' ');
	if (size_str) {
		while (*size_str == ' ')
			size_str++;
		if (isdigit((unsigned char) *size_str)) {
			size = strtoul(size_str, NULL, 10);
			has_size = true;
		}
	}

	/* Strip the path part ... */
	if (*view->env->directory) {
		size_t pathlen = strlen(path);
		size_t striplen = strlen(view->env->directory);

		if (pathlen > striplen)
			memmove(path, path + striplen, pathlen - striplen + 1);

		/* Insert "link" to parent directory. */
		if (view->lines == 1 &&
		    !tree_entry(view, LINE_DIRECTORY, "..", "040000", view->ref, 0, false))
			return false;
	}

	type = !strncmp(text + 7, "tree", 4) ? LINE_DIRECTORY : LINE_FILE;
	entry = tree_entry(view, type, path, text, text + 12, size, has_size && type == LINE_FILE);
	if (!entry)
		return false;
	data = entry->data;
	view_column_info_update(view, entry);

	/* Skip "Directory ..." and ".." line. */
	for (line = &view->line[1 + !!*view->env->directory]; line < entry; line++) {
		if (tree_compare_entry(line, entry) <= 0)
			continue;

		{
			struct line tmp = *entry;

			memmove(line + 1, line, (entry - line) * sizeof(*entry));
			line->data = data;
			line->type = type;
			line->lineno = tmp.lineno;
			{
				struct line *l;
				unsigned long n = line[1].lineno;

				for (l = line; l <= entry; l++) {
					l->dirty = l->cleareol = 1;
				}
				/* Renumber lines */
				line->lineno = n;
				for (l = line + 1; l <= entry; l++)
					l->lineno = l[-1].lineno + 1;
			}
		}
		return true;
	}

	return true;
}

static bool
tree_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	const struct tree_entry *entry = line->data;
	static struct view_column section;
	static char text[SIZEOF_STR];
	struct view_column *date = get_view_column(view, VIEW_COLUMN_DATE);

	if (line->type == LINE_HEADER) {
		memset(&section, 0, sizeof(section));
		section.type = VIEW_COLUMN_SECTION;
		section.opt.display = LINE_HEADER;
		snprintf(text, sizeof(text), "Directory path /%s", entry->name);
		column_data->section = &section;
		column_data->text = text;
		return true;
	}

	column_data->author = entry->author;
	column_data->date = date && date->opt.use_author ? &entry->time : &entry->ctime;
	if (!entry->author)
		column_data->date = NULL;
	column_data->id = entry->commit;
	if (entry->mode)
		column_data->mode = &entry->mode;
	if (entry->has_size)
		column_data->file_size = &entry->size;
	column_data->file_name = entry->name;

	return true;
}

static bool
tree_draw(struct view *view, struct line *line, unsigned int lineno)
{
	return view_column_draw(view, line, lineno);
}

static bool
tree_grep(struct view *view, struct line *line)
{
	struct tree_entry *entry = line->data;
	const char *text[] = {
		entry->name,
		entry->author ? entry->author->name : "",
		NULL
	};

	if (line->type == LINE_HEADER)
		return false;
	return grep_text(view, text);
}

static enum request
tree_request(struct view *view, enum request request, struct line *line)
{
	enum open_flags flags;
	struct tree_entry *entry = line->data;

	switch (request) {
	case REQ_VIEW_BLAME:
		if (line->type != LINE_FILE) {
			report("Blame only supported for files");
			return REQ_NONE;
		}

		string_copy(view->env->ref, view->vid);
		return request;

	case REQ_EDIT:
		if (line->type != LINE_FILE) {
			report("Edit only supported for files");
		} else {
			open_editor(view->env->file, 0);
		}
		return REQ_NONE;

	case REQ_PARENT:
	case REQ_BACK:
		if (!*view->env->directory) {
			/* quit view if at top of tree */
			return REQ_VIEW_CLOSE;
		}
		/* fake 'cd  ..' */
		pop_tree_stack_entry(view, &view->pos);
		reload_view(view);
		break;

	case REQ_ENTER:
		break;

	default:
		return request;
	}

	/* Cleanup the stack if the tree view is at a different tree. */
	if (!*view->env->directory)
		tree_stack_size = 0;

	switch (line->type) {
	case LINE_DIRECTORY:
		if (request == REQ_PARENT || request == REQ_BACK)
			break;
		if (tree_path_is_parent(entry->name)) {
			pop_tree_stack_entry(view, &view->pos);

		} else {
			const char *basename = tree_path(line);

			push_tree_stack_entry(view, basename, &view->pos);
		}

		reload_view(view);
		break;

	case LINE_FILE:
		if (request != REQ_ENTER)
			break;
		flags = view_is_displayed(view) ? OPEN_SPLIT : OPEN_DEFAULT;
		open_blob_view(view, flags);
		break;

	default:
		return REQ_NONE;
	}

	return REQ_NONE;
}

static void
tree_select(struct view *view, struct line *line)
{
	struct tree_entry *entry = line->data;

	if (line->type == LINE_HEADER) {
		string_format(view->ref, "Files in /%s", view->env->directory);
		return;
	}

	if (line->type == LINE_DIRECTORY && tree_path_is_parent(entry->name)) {
		string_copy(view->ref, "Open parent directory");
		view->env->blob[0] = 0;
		return;
	}

	if (line->type == LINE_FILE) {
		string_copy_rev(view->env->blob, entry->id);
		string_format(view->env->file, "%s%s", view->env->directory, tree_path(line));
	}

	string_copy_rev(view->ref, entry->id);
}

static enum status_code
tree_open(struct view *view, enum open_flags flags)
{
	static const char *tree_argv[] = {
		"git", "ls-tree", "-l", "%(commit)", "%(directory)", NULL
	};

	if (!strcmp(view->env->commit, NULL_ID) || (!*view->env->commit && !*repo.head_id))
		return error("No tree exists for this commit");

	if (view->lines == 0 && repo.prefix[0] && !view->env->directory[0]) {
		char prefix[SIZEOF_STR];
		char *pos = prefix;

		string_copy(prefix, repo.prefix);
		while (pos && *pos) {
			char *end = strchr(pos, '/');

			if (end)
				*end = 0;
			push_tree_stack_entry(view, pos, &view->pos);
			pos = end;
			if (end)
				pos++;
		}

	} else if (strcmp(view->vid, view->ops->id)) {
		view->env->directory[0] = 0;
		tree_stack_size = 0;
	}

	return begin_update(view, repo.cdup[0] ? repo.cdup : NULL, tree_argv, flags)
		? SUCCESS : error("Failed to open tree view");
}

static struct view_ops tree_ops = {
	"file",
	argv_env.commit,
	VIEW_SEND_CHILD_ENTER | VIEW_SORTABLE,
	sizeof(struct tree_state),
	tree_open,
	tree_read,
	tree_draw,
	tree_request,
	tree_grep,
	tree_select,
	NULL,
	tree_get_column_data,
};

struct view tree_view = {
	"tree",
	&tree_ops,
	NULL,
	&argv_env,
};

void
open_tree_view(struct view *prev, enum open_flags flags)
{
	open_view(prev, &tree_view, flags);
}

/* ------------------------------------------------------------------ */
/* Blob view */

struct blob_state {
	char commit[SIZEOF_REF];
	char file[SIZEOF_STR];
	bool has_file;
};

static enum status_code
blob_open(struct view *view, enum open_flags flags)
{
	struct blob_state *state = view->private;
	static const char *blob_argv[] = {
		"git", "cat-file", "blob", "%(blob)", NULL
	};
	const char **argv = (flags & (OPEN_PREPARED | OPEN_REFRESH)) ? view->argv : blob_argv;

	if (!view->env->blob[0] && view->env->file[0]) {
		const char *commit = view->env->commit[0] && strcmp(view->env->commit, NULL_ID)
				   ? view->env->commit : "HEAD";
		char blob_spec[SIZEOF_STR];
		const char *rev_parse_argv[] = {
			"git", "rev-parse", blob_spec, NULL
		};

		if (!string_format(blob_spec, "%s:%s", commit, view->env->file) ||
		    !io_run_buf(rev_parse_argv, view->env->blob, sizeof(view->env->blob), NULL, false))
			return error("Failed to resolve blob from file name");
	}

	if (!view->env->blob[0])
		return error("No file chosen, press %s to open tree view",
			     get_keys(generic_keymap, REQ_VIEW_TREE, false));

	if (view->env->file[0]) {
		string_copy(state->file, view->env->file);
		state->has_file = true;
	}
	string_copy(state->commit, view->env->commit);

	if (!begin_update(view, NULL, argv ? argv : blob_argv, flags))
		return error("Failed to open blob view");

	if (state->has_file)
		string_copy(view->ref, state->file);
	return SUCCESS;
}

static bool
blob_read(struct view *view, char *line, size_t len)
{
	(void) len;
	if (!line)
		return true;
	return pager_common_read(view, line, LINE_DEFAULT, NULL);
}

static void
blob_select(struct view *view, struct line *line)
{
	struct blob_state *state = view->private;

	(void) line;
	if (state->has_file)
		string_format(view->env->file, "%s", state->file);
	view->env->lineno = view->pos.lineno + 1;
}

static enum request
blob_request(struct view *view, enum request request, struct line *line)
{
	struct blob_state *state = view->private;

	switch (request) {
	case REQ_REFRESH:
		if (!state->has_file) {
			report("Cannot reload immutable blob");
		} else {
			string_ncopy(view->env->file, state->file, strlen(state->file));
			reload_view(view);
		}
		return REQ_NONE;

	case REQ_VIEW_BLAME:
		string_ncopy(view->env->ref, state->commit, strlen(state->commit));
		view->env->goto_lineno = line - view->line;
		return request;

	case REQ_EDIT:
		if (state->has_file)
			open_editor(state->file, (line - view->line) + 1);
		return REQ_NONE;

	default:
		return pager_request(view, request, line);
	}
}

static bool
blob_grep(struct view *view, struct line *line)
{
	const char *text[] = { box_text(line), NULL };

	return grep_text(view, text);
}

static struct view_ops blob_ops = {
	"line",
	argv_env.blob,
	VIEW_REFRESH,
	sizeof(struct blob_state),
	blob_open,
	blob_read,
	pager_draw,
	blob_request,
	blob_grep,
	blob_select,
	NULL,
	pager_get_column_data,
};

struct view blob_view = {
	"blob",
	&blob_ops,
	NULL,
	&argv_env,
};

void
open_blob_view(struct view *prev, enum open_flags flags)
{
	open_view(prev, &blob_view, flags);
}
