	&argv_env,
};

void
open_stage_view(struct view *prev, void *status, line_type_t type, enum open_flags flags)
{
	if (type) {
		stage_line_type = type;
		if (status)
			stage_status = *(struct status *) status;
		else
			memset(&stage_status, 0, sizeof(stage_status));
	}

	open_view(prev, &stage_view, flags | OPEN_RELOAD);
}
