cat > /workspace/src/status_view.c <<'EOF'
/* Status and stage views */
#include "tigview.h"

static char status_onbranch[SIZEOF_STR];
static struct status stage_status;
static line_type_t stage_line_type;

/* ------------------------------------------------------------------ */
/* Status parsing */

static bool
status_get_diff(struct status *file, const char *buf, size_t bufsize)
{
	const char *old_mode = buf +  1;
	const char *new_mode = buf +  8;
	const char *old_rev  = buf + 15;
	const char *new_rev  = buf + 56;
	const char *status   = buf + 97;

	if (bufsize < 98 ||
	    old_mode[-1] != ':' ||
	    new_mode[-1] != ' ' ||
	    old_rev[-1]  != ' ' ||
	    new_rev[-1]  != ' ' ||
	    status[-1]   != ' ')
		return false;

	file->status = *status;

	string_copy_rev(file->old.rev, old_rev);
	string_copy_rev(file->new.rev, new_rev);

	file->old.mode = strtoul(old_mode, NULL, 8);
	file->new.mode = strtoul(new_mode, NULL, 8);

	file->old.name[0] = file->new.name[0] = 0;

	return true;
}

static void
status_add_line(struct view *view, line_type_t type, struct status *status)
{
	struct status *data = NULL;
	struct line *line;

	if (status) {
		line = add_line_alloc(view, &data, type, 0, false);
		if (line)
			*data = *status;
	} else {
		line = add_line(view, NULL, type, 0, false);
	}
	if (line)
		view_column_info_update(view, line);
}

static bool
status_run(struct view *view, const char *argv[], char status_char, line_type_t type)
{
	size_t len;
	int exit_status;
	char *out = io_capture(argv, repo.cdup[0] ? repo.cdup : NULL, &len, &exit_status, false);
	char *pos, *end;
	bool added = false;

	add_line(view, NULL, type, 0, false);

	if (!out)
		return false;

	pos = out;
	end = out + len;
	while (pos < end) {
		struct status file;
		size_t entrylen = strnlen(pos, end - pos);

		memset(&file, 0, sizeof(file));

		if (status_char) {
			string_ncopy(file.new.name, pos, entrylen);
			file.status = status_char;
			string_copy(file.old.name, file.new.name);
			pos += entrylen + 1;
		} else {
			if (!status_get_diff(&file, pos, entrylen))
				break;
			pos += entrylen + 1;
			if (pos >= end)
				break;
			entrylen = strnlen(pos, end - pos);
			string_ncopy(file.old.name, pos, entrylen);
			pos += entrylen + 1;

			/* Copies and renames have a second filename */
			if (file.status == 'C' || file.status == 'R') {
				if (pos >= end)
					break;
				entrylen = strnlen(pos, end - pos);
				string_ncopy(file.new.name, pos, entrylen);
				pos += entrylen + 1;
			} else {
				string_copy(file.new.name, file.old.name);
			}
		}

		/* Skip duplicate unmerged entries */
		if (file.status == 'U' && view->lines > 0) {
			struct status *last = view->line[view->lines - 1].data;

			if (last && last->status == 'U' && !strcmp(last->new.name, file.new.name))
				continue;
		}

		status_add_line(view, type, &file);
		added = true;
	}

	free(out);

	if (!added)
		add_line(view, NULL, LINE_STAT_NONE, 0, false);

	return true;
}

static int
count_revs(const char *range)
{
	const char *argv[] = { "git", "rev-list", "--count", range, NULL };
	char buf[64];

	if (!io_run_buf(argv, buf, sizeof(buf), NULL, false))
		return -1;
	return atoi(buf);
}

static void
status_update_onbranch(void)
{
	static const char *paths[][3] = {
		{ "rebase-apply/rebasing",	"rebase-apply/head-name",	"Rebasing" },
		{ "rebase-apply/applying",	"rebase-apply/head-name",	"Applying mailbox to" },
		{ "rebase-apply/",		"rebase-apply/head-name",	"Rebasing mailbox onto" },
		{ "rebase-merge/interactive",	"rebase-merge/head-name",	"Interactive rebase" },
		{ "rebase-merge/",		"rebase-merge/head-name",	"Rebase merge" },
		{ "MERGE_HEAD",			NULL,				"Merging" },
		{ "BISECT_LOG",			NULL,				"Bisecting" },
		{ "HEAD",			NULL,				"On branch" },
	};
	char buf[SIZEOF_STR];
	struct stat st;
	size_t i;

	if (!*repo.head_id) {
		string_copy(status_onbranch, "Initial commit");
		return;
	}

	for (i = 0; i < ARRAY_SIZE(paths); i++) {
		const char *prefix = paths[i][2];
		const char *head = repo.head;
		char tracking_info[SIZEOF_STR] = "";
		char headbuf[SIZEOF_STR];

		if (!string_format(buf, "%s/%s", repo.git_dir, paths[i][0]) ||
		    lstat(buf, &st) < 0)
			continue;

		if (paths[i][1]) {
			char path[SIZEOF_STR];
			char *data;

			snprintf(path, sizeof(path), "%s/%s", repo.git_dir, paths[i][1]);
			data = read_file(path, NULL);
			if (data) {
				string_copy(headbuf, string_trim(data));
				free(data);
				head = headbuf;
				if (!prefixcmp(head, "refs/heads/"))
					head += STRING_SIZE("refs/heads/");
			}
		}

		if (!*head && !strcmp(paths[i][0], "HEAD")) {
			string_format(status_onbranch, "HEAD detached at %s", repo.head_id);
			return;
		}

		if (!strcmp(paths[i][0], "HEAD") && *repo.remote) {
			char branch_merge[SIZEOF_STR] = "";
			const char *config_argv[] = { "git", "config", "--get", NULL, NULL };
			char key[SIZEOF_STR];

			snprintf(key, sizeof(key), "branch.%s.merge", repo.head);
			config_argv[3] = key;
			if (io_run_buf(config_argv, branch_merge, sizeof(branch_merge), NULL, false)) {
				const char *merge = branch_merge;
				char upstream[SIZEOF_STR];
				char range[SIZEOF_STR * 2];
				char ref[SIZEOF_STR];
				int ahead = 0, behind = 0;

				if (!prefixcmp(merge, "refs/heads/"))
					merge += STRING_SIZE("refs/heads/");
				snprintf(upstream, sizeof(upstream), "%s/%s", repo.remote, merge);
				snprintf(ref, sizeof(ref), "refs/remotes/%s", upstream);
				{
					const char *verify_argv[] = { "git", "rev-parse", "--verify", "-q", ref, NULL };
					char id[SIZEOF_STR];

					if (io_run_buf(verify_argv, id, sizeof(id), NULL, false)) {
						snprintf(range, sizeof(range), "%s..HEAD", ref);
						ahead = count_revs(range);
						snprintf(range, sizeof(range), "HEAD..%s", ref);
						behind = count_revs(range);
						if (ahead < 0)
							ahead = 0;
						if (behind < 0)
							behind = 0;
					}
				}

				if (ahead && behind)
					snprintf(tracking_info, sizeof(tracking_info),
						 ". Your branch and '%s' have diverged, and have %d and %d different commits each, respectively",
						 upstream, ahead, behind);
				else if (ahead)
					snprintf(tracking_info, sizeof(tracking_info),
						 ". Your branch is ahead of '%s' by %d commit%s.",
						 upstream, ahead, ahead > 1 ? "s" : "");
				else if (behind)
					snprintf(tracking_info, sizeof(tracking_info),
						 ". Your branch is behind '%s' by %d commit%s.",
						 upstream, behind, behind > 1 ? "s" : "");
				else
					snprintf(tracking_info, sizeof(tracking_info),
						 ". Your branch is up-to-date with '%s'.", upstream);
			}
		}

		if (!string_format(status_onbranch, "%s %s%s", prefix, head, tracking_info))
			string_copy(status_onbranch, repo.head);
		return;
	}

	string_copy(status_onbranch, "Not currently on any branch");
}

struct status_restore_info {
	line_type_t section;
	long offset;
	bool valid;
};

static struct status_restore_info status_restore_info;

static void
status_save_position(struct view *view)
{
	long i;

	status_restore_info.valid = false;
	if (!view->lines || view->pos.lineno >= view->lines)
		return;
	for (i = view->pos.lineno; i >= 0; i--) {
		struct line *line = &view->line[i];

		if (!line->data && line->type != LINE_STAT_NONE) {
			status_restore_info.section = line->type;
			status_restore_info.offset = view->pos.lineno - i;
			status_restore_info.valid = true;
			return;
		}
	}
}

static void
status_restore(struct view *view)
{
	long lineno = -1;
	size_t i;

	if (!check_position_any(&view->prev_pos) && !status_restore_info.valid)
		return;

	if (status_restore_info.valid) {
		for (i = 0; i < view->lines; i++) {
			struct line *line = &view->line[i];

			if (!line->data && line->type == status_restore_info.section) {
				lineno = i + status_restore_info.offset;
				break;
			}
		}
	}
	if (lineno < 0)
		lineno = view->prev_pos.lineno;
	status_restore_info.valid = false;

	if (lineno >= (long) view->lines)
		lineno = view->lines - 1;
	while (lineno < (long) view->lines && !view->line[lineno].data)
		lineno++;
	while (lineno > 0 && (lineno >= (long) view->lines || !view->line[lineno].data))
		lineno--;

	/* If the above fails, always skip the "On branch" line. */
	if (lineno < (long) view->lines)
		view->pos.lineno = lineno;
	else
		view->pos.lineno = 1;

	if (view->prev_pos.offset > view->pos.lineno)
		view->pos.offset = view->pos.lineno;
	else if (view->prev_pos.offset < view->lines)
		view->pos.offset = view->prev_pos.offset;
	if (view->pos.lineno >= view->pos.offset + view->height)
		view->pos.offset = view->pos.lineno - view->height + 1;

	clear_position(&view->prev_pos);
}

static enum status_code
status_open(struct view *view, enum open_flags flags)
{
	const char *staged_argv[] = {
		"git", "diff-index", "-z", "--diff-filter=ACDMRTXB", "-M", "--cached", "HEAD", "--", NULL
	};
	const char *no_head_argv[] = {
		"git", "ls-files", "-z", "--cached", "--exclude-standard", NULL
	};
	const char *unstaged_argv[] = {
		"git", "diff-files", "-z", NULL
	};
	const char *other_argv[] = {
		"git", "ls-files", "-z", "--others", "--exclude-standard",
		opt_status_show_untracked_dirs ? NULL : "--directory", "--no-empty-directory", NULL
	};
	const char *refresh_argv[] = {
		"git", "update-index", "-q", "--unmerged", "--refresh", NULL
	};
	bool had_lines = view->lines > 0;

	(void) flags;
	if (!repo.is_inside_work_tree && !*repo.worktree)
		return error("The status view requires a working tree");

	if (had_lines)
		status_save_position(view);
	reset_view(view);
	if (!had_lines)
		status_restore_info.valid = false;

	load_repo_head();
	status_update_onbranch();

	io_run_ok(refresh_argv, repo.cdup[0] ? repo.cdup : NULL);

	add_line(view, NULL, LINE_HEADER, 0, true);

	if (!*repo.head_id) {
		if (!status_run(view, no_head_argv, 'A', LINE_STAT_STAGED))
			return error("Failed to load status data");
	} else if (!status_run(view, staged_argv, 0, LINE_STAT_STAGED)) {
		return error("Failed to load status data");
	}

	if (!status_run(view, unstaged_argv, 0, LINE_STAT_UNSTAGED))
		return error("Failed to load status data");

	if (opt_status_show_untracked_files) {
		if (!status_run(view, other_argv, '?', LINE_STAT_UNTRACKED))
			return error("Failed to load status data");
	}

	string_copy(view->vid, "");
	status_restore(view);
	return SUCCESS;
}

static bool
status_read(struct view *view, char *line, size_t len)
{
	(void) view;
	(void) line;
	(void) len;
	return true;
}

static bool
status_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	struct status *status = line->data;

	(void) view;
	if (!status) {
		static struct view_column group_column;
		const char *text;
		line_type_t type;

		memset(&group_column, 0, sizeof(group_column));
		column_data->section = &group_column;
		column_data->section->type = VIEW_COLUMN_SECTION;

		switch (line->type) {
		case LINE_STAT_STAGED:
			type = LINE_SECTION;
			text = "Changes to be committed:";
			break;

		case LINE_STAT_UNSTAGED:
			type = LINE_SECTION;
			text = "Changes not staged for commit:";
			break;

		case LINE_STAT_UNTRACKED:
			type = LINE_SECTION;
			text = "Untracked files:";
			break;

		case LINE_STAT_NONE:
			type = LINE_DEFAULT;
			text = "  (no files)";
			break;

		case LINE_HEADER:
			type = LINE_HEADER;
			text = status_onbranch;
			break;

		default:
			return false;
		}

		group_column.opt.display = type;
		column_data->text = text;

	} else {
		static char status_char[2];

		status_char[0] = status->status;
		status_char[1] = 0;
		column_data->status = status_char;
		column_data->file_name = status->new.name;
	}
	return true;
}

static bool
status_draw(struct view *view, struct line *line, unsigned int lineno)
{
	return view_column_draw(view, line, lineno);
}

bool
status_stage_info(char *buf, size_t bufsize, line_type_t type, struct status *status)
{
	const char *file = status ? status->new.name : "";
	const char *info;

	switch (type) {
	case LINE_STAT_STAGED:
		if (status && status->status)
			info = "Staged changes to %s";
		else
			info = "Staged changes";
		break;

	case LINE_STAT_UNSTAGED:
		if (status && status->status)
			info = "Unstaged changes to %s";
		else
			info = "Unstaged changes";
		break;

	case LINE_STAT_UNTRACKED:
		info = "Untracked file %s";
		break;

	default:
		info = "";
	}

	return string_nformat(buf, bufsize, NULL, info, file);
}

static const char *
get_view_key_name(struct view *view, enum request request)
{
	const char *key = get_keys(view->keymap, request, false);

	if (!*key)
		key = get_keys(generic_keymap, request, false);
	return *key ? key : "(no key)";
}

static void
status_select(struct view *view, struct line *line)
{
	struct status *status = line->data;
	char file[SIZEOF_STR] = "all files";
	const char *text;
	const char *key;

	if (status && !string_format(file, "'%s'", status->new.name))
		return;

	if (!status && view_has_line(view, line + 1) && line[1].type == LINE_STAT_NONE)
		line++;

	switch (line->type) {
	case LINE_STAT_STAGED:
		text = "Press %s to unstage %s for commit";
		break;

	case LINE_STAT_UNSTAGED:
		text = "Press %s to stage %s for commit";
		break;

	case LINE_STAT_UNTRACKED:
		text = "Press %s to stage %s for addition";
		break;

	case LINE_HEADER:
	case LINE_STAT_NONE:
	default:
		text = "Nothing to update";
		break;
	}

	if (status && status->status == 'U') {
		text = "Press %s to resolve conflict in %s";
		key = get_view_key_name(view, REQ_STATUS_MERGE);

	} else {
		key = get_view_key_name(view, REQ_STATUS_UPDATE);
	}

	string_format(view->ref, text, key, file);
	if (status)
		string_copy(view->env->file, status->new.name);
}

static bool
status_grep(struct view *view, struct line *line)
{
	struct status *status = line->data;

	if (status) {
		const char buf[2] = { status->status, 0 };
		const char *text[] = { status->new.name, buf, NULL };

		return grep_text(view, text);
	}

	return false;
}

/* ------------------------------------------------------------------ */
/* Updating */

static bool
status_update_write_files(struct status *files, size_t count, line_type_t type)
{
	const char *staged_argv[] = {
		"git", "update-index", "-z", "--index-info", NULL
	};
	const char *others_argv[] = {
		"git", "update-index", "-z", "--add", "--remove", "--stdin", NULL
	};
	char *input = NULL;
	size_t inlen = 0, alloc = 0;
	size_t i;
	bool ok;

	for (i = 0; i < count; i++) {
		char buf[SIZEOF_STR * 2];
		int n;

		if (type == LINE_STAT_STAGED)
			n = snprintf(buf, sizeof(buf), "%06o %s\t%s", files[i].old.mode,
				     files[i].old.rev, files[i].old.name);
		else
			n = snprintf(buf, sizeof(buf), "%s", files[i].new.name);
		if (n < 0)
			continue;
		if (inlen + n + 2 > alloc) {
			alloc = (inlen + n + 2) * 2;
			input = xrealloc(input, alloc);
		}
		memcpy(input + inlen, buf, n);
		inlen += n;
		input[inlen++] = 0;
	}

	ok = io_run_with_input(type == LINE_STAT_STAGED ? staged_argv : others_argv,
			       repo.cdup[0] ? repo.cdup : NULL, input ? input : "", inlen);
	free(input);
	return ok;
}

bool
status_update_file(struct status *status, line_type_t type)
{
	return status_update_write_files(status, 1, type);
}

bool
status_update_files(struct view *view, struct line *line)
{
	struct status *files = NULL;
	size_t count = 0;
	line_type_t type = line->type;

	for (; view_has_line(view, line) && line->type == type && line->data; line++) {
		files = xrealloc(files, sizeof(*files) * (count + 1));
		files[count++] = *(struct status *) line->data;
	}

	if (!count) {
		free(files);
		return true;
	}
	{
		bool ok = status_update_write_files(files, count, type);

		free(files);
		return ok;
	}
}

static bool
status_update(struct view *view)
{
	struct line *line = &view->line[view->pos.lineno];

	if (!line->data) {
		if (view_has_line(view, line + 1) && line[1].type == LINE_STAT_NONE) {
			report("Nothing to update");
			return false;
		}

		if (!status_update_files(view, line + 1)) {
			report("Failed to update file status");
			return false;
		}

	} else if (!status_update_file(line->data, line->type)) {
		report("Failed to update file status");
		return false;
	}

	return true;
}

bool
status_revert(struct status *status, line_type_t type, bool has_none)
{
	if (!status || type != LINE_STAT_UNSTAGED) {
		if (type == LINE_STAT_STAGED) {
			report("Cannot revert changes to staged files");
		} else if (type == LINE_STAT_UNTRACKED) {
			report("Cannot revert changes to untracked files");
		} else if (has_none) {
			report("Nothing to revert");
		} else {
			report("Cannot revert changes to multiple files");
		}
		return false;

	} else {
		char prompt[SIZEOF_STR + 64];

		snprintf(prompt, sizeof(prompt), "Are you sure you want to revert changes to %s?", status->old.name);
		if (prompt_yesno(prompt)) {
			const char *checkout_argv[] = {
				"git", "checkout", "--", status->old.name, NULL
			};

			if (status->status == 'U') {
				const char *reset_argv[] = { "git", "update-index", "--cacheinfo", NULL };
				(void) reset_argv;
			}
			return io_run_ok(checkout_argv, repo.cdup[0] ? repo.cdup : NULL);
		}
		return false;
	}
}

static enum request
status_enter(struct view *view, struct line *line)
{
	struct status *status = line->data;
	enum open_flags flags = view_is_displayed(view) ? OPEN_SPLIT : OPEN_DEFAULT;

	if (line->type == LINE_STAT_NONE ||
	    (!status && view_has_line(view, line + 1) && line[1].type == LINE_STAT_NONE)) {
		report("No file to diff");
		return REQ_NONE;
	}

	switch (line->type) {
	case LINE_STAT_STAGED:
	case LINE_STAT_UNSTAGED:
		break;

	case LINE_STAT_UNTRACKED:
		if (!status) {
			report("No file to show");
			return REQ_NONE;
		}

		if (!suffixcmp(status->new.name, -1, "/")) {
			report("Cannot display a directory");
			return REQ_NONE;
		}
		break;

	default:
		report("Nothing to enter");
		return REQ_NONE;
	}

	open_stage_view(view, status, line->type, flags);
	return REQ_NONE;
}

static enum request
status_request(struct view *view, enum request request, struct line *line)
{
	struct status *status = line->data;

	switch (request) {
	case REQ_STATUS_UPDATE:
		if (!status_update(view))
			return REQ_NONE;
		break;

	case REQ_STATUS_REVERT:
		if (!status_revert(status, line->type,
				   view_has_line(view, line + 1) && line[1].type == LINE_STAT_NONE))
			return REQ_NONE;
		break;

	case REQ_STATUS_MERGE:
		if (!status || status->status != 'U') {
			report("Merging only possible for files with unmerged status ('U').");
			return REQ_NONE;
		} else {
			const char *mergetool_argv[] = { "git", "mergetool", status->new.name, NULL };

			open_external_viewer(mergetool_argv, repo.cdup[0] ? repo.cdup : NULL, false, true, false, false, true, "");
		}
		break;

	case REQ_EDIT:
		if (!status)
			return request;
		if (status->status == 'D') {
			report("File has been deleted.");
			return REQ_NONE;
		}

		open_editor(status->new.name, 0);
		break;

	case REQ_VIEW_BLAME:
		if (line->type == LINE_STAT_UNTRACKED || !status) {
			report("Nothing to blame here");
			return REQ_NONE;
		}
		if (status)
			view->env->ref[0] = 0;
		return request;

	case REQ_ENTER:
		return status_enter(view, line);

	case REQ_REFRESH:
		load_repo_head();
		break;

	default:
		return request;
	}

	refresh_view(view);
	{
		struct view *main = &main_view;

		if (main->lines && view_is_displayed(main))
			refresh_view(main);
	}

	return REQ_NONE;
}

