/* Sorting */
struct sort_state {
	enum view_column_type field;
	bool initialized;
	bool reverse;
};

static struct sort_state refs_sort;
static struct sort_state tree_sort_state;

static bool
refs_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	const struct reference *reference = line->data;
	struct view_column *date = get_view_column(view, VIEW_COLUMN_DATE);

	column_data->author = reference->author;
	column_data->committer = reference->committer;
	column_data->date = date && date->opt.use_author ? &reference->time : &reference->ctime;
	if (!reference->author)
		column_data->date = NULL;
	column_data->id = reference->ref->id;
	column_data->ref = reference->ref;
	column_data->commit_title = reference->title;

	return true;
}

static void
refs_select(struct view *view, struct line *line)
{
	struct reference *reference = line->data;
	const struct ref *ref = reference->ref;

	if (reference->is_all) {
		string_copy(view->ref, ref->name);
		view->env->commit[0] = 0;
		view->env->head[0] = 0;
		view->env->ref[0] = 0;
		view->env->branch[0] = 0;
		view->env->remote[0] = 0;
		view->env->tag[0] = 0;
		view->env->refname[0] = 0;
		return;
	}
	string_copy_rev(view->ref, ref->id);
	string_copy_rev(view->env->commit, ref->id);
	string_copy_rev(view->env->head, ref->id);
	string_copy(view->env->refname, ref->name);
	string_copy(view->env->ref, ref->name);

	if (ref_is_remote(ref)) {
		char *slash = strchr(ref->name, '/');

		if (slash) {
			string_ncopy(view->env->remote, ref->name, slash - ref->name);
			string_copy(view->env->branch, slash + 1);
		}
		view->env->tag[0] = 0;
	} else if (ref_is_tag(ref)) {
		string_copy(view->env->tag, ref->name);
		view->env->branch[0] = 0;
		view->env->remote[0] = 0;
	} else {
		string_copy(view->env->branch, ref->name);
		view->env->tag[0] = 0;
		view->env->remote[0] = 0;
	}
}

static enum request
refs_request(struct view *view, enum request request, struct line *line)
{
	struct reference *reference = line->data;

	switch (request) {
	case REQ_REFRESH:
		load_refs(true);
		refresh_view(view);
		return REQ_NONE;

	case REQ_ENTER:
	{
		const struct ref *ref = reference->ref;
		extern bool main_prepare_argv(const char *rev, bool all);

		if (!main_prepare_argv(reference->is_all ? "--all" : ref->name, reference->is_all))
			report("Failed to format argument");
		else
			open_main_view(view, OPEN_SPLIT | OPEN_PREPARED);
		return REQ_NONE;
	}

	default:
		return request;
	}
}

static bool
refs_read(struct view *view, char *data, size_t len)
{
	char *author;
	char *committer;
	char *title;
	char *end = data ? data + len : NULL;
	size_t i;

	if (!data)
		return true;

	author = memchr(data, 0, len);
	if (!author)
		return true;
	author++;
	committer = author < end ? memchr(author, 0, end - author) : NULL;
	if (!committer)
		return true;
	committer++;
	title = committer < end ? memchr(committer, 0, end - committer) : NULL;
	if (!title)
		return true;
	title++;

	for (i = 0; i < view->lines; i++) {
		struct line *line = &view->line[i];
		struct reference *reference = line->data;
		char buf[SIZEOF_STR];

		if (reference->is_all || strncmp(reference->ref->id, data, SIZEOF_REV - 1))
			continue;

		string_copy(buf, author);
		parse_author_line(buf, &reference->author, &reference->time);
		string_copy(buf, committer);
		parse_author_line(buf, &reference->committer, &reference->ctime);
		free(reference->title);
		reference->title = xstrdup(title);
		view_column_info_update(view, line);
	}

	return true;
}

static bool
refs_open_visitor(void *data, const struct ref *ref)
{
	struct view *view = data;
	struct reference *reference;
	bool is_all = ref == refs_all;
	struct line *line;

	if (!is_all) {
		if (ref->type == REFERENCE_STASH || ref->type == REFERENCE_NOTE ||
		    ref->type == REFERENCE_PREFETCH || ref->type == REFERENCE_OTHER)
			return true;
		if (ref->type == REFERENCE_HEAD && !strcmp(ref->name, "HEAD") && !*repo.head)
			;
	}

	line = add_line_alloc(view, &reference, LINE_DEFAULT, 0, is_all);
	if (!line)
		return false;

	reference->ref = ref;
	reference->is_all = is_all;
	view_column_info_update(view, line);

	return true;
}

static void
refs_done(struct view *view)
{
	size_t i;

	for (i = 0; i < view->lines; i++) {
		struct reference *reference = view->line[i].data;

		if (reference) {
			free(reference->title);
			reference->title = NULL;
		}
	}
}

static enum status_code
refs_open(struct view *view, enum open_flags flags)
{
	const char *refs_log[] = {
		"git", "log", "--encoding=UTF-8", "--no-color", "--date=raw",
			opt_mailmap ? "--pretty=format:%H%x00%aN <%aE> %ad%x00%cN <%cE> %cd%x00%s"
				    : "--pretty=format:%H%x00%an <%ae> %ad%x00%cn <%ce> %cd%x00%s",
			"--all", "--simplify-by-decoration", NULL
	};

	(void) flags;
	refs_done(view);
	if (!begin_update(view, NULL, refs_log, OPEN_RELOAD))
		return error("Failed to open refs view");

	view_column_reset(view);
	refs_open_visitor(view, get_refs_all());
	foreach_ref(refs_open_visitor, view);
	refs_sort.initialized = false;

	return SUCCESS;
}

static bool
refs_grep(struct view *view, struct line *line)
{
	struct reference *reference = line->data;
	const char *text[] = {
		reference->ref->name,
		reference->author ? reference->author->name : "",
		reference->title ? reference->title : "",
		NULL
	};

	(void) view;
	return grep_text(view, text);
}

static bool
refs_draw(struct view *view, struct line *line, unsigned int lineno)
{
	return view_column_draw(view, line, lineno);
}

static struct view_ops refs_ops = {
	"reference",
	argv_env.head,
	VIEW_REFRESH | VIEW_SORTABLE,
	0,
	refs_open,
	refs_read,
	refs_draw,
	refs_request,
	refs_grep,
	refs_select,
	refs_done,
	refs_get_column_data,
};

struct view refs_view = {
	"refs",
	&refs_ops,
	NULL,
	&argv_env,
};

void
open_refs_view(struct view *prev, enum open_flags flags)
{
	open_view(prev, &refs_view, flags | OPEN_RELOAD);
}

/* ------------------------------------------------------------------ */
/* Sorting of refs and tree views */

static struct view *sorting_view;
static struct sort_state *sorting_state;

static int
sort_order(struct sort_state *state, int result)
{
	return state->reverse ? -result : result;
}

static int
ident_compare(const struct ident *i1, const struct ident *i2)
{
	if (!i1 || !i2)
		return (!!i1) - (!!i2);
	if (!i1->name || !i2->name)
		return (!!i1->name) - (!!i2->name);
	return strcmp(i1->name, i2->name);
}

static int
timecmp(const struct time *t1, const struct time *t2)
{
	if (!t1 || !t2)
		return (!!t1) - (!!t2);
	return t1->sec < t2->sec ? -1 : t1->sec > t2->sec ? 1 : 0;
}

static int
sort_view_compare(const void *l1, const void *l2)
{
	const struct line *line1 = l1;
	const struct line *line2 = l2;
	struct view_column_data d1 = {0}, d2 = {0};
	int result = 0;

	sorting_view->ops->get_column_data(sorting_view, line1, &d1);
	sorting_view->ops->get_column_data(sorting_view, line2, &d2);

	if (sorting_view == &tree_view) {
		if (line1->type == LINE_HEADER)
			return -1;
		if (line2->type == LINE_HEADER)
			return 1;
		if (d1.file_name && !strcmp(d1.file_name, ".."))
			return -1;
		if (d2.file_name && !strcmp(d2.file_name, ".."))
			return 1;
	}

	switch (sorting_state->field) {
	case VIEW_COLUMN_AUTHOR:
		result = ident_compare(d1.author, d2.author);
		break;
	case VIEW_COLUMN_COMMITTER:
		result = ident_compare(d1.committer, d2.committer);
		break;
	case VIEW_COLUMN_DATE:
		result = timecmp(d1.date, d2.date);
		break;
	case VIEW_COLUMN_COMMIT_TITLE:
		result = strcmp(d1.commit_title ? d1.commit_title : "", d2.commit_title ? d2.commit_title : "");
		break;
	case VIEW_COLUMN_FILE_NAME:
		if (line1->type != line2->type)
			result = line1->type == LINE_DIRECTORY ? -1 : 1;
		else
			result = strcmp(d1.file_name ? d1.file_name : "", d2.file_name ? d2.file_name : "");
		break;
	case VIEW_COLUMN_FILE_SIZE:
		result = (d1.file_size ? (long) *d1.file_size : -1) - (d2.file_size ? (long) *d2.file_size : -1);
		result = result < 0 ? -1 : result > 0;
		break;
	case VIEW_COLUMN_MODE:
		result = (d1.mode ? (int) *d1.mode : 0) - (d2.mode ? (int) *d2.mode : 0);
		break;
	case VIEW_COLUMN_REF:
		if (d1.ref && d2.ref) {
			if (d1.ref == refs_all || d2.ref == refs_all)
				result = d1.ref == refs_all ? -1 : 1;
			else
				result = ref_compare(d1.ref, d2.ref);
		}
		break;
	case VIEW_COLUMN_LINE_NUMBER:
	default:
		result = (long) line1->lineno - (long) line2->lineno;
		if (sorting_view == &refs_view) {
			const struct reference *r1 = line1->data, *r2 = line2->data;

			if (r1->is_all || r2->is_all)
				result = r1->is_all ? -1 : 1;
			else
				result = ref_compare(r1->ref, r2->ref);
		}
		break;
	}

	return sort_order(sorting_state, result);
}

static bool
column_is_sortable(enum view_column_type type)
{
	return type != VIEW_COLUMN_ID && type != VIEW_COLUMN_SECTION && type != VIEW_COLUMN_TEXT &&
	       type != VIEW_COLUMN_STATUS;
}

void
sort_view_request(struct view *view, bool change_field, char *msg, size_t msgsize)
{
	struct sort_state *state = view == &tree_view ? &tree_sort_state : &refs_sort;
	struct view_column *column;
	size_t i;

	if (!view->columns)
		view_column_reset(view);

	if (!state->initialized) {
		state->field = view == &refs_view ? VIEW_COLUMN_REF : VIEW_COLUMN_LINE_NUMBER;
		state->initialized = true;
	}

	if (change_field) {
		struct view_column *current = get_view_column(view, state->field);
		struct view_column *next;

		next = current ? current->next : view->columns;
		while (true) {
			if (!next)
				next = view->columns;
			if (column_is_sortable(next->type))
				break;
			next = next->next;
		}
		state->field = next->type;
		snprintf(msg, msgsize, "set sort-field = %s", view_column_type_name(state->field));
	} else {
		state->reverse = !state->reverse;
		snprintf(msg, msgsize, "set sort-order = %s", state->reverse ? "descending" : "ascending");
	}

	sorting_view = view;
	sorting_state = state;
	{
		struct line *selected = view->lines ? &view->line[view->pos.lineno] : NULL;
		void *selected_data = selected ? selected->data : NULL;
		unsigned long *linenos = xcalloc(view->lines + 1, sizeof(*linenos));

		for (i = 0; i < view->lines; i++)
			linenos[i] = view->line[i].lineno;
		qsort(view->line, view->lines, sizeof(*view->line), sort_view_compare);
		(void) linenos;
		free(linenos);
		for (i = 0; i < view->lines; i++)
			if (view->line[i].data == selected_data) {
				view->pos.lineno = i;
				break;
			}
		(void) column;
	}
	redraw_view(view);
}

/* ------------------------------------------------------------------ */
/* Stash view */

struct stash_state {
	char **names;
	size_t names_count;
};

struct stash_commit {
	struct commit commit;
};

static enum status_code
stash_open(struct view *view, enum open_flags flags)
{
	const char *stash_argv[] = { "git", "stash", "list", "--encoding=UTF-8", "--no-color",
		opt_mailmap ? "--pretty=format:%H %P%x00%aN <%aE> %at %ai%x00%cN <%cE> %ct %ci%x00%s%x00%gd"
			    : "--pretty=format:%H %P%x00%an <%ae> %at %ai%x00%cn <%ce> %ct %ci%x00%s%x00%gd",
		NULL };

	view_column_reset(view);
	if (!begin_update(view, NULL, stash_argv, flags | OPEN_RELOAD))
		return error("Failed to open stash view");
	return SUCCESS;
}

struct stash_line {
	struct commit commit;
	char name[SIZEOF_REF];
};

static void
parse_iso_ident(char *ident, const struct ident **author, struct time *time)
{
	char *emailend = strchr(ident, '>');
	size_t len = strlen(ident);

	if (emailend && len > 6) {
		char zone[8];
		char *secs = emailend + 2;

		string_copy(zone, ident + len - 5);
		*(emailend + 1) = 0;
		parse_author_line(ident, author, NULL);
		parse_timesec(time, secs);
		parse_timezone(time, zone);
	} else {
		parse_author_line(ident, author, time);
	}
}

static bool
stash_read(struct view *view, char *data, size_t len)
{
	char *fields[5] = {0};
	char *end;
	char *p;
	int n = 0;
	struct stash_line *stash;
	struct line *line;

	if (!data) {
		if (!view->lines && !view->prev && view == display[0])
			die("No revisions match the given arguments.");
		return true;
	}

	end = data + len;
	p = data + strlen(data) + 1;
	while (p < end && n < 5) {
		fields[n++] = p;
		p += strlen(p) + 1;
	}

	line = add_line_alloc(view, &stash, LINE_MAIN_COMMIT, 0, false);
	if (!line)
		return false;
	string_copy_rev(stash->commit.id, data);
	if (fields[0])
		parse_iso_ident(fields[0], &stash->commit.author, &stash->commit.time);
	if (fields[1])
		parse_iso_ident(fields[1], &stash->commit.committer, &stash->commit.ctime);
	stash->commit.title = xstrdup(fields[2] ? fields[2] : "");
	string_copy(stash->name, fields[3] ? fields[3] : "");
	view_column_info_update(view, line);
	return true;
}

static bool
stash_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	struct stash_line *stash = line->data;
	struct view_column *date = get_view_column(view, VIEW_COLUMN_DATE);

	column_data->author = stash->commit.author;
	column_data->committer = stash->commit.committer;
	column_data->date = date && date->opt.use_author ? &stash->commit.time : &stash->commit.ctime;
	column_data->id = stash->commit.id;
	column_data->reflog = stash->name;
	column_data->commit_title = stash->commit.title;
	return true;
}

static void
stash_select(struct view *view, struct line *line)
{
	struct stash_line *stash = line->data;

	string_copy(view->ref, stash->name);
	string_copy(view->env->stash, stash->name);
	string_copy_rev(view->env->commit, stash->commit.id);
}

static enum request
stash_request(struct view *view, enum request request, struct line *line)
{
	enum open_flags flags = (view_is_displayed(view) && request != REQ_VIEW_DIFF)
				? OPEN_SPLIT : OPEN_DEFAULT;
	struct view *diff = &diff_view;

	(void) line;
	switch (request) {
	case REQ_VIEW_DIFF:
	case REQ_ENTER:
		if (view_is_displayed(view) && display[0] != view)
			maximize_view(view, true);

		if (!view_is_displayed(diff) ||
		    strcmp(view->env->stash, diff->ref)) {
			const char *diff_argv[] = {
				"git", "stash", "show", "--encoding=UTF-8", "--pretty=fuller",
					"--root", "--patch-with-stat", use_mailmap_arg(),
					show_notes_arg(), diff_context_arg(),
					ignore_space_arg(), "%(diffargs)",
					"%(cmdlineargs)", "--no-color", "%(stash)",
					NULL
			};

			if (!argv_format(diff_view.env, &diff_view.argv, diff_argv, false, false))
				report("Failed to format argument");
			else
				open_diff_view(view, flags | OPEN_PREPARED);
		}
		return REQ_NONE;

	case REQ_REFRESH:
		refresh_view(view);
		return REQ_NONE;

	default:
		return request;
	}
}

static bool
stash_grep(struct view *view, struct line *line)
{
	struct stash_line *stash = line->data;
	const char *text[] = {
		stash->commit.title ? stash->commit.title : "",
		stash->commit.author ? stash->commit.author->name : "",
		stash->name,
		NULL
	};

	return grep_text(view, text);
}

static void
stash_done(struct view *view)
{
	size_t i;

	for (i = 0; i < view->lines; i++) {
		struct stash_line *stash = view->line[i].data;

		if (stash) {
			free(stash->commit.title);
			stash->commit.title = NULL;
		}
	}
}

static bool
stash_draw(struct view *view, struct line *line, unsigned int lineno)
{
	return view_column_draw(view, line, lineno);
}

static struct view_ops stash_ops = {
	"stash",
	argv_env.stash,
	VIEW_SEND_CHILD_ENTER | VIEW_REFRESH,
	0,
	stash_open,
	stash_read,
	stash_draw,
	stash_request,
	stash_grep,
	stash_select,
	stash_done,
	stash_get_column_data,
};

struct view stash_view = {
	"stash",
	&stash_ops,
	NULL,
	&argv_env,
};

void
open_stash_view(struct view *prev, enum open_flags flags)
{
	open_view(prev, &stash_view, flags);
}
