	string_copy_rev(view->ref, ref->id);
	string_copy_rev(view->env->commit, ref->id);
	string_copy_rev(view->env->head, ref->id);
	string_copy(view->env->refname, ref->name);
	string_copy(view->env->ref, ref->name);

	if (ref_is_remote(ref)) {
		char *slash = strchr(ref->name, '/');

		if (slash) {
			string_ncopy(view->env->remote, ref->name, slash - ref->name);
			string_copy(view->env->branch, slash + 1);
		}
		view->env->tag[0] = 0;
	} else if (ref_is_tag(ref)) {
		string_copy(view->env->tag, ref->name);
		view->env->branch[0] = 0;
		view->env->remote[0] = 0;
	} else {
		string_copy(view->env->branch, ref->name);
		view->env->tag[0] = 0;
		view->env->remote[0] = 0;
	}
}

static enum request
refs_request(struct view *view, enum request request, struct line *line)
{
	struct reference *reference = line->data;

	switch (request) {
	case REQ_REFRESH:
		load_refs(true);
		refresh_view(view);
		return REQ_NONE;

	case REQ_ENTER:
	{
		const struct ref *ref = reference->ref;
		extern bool main_prepare_argv(const char *rev, bool all);

		if (!main_prepare_argv(reference->is_all ? "--all" : ref->name, reference->is_all))
			report("Failed to format argument");
		else
			open_main_view(view, OPEN_SPLIT | OPEN_PREPARED);
		return REQ_NONE;
	}

	default:
		return request;
	}
}

static bool
refs_read(struct view *view, char *data, size_t len)
{
	char *author;
	char *committer;
	char *title;
	char *end = data ? data + len : NULL;
	size_t i;

	if (!data)
		return true;

	author = memchr(data, 0, len);
	if (!author)
		return true;
	author++;
	committer = author < end ? memchr(author, 0, end - author) : NULL;
	if (!committer)
		return true;
	committer++;
	title = committer < end ? memchr(committer, 0, end - committer) : NULL;
	if (!title)
		return true;
	title++;

	for (i = 0; i < view->lines; i++) {
		struct line *line = &view->line[i];
		struct reference *reference = line->data;
		char buf[SIZEOF_STR];

		if (reference->is_all || strncmp(reference->ref->id, data, SIZEOF_REV - 1))
			continue;

		string_copy(buf, author);
		parse_author_line(buf, &reference->author, &reference->time);
		string_copy(buf, committer);
		parse_author_line(buf, &reference->committer, &reference->ctime);
		free(reference->title);
		reference->title = xstrdup(title);
		view_column_info_update(view, line);
	}

	return true;
}

static bool
refs_open_visitor(void *data, const struct ref *ref)
{
	struct view *view = data;
	struct reference *reference;
	bool is_all = ref == refs_all;
	struct line *line;

	if (!is_all) {
		if (ref->type == REFERENCE_STASH || ref->type == REFERENCE_NOTE ||
		    ref->type == REFERENCE_PREFETCH || ref->type == REFERENCE_OTHER)
			return true;
		if (ref->type == REFERENCE_HEAD && !strcmp(ref->name, "HEAD") && !*repo.head)
			;
	}

	line = add_line_alloc(view, &reference, LINE_DEFAULT, 0, is_all);
	if (!line)
		return false;

	reference->ref = ref;
	reference->is_all = is_all;
	view_column_info_update(view, line);

	return true;
}

static void
refs_done(struct view *view)
{
	size_t i;

	for (i = 0; i < view->lines; i++) {
		struct reference *reference = view->line[i].data;

		if (reference) {
			free(reference->title);
			reference->title = NULL;
		}
	}
}

static enum status_code
refs_open(struct view *view, enum open_flags flags)
{
	const char *refs_log[] = {
		"git", "log", "--encoding=UTF-8", "--no-color", "--date=raw",
			opt_mailmap ? "--pretty=format:%H%x00%aN <%aE> %ad%x00%cN <%cE> %cd%x00%s"
				    : "--pretty=format:%H%x00%an <%ae> %ad%x00%cn <%ce> %cd%x00%s",
			"--all", "--simplify-by-decoration", NULL
	};

	(void) flags;
	refs_done(view);
	if (!begin_update(view, NULL, refs_log, OPEN_RELOAD))
		return error("Failed to open refs view");

	view_column_reset(view);
	refs_open_visitor(view, get_refs_all());
	foreach_ref(refs_open_visitor, view);
	refs_sort.initialized = false;

	return SUCCESS;
}

static bool
refs_grep(struct view *view, struct line *line)
{
	struct reference *reference = line->data;
	const char *text[] = {
		reference->ref->name,
		reference->author ? reference->author->name : "",
		reference->title ? reference->title : "",
		NULL
	};

	(void) view;
	return grep_text(view, text);
}

