/* ------------------------------------------------------------------ */
/* Sorting of refs and tree views */

static struct view *sorting_view;
static struct sort_state *sorting_state;

static int
sort_order(struct sort_state *state, int result)
{
	return state->reverse ? -result : result;
}

static int
ident_compare(const struct ident *i1, const struct ident *i2)
{
	if (!i1 || !i2)
		return (!!i1) - (!!i2);
	if (!i1->name || !i2->name)
		return (!!i1->name) - (!!i2->name);
	return strcmp(i1->name, i2->name);
}

static int
timecmp(const struct time *t1, const struct time *t2)
{
	if (!t1 || !t2)
		return (!!t1) - (!!t2);
	return t1->sec < t2->sec ? -1 : t1->sec > t2->sec ? 1 : 0;
}

static int
sort_view_compare(const void *l1, const void *l2)
{
	const struct line *line1 = l1;
	const struct line *line2 = l2;
	struct view_column_data d1 = {0}, d2 = {0};
	int result = 0;

	sorting_view->ops->get_column_data(sorting_view, line1, &d1);
	sorting_view->ops->get_column_data(sorting_view, line2, &d2);

	if (sorting_view == &tree_view) {
		if (line1->type == LINE_HEADER)
			return -1;
		if (line2->type == LINE_HEADER)
			return 1;
		if (d1.file_name && !strcmp(d1.file_name, ".."))
			return -1;
		if (d2.file_name && !strcmp(d2.file_name, ".."))
			return 1;
	}

	switch (sorting_state->field) {
	case VIEW_COLUMN_AUTHOR:
		result = ident_compare(d1.author, d2.author);
		break;
	case VIEW_COLUMN_COMMITTER:
		result = ident_compare(d1.committer, d2.committer);
		break;
	case VIEW_COLUMN_DATE:
		result = timecmp(d1.date, d2.date);
		break;
	case VIEW_COLUMN_COMMIT_TITLE:
		result = strcmp(d1.commit_title ? d1.commit_title : "", d2.commit_title ? d2.commit_title : "");
		break;
	case VIEW_COLUMN_FILE_NAME:
		if (line1->type != line2->type)
			result = line1->type == LINE_DIRECTORY ? -1 : 1;
		else
			result = strcmp(d1.file_name ? d1.file_name : "", d2.file_name ? d2.file_name : "");
		break;
	case VIEW_COLUMN_FILE_SIZE:
		result = (d1.file_size ? (long) *d1.file_size : -1) - (d2.file_size ? (long) *d2.file_size : -1);
		result = result < 0 ? -1 : result > 0;
		break;
	case VIEW_COLUMN_MODE:
		result = (d1.mode ? (int) *d1.mode : 0) - (d2.mode ? (int) *d2.mode : 0);
		break;
	case VIEW_COLUMN_REF:
		if (d1.ref && d2.ref) {
			if (d1.ref == refs_all || d2.ref == refs_all)
				result = d1.ref == refs_all ? -1 : 1;
			else
				result = ref_compare(d1.ref, d2.ref);
		}
		break;
	case VIEW_COLUMN_LINE_NUMBER:
	default:
		result = (long) line1->lineno - (long) line2->lineno;
		if (sorting_view == &refs_view) {
			const struct reference *r1 = line1->data, *r2 = line2->data;

			if (r1->is_all || r2->is_all)
				result = r1->is_all ? -1 : 1;
			else
				result = ref_compare(r1->ref, r2->ref);
		}
		break;
	}

	return sort_order(sorting_state, result);
}

static bool
column_is_sortable(enum view_column_type type)
{
	return type != VIEW_COLUMN_ID && type != VIEW_COLUMN_SECTION && type != VIEW_COLUMN_TEXT &&
	       type != VIEW_COLUMN_STATUS;
}

void
sort_view_request(struct view *view, bool change_field, char *msg, size_t msgsize)
{
	struct sort_state *state = view == &tree_view ? &tree_sort_state : &refs_sort;
	struct view_column *column;
	size_t i;

	if (!view->columns)
		view_column_reset(view);

	if (!state->initialized) {
		state->field = view == &refs_view ? VIEW_COLUMN_REF : VIEW_COLUMN_LINE_NUMBER;
		state->initialized = true;
	}

	if (change_field) {
		struct view_column *current = get_view_column(view, state->field);
		struct view_column *next;

		next = current ? current->next : view->columns;
		while (true) {
			if (!next)
				next = view->columns;
			if (column_is_sortable(next->type))
				break;
			next = next->next;
		}
		state->field = next->type;
		snprintf(msg, msgsize, "set sort-field = %s", view_column_type_name(state->field));
	} else {
		state->reverse = !state->reverse;
		snprintf(msg, msgsize, "set sort-order = %s", state->reverse ? "descending" : "ascending");
	}

	sorting_view = view;
	sorting_state = state;
	{
		struct line *selected = view->lines ? &view->line[view->pos.lineno] : NULL;
		void *selected_data = selected ? selected->data : NULL;
		unsigned long *linenos = xcalloc(view->lines + 1, sizeof(*linenos));

		for (i = 0; i < view->lines; i++)
			linenos[i] = view->line[i].lineno;
		qsort(view->line, view->lines, sizeof(*view->line), sort_view_compare);
		(void) linenos;
		free(linenos);
		for (i = 0; i < view->lines; i++)
			if (view->line[i].data == selected_data) {
				view->pos.lineno = i;
				break;
			}
		(void) column;
	}
	redraw_view(view);
}

