/* Stash view */

struct stash_state {
	char **names;
	size_t names_count;
};

struct stash_commit {
	struct commit commit;
};

static enum status_code
stash_open(struct view *view, enum open_flags flags)
{
	const char *stash_argv[] = { "git", "stash", "list", "--encoding=UTF-8", "--no-color",
		opt_mailmap ? "--pretty=format:%H %P%x00%aN <%aE> %at %ai%x00%cN <%cE> %ct %ci%x00%s%x00%gd"
			    : "--pretty=format:%H %P%x00%an <%ae> %at %ai%x00%cn <%ce> %ct %ci%x00%s%x00%gd",
		NULL };

	view_column_reset(view);
	if (!begin_update(view, NULL, stash_argv, flags | OPEN_RELOAD))
		return error("Failed to open stash view");
	return SUCCESS;
}

struct stash_line {
	struct commit commit;
	char name[SIZEOF_REF];
};

static void
parse_iso_ident(char *ident, const struct ident **author, struct time *time)
{
	char *emailend = strchr(ident, '>');
	size_t len = strlen(ident);

	if (emailend && len > 6) {
		char zone[8];
		char *secs = emailend + 2;

		string_copy(zone, ident + len - 5);
		*(emailend + 1) = 0;
		parse_author_line(ident, author, NULL);
		parse_timesec(time, secs);
		parse_timezone(time, zone);
	} else {
		parse_author_line(ident, author, time);
	}
}

static bool
stash_read(struct view *view, char *data, size_t len)
{
	char *fields[5] = {0};
	char *end;
	char *p;
	int n = 0;
	struct stash_line *stash;
	struct line *line;

	if (!data) {
		if (!view->lines && !view->prev && view == display[0])
			die("No revisions match the given arguments.");
		return true;
	}

	end = data + len;
	p = data + strlen(data) + 1;
	while (p < end && n < 5) {
		fields[n++] = p;
		p += strlen(p) + 1;
	}

	line = add_line_alloc(view, &stash, LINE_MAIN_COMMIT, 0, false);
	if (!line)
		return false;
	string_copy_rev(stash->commit.id, data);
	if (fields[0])
		parse_iso_ident(fields[0], &stash->commit.author, &stash->commit.time);
	if (fields[1])
		parse_iso_ident(fields[1], &stash->commit.committer, &stash->commit.ctime);
	stash->commit.title = xstrdup(fields[2] ? fields[2] : "");
	string_copy(stash->name, fields[3] ? fields[3] : "");
	view_column_info_update(view, line);
	return true;
}

static bool
stash_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	struct stash_line *stash = line->data;
	struct view_column *date = get_view_column(view, VIEW_COLUMN_DATE);

	column_data->author = stash->commit.author;
	column_data->committer = stash->commit.committer;
	column_data->date = date && date->opt.use_author ? &stash->commit.time : &stash->commit.ctime;
	column_data->id = stash->commit.id;
	column_data->reflog = stash->name;
	column_data->commit_title = stash->commit.title;
	return true;
}

static void
stash_select(struct view *view, struct line *line)
{
	struct stash_line *stash = line->data;

	string_copy(view->ref, stash->name);
	string_copy(view->env->stash, stash->name);
	string_copy_rev(view->env->commit, stash->commit.id);
}

static enum request
stash_request(struct view *view, enum request request, struct line *line)
{
	enum open_flags flags = (view_is_displayed(view) && request != REQ_VIEW_DIFF)
				? OPEN_SPLIT : OPEN_DEFAULT;
	struct view *diff = &diff_view;

	(void) line;
	switch (request) {
	case REQ_VIEW_DIFF:
	case REQ_ENTER:
		if (view_is_displayed(view) && display[0] != view)
			maximize_view(view, true);

		if (!view_is_displayed(diff) ||
		    strcmp(view->env->stash, diff->ref)) {
			const char *diff_argv[] = {
				"git", "stash", "show", "--encoding=UTF-8", "--pretty=fuller",
					"--root", "--patch-with-stat", use_mailmap_arg(),
					show_notes_arg(), diff_context_arg(),
					ignore_space_arg(), "%(diffargs)",
					"%(cmdlineargs)", "--no-color", "%(stash)",
					NULL
			};

			if (!argv_format(diff_view.env, &diff_view.argv, diff_argv, false, false))
				report("Failed to format argument");
			else
				open_diff_view(view, flags | OPEN_PREPARED);
		}
		return REQ_NONE;

	case REQ_REFRESH:
		refresh_view(view);
		return REQ_NONE;

	default:
		return request;
	}
}

static bool
stash_grep(struct view *view, struct line *line)
{
	struct stash_line *stash = line->data;
	const char *text[] = {
		stash->commit.title ? stash->commit.title : "",
		stash->commit.author ? stash->commit.author->name : "",
		stash->name,
		NULL
	};

	return grep_text(view, text);
}

static void
stash_done(struct view *view)
{
	size_t i;

	for (i = 0; i < view->lines; i++) {
		struct stash_line *stash = view->line[i].data;

		if (stash) {
			free(stash->commit.title);
			stash->commit.title = NULL;
		}
	}
}

static bool
stash_draw(struct view *view, struct line *line, unsigned int lineno)
{
	return view_column_draw(view, line, lineno);
}

static struct view_ops stash_ops = {
	"stash",
	argv_env.stash,
	VIEW_SEND_CHILD_ENTER | VIEW_REFRESH,
	0,
	stash_open,
	stash_read,
	stash_draw,
	stash_request,
	stash_grep,
	stash_select,
	stash_done,
	stash_get_column_data,
};

struct view stash_view = {
	"stash",
	&stash_ops,
	NULL,
	&argv_env,
};

void
open_stash_view(struct view *prev, enum open_flags flags)
{
	open_view(prev, &stash_view, flags);
}
