	char *lines[16] = {0};
	int n = 0, i;
	char *pos;

	(void) read_repo_info_line;
	memset(&repo, 0, sizeof(repo));
	if (!out)
		return;

	for (pos = out; n < 16 && pos < out + len; ) {
		char *eol = strchr(pos, '\\n');

		if (!eol)
			eol = out + len;
		*eol = 0;
		lines[n++] = pos;
		pos = eol + 1;
	}

	if (n < 2) {
		free(out);
		return;
	}

