			i++;
	}

	for (; i < n; i++) {
		if (iscommit(lines[i]) && strlen(lines[i]) == SIZEOF_REV - 1)
			string_copy(repo.head_id, lines[i]);
		else if (!prefixcmp(lines[i], "refs/heads/"))
