	struct blame *blame = line->data;
	struct blame_state *state = view->private;

	switch (request) {
	case REQ_VIEW_BLAME:
	case REQ_PARENT:
		if (!blame->commit) {
			report("Commit data not loaded yet");
			break;
		}
		if (!strcmp(blame->commit->id, NULL_ID) || !blame->commit->has_previous) {
			if (request == REQ_VIEW_BLAME && !strcmp(blame->commit->id, NULL_ID))
				break;
			report("The selected commit has no parents with this file");
			break;
		}
		string_copy_rev(view->env->ref, blame->commit->parent_id);
		string_copy(view->env->file, blame->commit->parent_filename);
		view->env->goto_lineno = blame->lineno - 1;
		(void) state;
		reload_view(view);
		break;

	case REQ_ENTER:
		if (!blame->commit) {
			report("Commit data not loaded yet");
			break;
		}

		if (view_is_displayed(&diff_view) &&
		    !strcmp(blame->commit->id, diff_view.vid))
			break;

		if (!strcmp(blame->commit->id, NULL_ID)) {
			const char *diff_argv[] = {
				"git", "diff", "--encoding=UTF-8", "--patch-with-stat", "--stat=%(width)",
				diff_context_arg(), ignore_space_arg(), "--no-color", "--", "%(file)", NULL
			};
			struct view *diff = &diff_view;

			diff_set_goto(blame->commit->filename, blame->lineno);
			if (argv_format(view->env, &diff->argv, diff_argv, false, false))
				open_view(view, diff, flags | OPEN_PREPARED);
		} else {
			diff_set_goto(blame->commit->filename, blame->lineno);
			open_diff_view(view, flags);
		}
		break;

	case REQ_REFRESH:
		reload_view(view);
		break;

	default:
		return request;
	}

	return REQ_NONE;
}

