			string_copy(state->current->parent_filename, line + SIZEOF_REV);
			state->current->has_previous = true;
		}

	} else if (match_blame_header("filename ", &line)) {
		string_copy(state->current->filename, line);
	}

	return true;
}

static bool
blame_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	struct blame_state *state = view->private;
	struct blame *blame = line->data;
	struct view_column *date = get_view_column(view, VIEW_COLUMN_DATE);

	if (blame->commit) {
		column_data->id = blame->commit->id;
		column_data->author = blame->commit->author;
		column_data->date = date && date->opt.use_author ? &blame->commit->time : &blame->commit->ctime;
		if (!blame->commit->ctime.sec)
			column_data->date = &blame->commit->time;
		if (state->auto_filename_display)
			column_data->file_name = blame->commit->filename;
	}

	column_data->line_number = &blame->lineno;
	column_data->text = blame->text;

	return true;
}

static bool
blame_draw(struct view *view, struct line *line, unsigned int lineno)
{
	return view_column_draw(view, line, lineno);
}

static bool
blame_grep(struct view *view, struct line *line)
{
	struct blame *blame = line->data;
	struct blame_commit *commit = blame->commit;
	const char *text[] = {
		blame->text,
		commit ? commit->title : "",
		commit ? commit->id : "",
		commit && commit->author ? commit->author->name : "",
		NULL
	};

	return grep_text(view, text);
}

static void
blame_select(struct view *view, struct line *line)
{
	struct blame *blame = line->data;
	struct blame_commit *commit = blame->commit;

	if (!commit)
		return;

	if (!strcmp(commit->id, NULL_ID)) {
		string_ncopy(view->env->commit, "HEAD", 4);
		string_copy(view->ref, commit->filename);
	} else {
		string_copy_rev(view->env->commit, commit->id);
		string_format(view->ref, "%s:%s", commit->id, commit->filename);
	}

	string_copy(view->env->file, commit->filename);
	view->env->lineno = blame->lineno;
}

extern void diff_set_goto(const char *file, unsigned long lineno);

static enum request
blame_request(struct view *view, enum request request, struct line *line)
{
	enum open_flags flags = view_is_displayed(view) ? OPEN_SPLIT : OPEN_DEFAULT;
	struct blame *blame = line->data;
	struct blame_state *state = view->private;

	switch (request) {
	case REQ_VIEW_BLAME:
	case REQ_PARENT:
		if (!blame->commit) {
			report("Commit data not loaded yet");
			break;
		}
		if (!strcmp(blame->commit->id, NULL_ID) || !blame->commit->has_previous) {
			if (request == REQ_VIEW_BLAME && !strcmp(blame->commit->id, NULL_ID))
				break;
			report("The selected commit has no parents with this file");
			break;
		}
		string_copy_rev(view->env->ref, blame->commit->parent_id);
		string_copy(view->env->file, blame->commit->parent_filename);
		view->env->goto_lineno = blame->lineno - 1;
		(void) state;
		reload_view(view);
		break;

	case REQ_ENTER:
		if (!blame->commit) {
			report("Commit data not loaded yet");
			break;
		}

		if (view_is_displayed(&diff_view) &&
		    !strcmp(blame->commit->id, diff_view.vid))
			break;

		if (!strcmp(blame->commit->id, NULL_ID)) {
			const char *diff_argv[] = {
				"git", "diff", "--encoding=UTF-8", "--patch-with-stat", "--stat=%(width)",
				diff_context_arg(), ignore_space_arg(), "--no-color", "--", "%(file)", NULL
			};
			struct view *diff = &diff_view;

			diff_set_goto(blame->commit->filename, blame->lineno);
			if (argv_format(view->env, &diff->argv, diff_argv, false, false))
				open_view(view, diff, flags | OPEN_PREPARED);
		} else {
			diff_set_goto(blame->commit->filename, blame->lineno);
			open_diff_view(view, flags);
		}
		break;

	case REQ_REFRESH:
		reload_view(view);
		break;

	default:
		return request;
	}

	return REQ_NONE;
}

static struct view_ops blame_ops = {
	"line",
	argv_env.file,
	VIEW_ALWAYS_LINENO | VIEW_BLAME_LIKE | VIEW_REFRESH | VIEW_HAS_ID,
