static bool
grep_read(struct view *view, char *data, size_t len)
{
	struct grep_state *state = view->private;
	struct grep_line *grep;
	char *lineno, *text;
	struct line *line;
	char *end = data ? data + len : NULL;

	if (!data) {
		state->last_file[0] = 0;
		if (!view->lines) {
			view->ref[0] = 0;
			report("No matches found");
		}
		return true;
	}

	if (!strcmp(data, "--"))
		return true;

	lineno = memchr(data, 0, len);
	if (!lineno || lineno + 1 >= end)
		return true;
	lineno++;
	text = memchr(lineno, 0, end - lineno);
	if (!text)
		return true;
	text++;

	if (strcmp(state->last_file, data)) {
		line = add_line_alloc(view, &grep, LINE_FILE, 0, false);
		if (!line)
			return false;
		string_copy(grep->file, data);
		grep->is_file = true;
		string_copy(state->last_file, data);
	}

	{
		size_t textlen = strlen(text);
		char expanded[SIZEOF_MED_STR];

		string_expand(expanded, sizeof(expanded), text, textlen, opt_tab_size);
		textlen = strlen(expanded);
		line = add_line_alloc(view, &grep, LINE_DEFAULT, textlen, false);
		if (!line)
			return false;
		string_copy(grep->file, data);
		grep->lineno = atoi(lineno);
		memcpy(grep->text, expanded, textlen);
		grep->text[textlen] = 0;
		view_column_info_update(view, line);
	}

	return true;
}

