	switch (request) {
	case REQ_REFRESH:
		refresh_view(view);
		return REQ_NONE;

	case REQ_ENTER:
		if (!*grep->file)
			return REQ_NONE;
		if (file_view->parent == view && file_view->prev == view &&
		    !strcmp(state->opened_file, grep->file) && view_is_displayed(file_view)) {
			if (grep->lineno)
				select_view_line(file_view, grep->lineno - 1);
			update_view_title(file_view);

		} else {
			extern void open_blob_file_view(struct view *prev, const char *file, unsigned long lineno, enum open_flags flags);

			open_blob_file_view(view, grep->file, grep->lineno, OPEN_SPLIT | OPEN_RELOAD);
		}
		string_copy(state->opened_file, grep->file);
		return REQ_NONE;

	case REQ_EDIT:
		if (!*grep->file)
			return request;
		open_editor(grep->file, grep->lineno);
		return REQ_NONE;

	case REQ_VIEW_BLAME:
		view->env->ref[0] = 0;
		view->env->goto_lineno = grep->lineno;
		return request;

	default:
		return request;
	}
