			opt_cmdline_args = NULL;
			argv_append_array(&opt_cmdline_args, argv);
		}
	}

	open_view(prev, view, OPEN_DEFAULT | OPEN_RELOAD);
}

bool
is_initial_grep_view(void)
{
	return true;
}
