static bool
finder_draw(struct view *view, struct line *line, unsigned int lineno)
{
	struct finder_line *fl = line->data;
	const char *path = fl->path;
	size_t pos = 0, m = 0;
	size_t len = strlen(path);

	(void) lineno;
	while (pos < len) {
		bool matched = m < fl->matches && fl->match[m] == pos;
		size_t run = 0;

		if (matched) {
			while (m < fl->matches && fl->match[m] == pos + run) {
				m++;
				run++;
			}
			set_view_attr(view, LINE_DEFAULT);
			wattron(view->win, A_REVERSE);
			if (draw_textn(view, LINE_DEFAULT, path + pos, run)) {
				wattroff(view->win, A_REVERSE);
				return true;
			}
			wattroff(view->win, A_REVERSE);
		} else {
			size_t next = m < fl->matches ? fl->match[m] : len;

			run = next - pos;
			if (draw_textn(view, LINE_DEFAULT, path + pos, run))
				return true;
		}
		pos += run;
	}
	return true;
}

