					finder_state.files = xrealloc(finder_state.files, sizeof(char *) * (finder_state.files_count + 1));
					finder_state.files[finder_state.files_count++] = xstrndup(pos, n);
				}
				pos += n + 1;
			}
			free(out);
		}
	}

	finder_refilter(view);
	view->vid[0] = 0;
	return SUCCESS;
}

static bool
finder_read(struct view *view, char *line, size_t len)
{
	(void) view;
	(void) line;
	(void) len;
	return true;
}

static bool
finder_draw(struct view *view, struct line *line, unsigned int lineno)
{
	struct finder_line *fl = line->data;
	const char *path = fl->path;
	size_t pos = 0, m = 0;
	size_t len = strlen(path);

	(void) lineno;
	while (pos < len) {
		bool matched = m < fl->matches && fl->match[m] == pos;
		size_t run = 0;

		if (matched) {
			while (m < fl->matches && fl->match[m] == pos + run) {
				m++;
				run++;
			}
			set_view_attr(view, LINE_DEFAULT);
			wattron(view->win, A_REVERSE);
			if (draw_textn(view, LINE_DEFAULT, path + pos, run)) {
				wattroff(view->win, A_REVERSE);
				return true;
			}
			wattroff(view->win, A_REVERSE);
		} else {
			size_t next = m < fl->matches ? fl->match[m] : len;

			run = next - pos;
			if (draw_textn(view, LINE_DEFAULT, path + pos, run))
				return true;
		}
		pos += run;
	}
	return true;
}

static enum request
finder_request(struct view *view, enum request request, struct line *line)
{
	(void) view;
	(void) line;
	return request;
}

static bool
finder_grep(struct view *view, struct line *line)
{
	struct finder_line *fl = line->data;
	const char *text[] = { fl->path, NULL };

	return grep_text(view, text);
}

static void
finder_select(struct view *view, struct line *line)
{
	(void) view;
	(void) line;
}

static bool
finder_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	struct finder_line *fl = line->data;

	(void) view;
	column_data->file_name = fl->path;
	return true;
}

static struct view_ops finder_ops = {
	"file",
	"",
	VIEW_NO_FLAGS,
	0,
	finder_open,
	finder_read,
	finder_draw,
	finder_request,
	finder_grep,
	finder_select,
	NULL,
	finder_get_column_data,
};

struct view finder_view = {
	"finder",
	&finder_ops,
	NULL,
	&argv_env,
};

static void
finder_move(struct view *view, int steps)
{
	long lineno = (long) view->pos.lineno + steps;

	if (!view->lines)
		return;
	if (lineno < 0)
		lineno = 0;
	if (lineno >= (long) view->lines)
		lineno = view->lines - 1;
	if ((unsigned long) lineno == view->pos.lineno)
		return;
	if (lineno < (long) view->pos.offset)
		view->pos.offset = lineno;
	else if (lineno >= (long) (view->pos.offset + view->height))
		view->pos.offset = lineno - view->height + 1;
	view->pos.lineno = lineno;
}

extern char *finder_prompt_key(struct key *key);

void
open_finder_view(struct view *prev)
{
	struct view *view = &finder_view;
	char msg[SIZEOF_STR];
	struct key key;
	size_t searchlen = 0;

	view->keymap = get_keymap("generic", 7);
	clear_position(&view->pos);
	open_view(prev, view, OPEN_RELOAD);
	if (!view_is_displayed(view))
		return;

	input_mode = true;
	while (true) {
		const char *prompt = "Find file: ";

		snprintf(msg, sizeof(msg), "%s%s", prompt, finder_state.search);
		werase(status_win);
		wmove(status_win, 0, 0);
		waddstr(status_win, msg);
		wclrtoeol(status_win);
		wnoutrefresh(status_win);
		redraw_view(view);
		update_view_title(view);

		get_input(strlen(msg), &key);

		if (key.value == KEY_RETURN || key.value == KEY_ENTER || (key.control && key.value == 'j')) {
			input_mode = false;
			if (view->lines) {
				struct finder_line *fl = view->line[view->pos.lineno].data;
				char spec[SIZEOF_STR * 2];
				const char *commit = *view->env->commit ? view->env->commit : "HEAD";
				const char *rev_parse_argv[] = { "git", "rev-parse", spec, NULL };

				string_copy(view->env->file, fl->path);
				snprintf(spec, sizeof(spec), "%s:%s", commit, fl->path);
				if (!io_run_buf(rev_parse_argv, view->env->blob, sizeof(view->env->blob), NULL, false))
					view->env->blob[0] = 0;
				werase(status_win);
				wnoutrefresh(status_win);
				view->prev = view->prev ? view->prev : prev;
				open_view(view->prev && view->prev != view ? view->prev : prev, &blob_view, OPEN_DEFAULT | OPEN_RELOAD);
				blob_view.prev = view->prev && view->prev != view ? view->prev : prev;
			} else {
				werase(status_win);
				wnoutrefresh(status_win);
				maximize_view(view->prev && view->prev != view ? view->prev : prev, true);
			}
			view->prev = view;
			return;
		}

		if (key.value == KEY_ESC || (key.control && (key.value == 'c' || key.value == 'g'))) {
			break;
		}

		if (key.value == KEY_BACKSPACE || (key.control && key.value == 'h')) {
			if (!searchlen)
				break;
			searchlen--;
			while (searchlen > 0 && (finder_state.search[searchlen] & 0xc0) == 0x80)
				searchlen--;
			finder_state.search[searchlen] = 0;
			finder_refilter(view);
			continue;
		}

		switch (key.value) {
		case KEY_UP:
			finder_move(view, -1);
			continue;
		case KEY_DOWN:
			finder_move(view, 1);
			continue;
		case KEY_PPAGE:
			finder_move(view, -view->height);
			continue;
		case KEY_NPAGE:
			finder_move(view, view->height);
			continue;
		case KEY_HOME:
			finder_move(view, -(long) view->lines);
			continue;
		case KEY_END:
			finder_move(view, view->lines);
			continue;
		default:
			break;
		}

		if (key.control) {
			if (key.value == 'p')
				finder_move(view, -1);
			else if (key.value == 'n')
				finder_move(view, 1);
			continue;
		}

		if (*key.bytes && !key.escape) {
			size_t n = strlen(key.bytes);

			if (searchlen + n < sizeof(finder_state.search) - 1) {
				memcpy(finder_state.search + searchlen, key.bytes, n);
				searchlen += n;
				finder_state.search[searchlen] = 0;
				finder_refilter(view);
			}
		}
	}

	input_mode = false;
	werase(status_win);
	wnoutrefresh(status_win);
	maximize_view(view->prev && view->prev != view ? view->prev : prev, true);
	view->prev = view;
}
